import { Container, Graphics, Text, TextStyle } from 'pixi.js';
import { GameScene, SceneManager } from './SceneManager';
import { GameState } from '../state/GameState';
import { WorldMapScene } from './WorldMapScene';
import { UIHelper } from '../engine/UIHelper';
import { SoundSynth } from '../audio/SoundSynth';
import { ParticleSystem } from '../engine/ParticleSystem';
import { MusicPlayer } from '../audio/MusicPlayer';

export class ParentDashboardScene extends Container implements GameScene {
  private screenW: number = 800;
  private screenH: number = 600;

  private bgGfx: Graphics;
  private headerContainer: Container;
  private statsContainer: Container;
  private modalContainer: Container;

  constructor() {
    super();
    this.bgGfx = new Graphics();
    this.headerContainer = new Container();
    this.statsContainer = new Container();
    this.modalContainer = new Container();

    this.addChild(this.bgGfx);
    this.addChild(this.statsContainer);
    this.addChild(this.headerContainer);
    this.addChild(this.modalContainer);
  }

  onEnter() {
    MusicPlayer.playTheme('sanctuary');
    this.renderAll();
  }

  resize(w: number, h: number) {
    this.screenW = w;
    this.screenH = h;
    this.renderAll();
  }

  private renderAll() {
    this.renderBackground();
    this.renderHeader();
    this.renderStats();
  }

  private renderBackground() {
    const w = this.screenW;
    const h = this.screenH;

    this.bgGfx.clear();
    this.bgGfx.rect(0, 0, w, h);
    this.bgGfx.fill({ color: 0x0E132B });

    for (let x = 0; x < w; x += 40) {
      this.bgGfx.moveTo(x, 0);
      this.bgGfx.lineTo(x, h);
    }
    for (let y = 0; y < h; y += 40) {
      this.bgGfx.moveTo(0, y);
      this.bgGfx.lineTo(w, y);
    }
    this.bgGfx.stroke({ width: 0.5, color: 0x1D2652 });
  }

  private renderHeader() {
    this.headerContainer.removeChildren();
    const w = this.screenW;

    const topBar = new Graphics();
    topBar.rect(0, 0, w, 56);
    topBar.fill({ color: 0x151B3B, alpha: 0.98 });
    topBar.stroke({ width: 1.5, color: 0x2A3568 });
    this.headerContainer.addChild(topBar);

    const backBtn = UIHelper.createButton('◀ Galaxy Map', 110, 32, 0x6C5CE7, '#FFFFFF', 12, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    backBtn.x = 70;
    backBtn.y = 28;
    this.headerContainer.addChild(backBtn);

    const title = new Text({
      text: '📊 Pittsburgh Public Schools Learning Report',
      style: new TextStyle({ fontSize: 15, fontWeight: 'bold', fill: '#00D2D3' })
    });
    title.anchor.set(0.5);
    title.x = w / 2;
    title.y = 28;
    this.headerContainer.addChild(title);
  }

  private renderStats() {
    this.statsContainer.removeChildren();
    const w = this.screenW;
    const h = this.screenH;
    const state = GameState.getInstance();
    const p = state.progress;

    let totalProblems = 0;
    let totalCorrect = 0;
    Object.values(p.standardsMastery).forEach((m) => {
      totalProblems += m.total;
      totalCorrect += m.correct;
    });

    const cardW = Math.min(540, w - 30);
    const summaryCard = new Graphics();
    summaryCard.roundRect((w - cardW) / 2, 70, cardW, 80, 16);
    summaryCard.fill({ color: 0x1A2248, alpha: 0.95 });
    summaryCard.stroke({ width: 2, color: 0x00D2D3 });
    this.statsContainer.addChild(summaryCard);

    const sumText = new Text({
      text: `Student: ${p.playerName}  |  🔥 Streak: ${p.streakDays} Days\nProblems Solved: ${totalProblems}  |  Accuracy: ${totalProblems > 0 ? Math.round((totalCorrect / totalProblems) * 100) : 0}%  |  ⭐ Stars: ${state.getTotalStars()}`,
      style: new TextStyle({ fontSize: 13, fill: '#FFFFFF', align: 'center', lineHeight: 22 })
    });
    sumText.anchor.set(0.5);
    sumText.x = w / 2;
    sumText.y = 110;
    this.statsContainer.addChild(sumText);

    const domains = [
      { code: '2.OA', name: 'Operations & Algebraic Thinking (Addition & Subtraction to 20/100)' },
      { code: '2.NBT', name: 'Numbers & Base Ten (Place Value, 2/3-Digit Regrouping to 1000)' },
      { code: '2.MD', name: 'Measurement & Data (Steel City Coins, Duquesne Incline Clocks)' },
      { code: '2.G', name: 'Geometry & Equal Shares (Polygons, 3D Solids, Halves/Thirds/Fourths)' },
      { code: '3.OA', name: 'PPS Gifted Multiplication & Division (Times Tables 0-10, Word Problems)' },
      { code: 'GIFTED', name: 'Gifted Pre-Algebra & Logic (Number Patterns, Balance Equations)' }
    ];

    let startY = 165;
    const barW = cardW - 40;

    domains.forEach((d) => {
      const stat = p.standardsMastery[d.code];
      const mastery = stat && stat.total > 0 ? Math.round((stat.correct / stat.total) * 100) : 0;

      const dName = new Text({
        text: `${d.code}: ${d.name}`,
        style: new TextStyle({ fontSize: 11, fontWeight: 'bold', fill: '#A4B0BE' })
      });
      dName.x = (w - cardW) / 2 + 20;
      dName.y = startY;
      this.statsContainer.addChild(dName);

      const track = new Graphics();
      track.roundRect((w - cardW) / 2 + 20, startY + 16, barW, 12, 6);
      track.fill({ color: 0x222B59 });
      track.stroke({ width: 1, color: 0x3D4A88 });

      const fillW = Math.max(8, barW * (mastery / 100));
      track.roundRect((w - cardW) / 2 + 20, startY + 16, fillW, 12, 6);
      track.fill({ color: mastery >= 80 ? 0x2ED573 : mastery >= 50 ? 0xFFA502 : 0x70A1FF });
      this.statsContainer.addChild(track);

      const pct = new Text({
        text: `${mastery}%`,
        style: new TextStyle({ fontSize: 10, fontWeight: 'bold', fill: '#FFFFFF' })
      });
      pct.anchor.set(1, 0.5);
      pct.x = (w - cardW) / 2 + 20 + barW;
      pct.y = startY + 8;
      this.statsContainer.addChild(pct);

      startY += 44;
    });

    if (totalProblems > 0) {
      const certBtn = UIHelper.createButton('📜 View Mastery Certificate', 210, 42, 0xF1C40F, '#1E272E', 13, () => {
        this.showCertificateModal();
      });
      certBtn.x = w / 2 - 115;
      certBtn.y = h - 45;
      this.statsContainer.addChild(certBtn);
    }

    const resetBtn = UIHelper.createButton('🔄 Reset Progress', 150, 42, 0xFF4757, '#FFFFFF', 12, () => {
      if (confirm('Reset all math stars and coins?')) {
        state.resetProgress();
        this.renderAll();
      }
    });
    resetBtn.x = w / 2 + 95;
    resetBtn.y = h - 45;
    this.statsContainer.addChild(resetBtn);
  }

  private showCertificateModal() {
    this.modalContainer.removeChildren();
    const w = this.screenW;
    const h = this.screenH;
    const state = GameState.getInstance();

    const mw = Math.min(520, w - 30);
    const mh = 380;
    const mx = (w - mw) / 2;
    const my = (h - mh) / 2;

    const modal = new Container();

    const bg = new Graphics();
    bg.roundRect(mx, my, mw, mh, 16);
    bg.fill({ color: 0xFDFBF7 });
    bg.stroke({ width: 5, color: 0xF1C40F });

    bg.roundRect(mx + 10, my + 10, mw - 20, mh - 20, 10);
    bg.stroke({ width: 2, color: 0xD4AF37 });

    const certTitle = new Text({
      text: '★ CERTIFICATE OF MATH MASTERY ★',
      style: new TextStyle({ fontSize: 18, fontWeight: 'bold', fill: '#B7791F', align: 'center' })
    });
    certTitle.anchor.set(0.5);
    certTitle.x = mx + mw / 2;
    certTitle.y = my + 42;

    const certSubtitle = new Text({
      text: 'Pittsburgh Public Schools 2nd Grade Curriculum',
      style: new TextStyle({ fontSize: 12, fill: '#4A5568', align: 'center' })
    });
    certSubtitle.anchor.set(0.5);
    certSubtitle.x = mx + mw / 2;
    certSubtitle.y = my + 70;

    const certBody = new Text({
      text: `This certifies that\n\n⭐ ${state.progress.playerName} ⭐\n\nhas demonstrated outstanding math problem solving,\nmastering Operations & Algebraic Thinking, Measurement,\nSteel City Coins & Time, and Geometry!`,
      style: new TextStyle({ fontSize: 13, fill: '#2D3748', align: 'center', lineHeight: 22 })
    });
    certBody.anchor.set(0.5);
    certBody.x = mx + mw / 2;
    certBody.y = my + 175;

    const seal = new Graphics();
    seal.circle(mx + mw - 60, my + mh - 70, 26);
    seal.fill({ color: 0xD4AF37 });
    seal.stroke({ width: 3, color: 0x975A16 });

    const sealText = new Text({
      text: 'PPS\n2026',
      style: new TextStyle({ fontSize: 10, fontWeight: 'bold', fill: '#FFFFFF', align: 'center' })
    });
    sealText.anchor.set(0.5);
    sealText.x = mx + mw - 60;
    sealText.y = my + mh - 70;

    const closeBtn = UIHelper.createButton('Close Certificate ✕', 160, 36, 0x6C5CE7, '#FFFFFF', 12, () => {
      this.modalContainer.removeChildren();
    });
    closeBtn.x = mx + mw / 2 - 40;
    closeBtn.y = my + mh - 45;

    modal.addChild(bg);
    modal.addChild(certTitle);
    modal.addChild(certSubtitle);
    modal.addChild(certBody);
    modal.addChild(seal);
    modal.addChild(sealText);
    modal.addChild(closeBtn);

    this.modalContainer.addChild(modal);
    SoundSynth.playLevelClear();
    ParticleSystem.triggerConfetti();
  }

  update(_deltaSec: number) {}
}
