import { WorldId, GameMode, StageDefinition } from '../types/game';
import { WORLDS } from '../math/CurriculumData';

export type SceneryType = 'planet' | 'asteroid' | 'star' | 'robot' | 'crystal' | 'satellite';

export interface OverworldNode {
  id: string;             // e.g. "w1_n1"
  worldId: WorldId;       // "world_1" ... "world_5"
  index: number;          // 0 .. 11
  mode: GameMode;         // "blaster" | "jetpack" | "snack_sort" (4 of each)
  stageId: string;        // mapped stage id from CurriculumData
  isoX: number;           // isometric grid coordinate X
  isoY: number;           // isometric grid coordinate Y
  screenX: number;        // projected world pixel coordinate X
  screenY: number;        // projected world pixel coordinate Y
  label: string;          // e.g. "1-1", "1-2"
}

export interface AmbientSceneryObject {
  id: string;
  type: SceneryType;
  screenX: number;
  screenY: number;
  scale: number;
  speed: number;
  rotationSpeed: number;
  bobPhase: number;
  palette: number[];
}

export interface WorldTheme {
  name: string;
  primaryColor: number;
  accentColor: number;
  bgColor: number;
  pathColor: number;
  pathBorderColor: number;
  gridColor: number;
  ambientLightColor: number;
  particleColors: number[];
  sceneryTypes: SceneryType[];
  decorations: string[];
}

export interface OverworldData {
  worldId: WorldId;
  theme: WorldTheme;
  nodes: OverworldNode[];
  pathWaypoints: { x: number; y: number }[];
  scenery: AmbientSceneryObject[];
  worldBounds: { width: number; height: number };
}

/**
 * Deterministic string hash function creating an unsigned 32-bit integer seed.
 */
export function hashString(str: string): number {
  let hash = 2166136261;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

/**
 * Mulberry32 seeded pseudo-random number generator.
 * Produces deterministic floats in the range [0, 1).
 */
export function createPrng(seed: number | string): () => number {
  let s = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
  if (s === 0) s = 1337;
  return function next(): number {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randomRange(rng: () => number, min: number, max: number): number {
  return min + rng() * (max - min);
}

function randomInt(rng: () => number, min: number, max: number): number {
  return Math.floor(min + rng() * (max - min + 1));
}

function randomChoice<T>(rng: () => number, array: readonly T[]): T {
  return array[Math.floor(rng() * array.length)];
}

function shuffleArray<T>(rng: () => number, array: readonly T[]): T[] {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
  }
  return arr;
}

