const DEFAULT_ORIGIN_X = 400;
const DEFAULT_ORIGIN_Y = 80;
const DEFAULT_TILE_W_HALF = 50;
const DEFAULT_TILE_H_HALF = 25;

export class OverworldGenerator {
  /**
   * Convert isometric grid coordinates to screen pixel coordinates.
   */
  public static isoToScreen(
    isoX: number,
    isoY: number,
    originX = DEFAULT_ORIGIN_X,
    originY = DEFAULT_ORIGIN_Y,
    tileWidthHalf = DEFAULT_TILE_W_HALF,
    tileHeightHalf = DEFAULT_TILE_H_HALF
  ): { x: number; y: number } {
    const x = originX + (isoX - isoY) * tileWidthHalf;
    const y = originY + (isoX + isoY) * tileHeightHalf;
    return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
  }

  /**
   * Convert screen pixel coordinates to isometric grid coordinates.
   */
  public static screenToIso(
    screenX: number,
    screenY: number,
    originX = DEFAULT_ORIGIN_X,
    originY = DEFAULT_ORIGIN_Y,
    tileWidthHalf = DEFAULT_TILE_W_HALF,
    tileHeightHalf = DEFAULT_TILE_H_HALF
  ): { isoX: number; isoY: number } {
    const dx = screenX - originX;
    const dy = screenY - originY;
    const isoX = (dx / tileWidthHalf + dy / tileHeightHalf) / 2;
    const isoY = (dy / tileHeightHalf - dx / tileWidthHalf) / 2;
    return {
      isoX: Math.round(isoX * 100) / 100,
      isoY: Math.round(isoY * 100) / 100
    };
  }

  /**
   * Generate smooth intermediate waypoints between consecutive path points.
   */
  public static interpolateWaypoints(
    points: { x: number; y: number }[],
    subdivisions = 4
  ): { x: number; y: number }[] {
    if (points.length < 2) return [...points];
    const waypoints: { x: number; y: number }[] = [];

    for (let i = 0; i < points.length - 1; i++) {
      const p0 = i > 0 ? points[i - 1] : points[i];
      const p1 = points[i];
      const p2 = points[i + 1];
      const p3 = i + 2 < points.length ? points[i + 2] : p2;

      for (let s = 0; s < subdivisions; s++) {
        const t = s / subdivisions;
        const t2 = t * t;
        const t3 = t2 * t;

        // Catmull-Rom spline interpolation
        const x = 0.5 * (
          (2 * p1.x) +
          (-p0.x + p2.x) * t +
          (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 +
          (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3
        );

        const y = 0.5 * (
          (2 * p1.y) +
          (-p0.y + p2.y) * t +
          (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 +
          (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3
        );

        waypoints.push({
          x: Math.round(x * 10) / 10,
          y: Math.round(y * 10) / 10
        });
      }
    }

    // Append the very last point
    const last = points[points.length - 1];
    waypoints.push({
      x: Math.round(last.x * 10) / 10,
      y: Math.round(last.y * 10) / 10
    });

    return waypoints;
  }

  /**
   * Returns the WorldTheme definition for a given WorldId.
   */
  public static getWorldTheme(worldId: WorldId): WorldTheme {
    return WORLD_THEMES[worldId] || WORLD_THEMES.world_1;
  }

  /**
   * Returns a list of all valid WorldIds.
   */
  public static getAllWorldIds(): WorldId[] {
    return ['world_1', 'world_2', 'world_3', 'world_4', 'world_5'];
  }

  /**
   * Looks up the CurriculumData StageDefinition corresponding to a given world and node index (0..11).
   */
  public static getStageForNode(worldId: WorldId, nodeIndex: number): StageDefinition | undefined {
    const worldDef = WORLDS.find(w => w.id === worldId) || WORLDS[0];
    const stages = worldDef.stages;
    if (!stages || stages.length === 0) return undefined;
    const clampedIndex = Math.max(0, Math.min(11, nodeIndex));
    const stageIdx = Math.min(stages.length - 1, Math.floor((clampedIndex / 12) * stages.length));
    return stages[stageIdx];
  }

  /**
   * Looks up an OverworldNode from a generated world by its string ID (e.g. "w1_n3").
   */
  public static getNodeById(worldId: WorldId, nodeId: string): OverworldNode | undefined {
    const data = OverworldGenerator.generateWorld(worldId);
    return data.nodes.find(n => n.id === nodeId);
  }

  /**
   * Procedurally generates complete overworld data for a given WorldId.
   * Deterministic: Identical seed/worldId produces identical OverworldData every time.
   */
  public static generateWorld(worldId: WorldId, customSeed?: number): OverworldData {
    const seed = customSeed !== undefined ? customSeed : hashString(worldId);
    const rng = createPrng(seed);

    const worldDef = WORLDS.find(w => w.id === worldId) || WORLDS[0];
    const theme = OverworldGenerator.getWorldTheme(worldId);
    const worldBounds = { width: 800, height: 1400 };

    // 1. Balanced Game Modes (Exactly 4 blaster, 4 jetpack, 4 snack_sort)
    const baseModes: GameMode[] = [
      'blaster', 'blaster', 'blaster', 'blaster',
      'jetpack', 'jetpack', 'jetpack', 'jetpack',
      'snack_sort', 'snack_sort', 'snack_sort', 'snack_sort'
    ];
    const shuffledModes = shuffleArray(rng, baseModes);

    // 2. Procedural Winding Path Parameters (Per world seed)
    const waveFreq = 1.35 + (rng() * 0.45); // ~1.35 to 1.80 full cycles
    const waveAmp = 190 + (rng() * 60);    // ~190 to 250 px horizontal amplitude
    const wavePhase = (rng() * Math.PI * 2); // random initial phase

    const startY = 1260; // Node 0 (Start) at bottom
    const endY = 140;    // Node 11 (Boss Finale) at top
    const centerX = worldBounds.width / 2; // 400

    const nodes: OverworldNode[] = [];
    const nodePoints: { x: number; y: number }[] = [];

    for (let i = 0; i < 12; i++) {
      const t = i / 11; // 0.0 -> 1.0

      // Base vertical progression from bottom to top
      const baseY = startY - t * (startY - endY);

      // S-curve / serpentine winding with minor per-node procedural jitter
      const jitterX = (rng() - 0.5) * 28;
      const jitterY = (rng() - 0.5) * 20;

      const angle = t * Math.PI * 2 * waveFreq + wavePhase;
      const rawX = centerX + Math.sin(angle) * waveAmp + jitterX;
      const rawY = baseY + jitterY;

      // Clamp within playable bounds
      const screenX = Math.round(Math.max(140, Math.min(worldBounds.width - 140, rawX)) * 10) / 10;
      const screenY = Math.round(Math.max(100, Math.min(worldBounds.height - 100, rawY)) * 10) / 10;

      // Compute corresponding isometric grid coordinates
      const { isoX, isoY } = OverworldGenerator.screenToIso(screenX, screenY);

      // Map to curriculum stage
      const stageIdx = Math.min(worldDef.stages.length - 1, Math.floor((i / 12) * worldDef.stages.length));
      const stage = worldDef.stages[stageIdx];

      const node: OverworldNode = {
        id: `w${worldDef.number}_n${i + 1}`,
        worldId,
        index: i,
        mode: shuffledModes[i],
        stageId: stage ? stage.id : `w${worldDef.number}_s1`,
        isoX,
        isoY,
        screenX,
        screenY,
        label: `${worldDef.number}-${i + 1}`
      };

      nodes.push(node);
      nodePoints.push({ x: screenX, y: screenY });
    }

    // 3. Interpolated Path Waypoints
    const pathWaypoints = OverworldGenerator.interpolateWaypoints(nodePoints, 5);

    // 4. Ambient Animated Scenery (8 to 12 objects per world)
    const sceneryCount = randomInt(rng, 8, 12);
    const scenery: AmbientSceneryObject[] = [];
    const availableTypes = theme.sceneryTypes;

    for (let j = 0; j < sceneryCount; j++) {
      const type = randomChoice(rng, availableTypes);
      let candidateX = 0;
      let candidateY = 0;
      let validPlacement = false;

      // Try up to 40 attempts to find a spot that does not obscure level nodes
      for (let attempt = 0; attempt < 40; attempt++) {
        // Place scenery throughout the world bounds with a margin
        candidateX = Math.round(randomRange(rng, 60, worldBounds.width - 60));
        candidateY = Math.round(randomRange(rng, 60, worldBounds.height - 60));

        // Check distance to all level nodes (must be >= 68 px to ensure hit areas are clear)
        let minNodeDist = Infinity;
        for (const node of nodes) {
          const dist = Math.hypot(node.screenX - candidateX, node.screenY - candidateY);
          if (dist < minNodeDist) minNodeDist = dist;
        }

        // Check distance to already placed scenery (must be >= 55 px to avoid overlap)
        let minSceneryDist = Infinity;
        for (const s of scenery) {
          const dist = Math.hypot(s.screenX - candidateX, s.screenY - candidateY);
          if (dist < minSceneryDist) minSceneryDist = dist;
        }

        if (minNodeDist >= 68 && minSceneryDist >= 55) {
          validPlacement = true;
          break;
        }
      }

      // If no ideal spot found, place along the side margins
      if (!validPlacement) {
        candidateX = j % 2 === 0 ? randomRange(rng, 45, 100) : randomRange(rng, worldBounds.width - 100, worldBounds.width - 45);
        candidateY = randomRange(rng, 80 + j * 100, 180 + j * 100);
      }

      // Palette generation from theme
      const palette = [
        theme.primaryColor,
        theme.accentColor,
        randomChoice(rng, theme.particleColors),
        theme.ambientLightColor
      ];

      const sceneryObj: AmbientSceneryObject = {
        id: `scenery_${worldId}_${j + 1}`,
        type,
        screenX: Math.round(candidateX * 10) / 10,
        screenY: Math.round(candidateY * 10) / 10,
        scale: Math.round(randomRange(rng, 0.65, 1.35) * 100) / 100,
        speed: Math.round(randomRange(rng, 0.6, 2.2) * 100) / 100,
        rotationSpeed: Math.round((rng() > 0.5 ? 1 : -1) * randomRange(rng, 0.006, 0.024) * 1000) / 1000,
        bobPhase: Math.round(randomRange(rng, 0, Math.PI * 2) * 100) / 100,
        palette
      };

      scenery.push(sceneryObj);
    }

    return {
      worldId,
      theme,
      nodes,
      pathWaypoints,
      scenery,
      worldBounds
    };
  }
}
