import { Container, Graphics, Text, TextStyle, Rectangle } from 'pixi.js';
import { GameScene, SceneManager } from './SceneManager';
import { StageDefinition, MathQuestion } from '../types/game';
import { MathGenerator } from '../math/MathGenerator';
import { GameState } from '../state/GameState';
import { PlushRobot } from '../entities/PlushRobot';
import { ParticleSystem } from '../engine/ParticleSystem';
import { VisualManipulative } from '../entities/VisualManipulative';
import { UIHelper } from '../engine/UIHelper';
import { SoundSynth } from '../audio/SoundSynth';
import { MusicPlayer } from '../audio/MusicPlayer';
import { SpeechHelper } from '../math/SpeechHelper';
import { WorldMapScene } from './WorldMapScene';

interface TopMonster {
  container: Container;
  bodyGfx: Graphics;
  faceGfx: Graphics;
  mouthGfx: Graphics;
  tongueGfx: Graphics;
  label: Text;
  targetCategory: string | number;
  x: number;
  y: number;
  width: number;
  height: number;
  baseColor: number;
  state: 'idle' | 'gobbling' | 'grossed_out';
  animTimer: number;
}

export class SnackSortScene extends Container implements GameScene {
  private stageDef: StageDefinition;
  private currentQuestion: MathQuestion | null = null;
  private questionsAnswered: number = 0;
  private correctAnswers: number = 0;
  private score: number = 0;

  private screenW: number = 800;
  private screenH: number = 600;

  private bgGfx: Graphics;
  private ceilingGfx: Graphics;
  private gameLayer: Container;
  private monstersLayer: Container;
  private slingshotGfx: Graphics;
  private trajectoryGfx: Graphics;
  private flyingCandyContainer: Container;
  private uiLayer: Container;
  private particleSys: ParticleSystem;

  private pip: PlushRobot;
  private monsters: TopMonster[] = [];

  // Slingshot / Bust-A-Move Aiming State
  private launcherX: number = 400;
  private launcherY: number = 520;
  private isAiming: boolean = false;
  private aimAngle: number = -Math.PI / 2;
  private pullDistance: number = 0;

  // Flying Candy State
  private isCandyFlying: boolean = false;
  private candyX: number = 0;
  private candyY: number = 0;
  private candyVx: number = 0;
  private candyVy: number = 0;
  private candyTypeIndex: number = 0;

  private hintModal: Container | null = null;
  private isGameOver: boolean = false;

  constructor(stageDef: StageDefinition) {
    super();
    this.stageDef = stageDef;

    this.bgGfx = new Graphics();
    this.ceilingGfx = new Graphics();
    this.gameLayer = new Container();
    this.monstersLayer = new Container();
    this.slingshotGfx = new Graphics();
    this.trajectoryGfx = new Graphics();
    this.flyingCandyContainer = new Container();
    this.particleSys = new ParticleSystem();
    this.uiLayer = new Container();

    this.addChild(this.bgGfx);
    this.addChild(this.ceilingGfx);
    this.addChild(this.gameLayer);
    this.gameLayer.addChild(this.monstersLayer);
    this.gameLayer.addChild(this.trajectoryGfx);
    this.gameLayer.addChild(this.slingshotGfx);
    this.gameLayer.addChild(this.flyingCandyContainer);

    this.pip = new PlushRobot(0.52);
    this.gameLayer.addChild(this.pip);

    this.addChild(this.particleSys);
    this.addChild(this.uiLayer);

    this.setupSlingshotControls();
  }

  onEnter() {
    MusicPlayer.playTheme('arcade_rush');
    this.nextQuestion();
    this.renderUI();
  }

  resize(w: number, h: number) {
    this.screenW = w;
    this.screenH = h;
    this.hitArea = new Rectangle(0, 0, w, h);
    this.launcherX = w / 2;
    this.launcherY = h - 85;
    this.pip.x = this.launcherX - 90;
    this.pip.y = this.launcherY + 10;
    this.renderBackground();
    this.renderSlingshot();
    this.renderUI();
  }

  private setupSlingshotControls() {
    this.eventMode = 'static';
    this.hitArea = new Rectangle(0, 0, this.screenW, this.screenH);

    this.bgGfx.eventMode = 'static';

    const handleDown = (e: any) => {
      if (this.isGameOver || this.isCandyFlying) return;
      this.isAiming = true;
      this.updateAimVector(e.global.x, e.global.y);
      SoundSynth.triggerHaptic(15);
    };

    const handleMove = (e: any) => {
      if (!this.isAiming || this.isGameOver || this.isCandyFlying) return;
      this.updateAimVector(e.global.x, e.global.y);
    };

    const handleUp = () => {
      if (!this.isAiming || this.isGameOver || this.isCandyFlying) return;
      this.isAiming = false;
      this.trajectoryGfx.clear();
      this.fireCandy();
    };

    this.on('pointerdown', handleDown);
    this.on('pointermove', handleMove);
    this.on('pointerup', handleUp);
    this.on('pointerupoutside', handleUp);

    this.bgGfx.on('pointerdown', handleDown);
    this.bgGfx.on('pointermove', handleMove);
    this.bgGfx.on('pointerup', handleUp);
  }

  private updateAimVector(touchX: number, touchY: number) {
    const dx = touchX - this.launcherX;
    const dy = touchY - this.launcherY;
    const dist = Math.hypot(dx, dy);

    if (dy > 0) {
      this.aimAngle = Math.atan2(-dy, -dx);
    } else {
      this.aimAngle = Math.atan2(dy, dx);
    }

    const minAngle = -Math.PI + 0.2;
    const maxAngle = -0.2;
    this.aimAngle = Math.max(minAngle, Math.min(maxAngle, this.aimAngle));
    this.pullDistance = Math.min(100, Math.max(30, dist));

    this.renderTrajectory();
    this.renderSlingshot();
  }

  private renderTrajectory() {
    this.trajectoryGfx.clear();
    if (!this.isAiming) return;

    let currX = this.launcherX;
    let currY = this.launcherY - 15;
    const speed = 25;
    let vx = Math.cos(this.aimAngle) * speed;
    let vy = Math.sin(this.aimAngle) * speed;

    for (let step = 0; step < 26; step++) {
      currX += vx;
      currY += vy;

      if (currX < 25) {
        currX = 25;
        vx = -vx;
      } else if (currX > this.screenW - 25) {
        currX = this.screenW - 25;
        vx = -vx;
      }

      if (currY < 130) break;

      if (step % 2 === 0) {
        const dotRadius = Math.max(2.5, 5 - step * 0.1);
        this.trajectoryGfx.circle(currX, currY, dotRadius);
        this.trajectoryGfx.fill({ color: 0xFFD32A, alpha: 0.85 });
      }
    }
  }

  private renderSlingshot() {
    this.slingshotGfx.clear();
    const lx = this.launcherX;
    const ly = this.launcherY;

    this.slingshotGfx.roundRect(lx - 32, ly + 25, 64, 20, 8);
    this.slingshotGfx.fill({ color: 0x2F3542 });
    this.slingshotGfx.stroke({ width: 2.5, color: 0x747D8C });

    this.slingshotGfx.moveTo(lx - 22, ly + 25);
    this.slingshotGfx.lineTo(lx - 26, ly - 10);
    this.slingshotGfx.moveTo(lx + 22, ly + 25);
    this.slingshotGfx.lineTo(lx + 26, ly - 10);
    this.slingshotGfx.stroke({ width: 6, color: 0xED4C67, cap: 'round' });

    let bandPullX = lx;
    let bandPullY = ly - 10;
    if (this.isAiming) {
      bandPullX = lx - Math.cos(this.aimAngle) * (this.pullDistance * 0.4);
      bandPullY = ly - 10 - Math.sin(this.aimAngle) * (this.pullDistance * 0.4);
    }

    this.slingshotGfx.moveTo(lx - 26, ly - 10);
    this.slingshotGfx.lineTo(bandPullX, bandPullY);
    this.slingshotGfx.moveTo(lx + 26, ly - 10);
    this.slingshotGfx.lineTo(bandPullX, bandPullY);
    this.slingshotGfx.stroke({ width: 3, color: 0xFFD32A });

    if (!this.isCandyFlying) {
      this.flyingCandyContainer.x = bandPullX;
      this.flyingCandyContainer.y = bandPullY;
    }
  }

  private fireCandy() {
    this.isCandyFlying = true;
    SoundSynth.playLaser();
    SoundSynth.triggerHaptic(30);

    this.candyX = this.launcherX;
    this.candyY = this.launcherY - 15;
    const speed = 720;
    this.candyVx = Math.cos(this.aimAngle) * speed;
    this.candyVy = Math.sin(this.aimAngle) * speed;

    this.pip.doHappyJump();
    this.renderSlingshot();
  }

  private renderBackground() {
    const w = this.screenW;
    const h = this.screenH;

    this.bgGfx.clear();
    this.bgGfx.rect(0, 0, w, h);
    this.bgGfx.fill({ color: 0x130F26 });

    this.bgGfx.rect(0, 0, 15, h);
    this.bgGfx.rect(w - 15, 0, 15, h);
    this.bgGfx.fill({ color: 0x1E1B38 });
    this.bgGfx.stroke({ width: 1.5, color: 0x6C5CE7 });

    this.ceilingGfx.clear();
    this.ceilingGfx.roundRect(15, 52, w - 30, 20, 8);
    this.ceilingGfx.fill({ color: 0x2A2356 });
    this.ceilingGfx.stroke({ width: 2, color: 0xA29BFE });
  }

  private nextQuestion() {
    if (this.questionsAnswered >= this.stageDef.targetCount) {
      this.triggerVictory();
      return;
    }

    this.currentQuestion = MathGenerator.generateQuestion(this.stageDef.id);
    this.candyTypeIndex = (this.candyTypeIndex + 1) % 3;
    this.setupTopMonsters(this.currentQuestion);
    this.drawCandySprite();
    this.isCandyFlying = false;
    this.renderSlingshot();
    this.renderUI();

    if (this.currentQuestion.speechPrompt) {
      SpeechHelper.speak(this.currentQuestion.speechPrompt);
    }
  }

  private setupTopMonsters(q: MathQuestion) {
    this.monstersLayer.removeChildren();
    this.monsters = [];

    const options = [...q.options];
    // Invariant Guarantee: Correct answer MUST be in options
    if (!options.map(String).includes(String(q.correctAnswer))) {
      options.unshift(q.correctAnswer);
    }
    const count = options.length;
    const monsterW = Math.min(130, (this.screenW - 30) / count - 10);
    const monsterH = 95;
    const colors = [0xFF4757, 0x2ED573, 0x1E90FF, 0xA55EEA, 0xFFA502];
    const topY = 145;

    options.forEach((opt, idx) => {
      const container = new Container();
      const x = (this.screenW / (count + 1)) * (idx + 1);
      const color = colors[idx % colors.length];

      const bodyGfx = new Graphics();
      const faceGfx = new Graphics();
      const mouthGfx = new Graphics();
      const tongueGfx = new Graphics();

      bodyGfx.roundRect(-monsterW / 2, -monsterH / 2, monsterW, monsterH, 24);
      bodyGfx.fill({ color });
      bodyGfx.stroke({ width: 3.5, color: 0xFFFFFF });

      bodyGfx.moveTo(-monsterW / 3, -monsterH / 2);
      bodyGfx.lineTo(-monsterW / 3 - 6, -monsterH / 2 - 14);
      bodyGfx.moveTo(monsterW / 3, -monsterH / 2);
      bodyGfx.lineTo(monsterW / 3 + 6, -monsterH / 2 - 14);
      bodyGfx.stroke({ width: 3, color: 0xFFD32A });

      faceGfx.circle(-monsterW / 4, -monsterH / 4, 11);
      faceGfx.circle(monsterW / 4, -monsterH / 4, 11);
      faceGfx.fill({ color: 0xFFFFFF });
      faceGfx.stroke({ width: 2, color: 0x2F3542 });
      faceGfx.circle(-monsterW / 4, -monsterH / 4, 5.5);
      faceGfx.circle(monsterW / 4, -monsterH / 4, 5.5);
      faceGfx.fill({ color: 0x2F3542 });

      mouthGfx.arc(0, 4, 14, 0.2, Math.PI - 0.2);
      mouthGfx.stroke({ width: 3, color: 0x1E272E, cap: 'round' });

      const badgeBg = new Graphics();
      badgeBg.roundRect(-monsterW / 2 + 10, 18, monsterW - 20, 26, 8);
      badgeBg.fill({ color: 0x1E272E, alpha: 0.9 });
      badgeBg.stroke({ width: 1.5, color: 0xFFD32A });

      const label = new Text({
        text: String(opt),
        style: new TextStyle({
          fontSize: 16,
          fontWeight: 'bold',
          fill: '#FFD32A',
          align: 'center'
        })
      });
      label.anchor.set(0.5);
      label.y = 31;

      container.addChild(bodyGfx);
      container.addChild(badgeBg);
      container.addChild(mouthGfx);
      container.addChild(tongueGfx);
      container.addChild(faceGfx);
      container.addChild(label);
      container.x = x;
      container.y = topY;

      this.monstersLayer.addChild(container);
      this.monsters.push({
        container,
        bodyGfx,
        faceGfx,
        mouthGfx,
        tongueGfx,
        label,
        targetCategory: opt,
        x,
        y: topY,
        width: monsterW,
        height: monsterH,
        baseColor: color,
        state: 'idle',
        animTimer: 0
      });
    });
  }

  private drawCandySprite() {
    this.flyingCandyContainer.removeChildren();
    const gfx = new Graphics();

    if (this.candyTypeIndex === 0) {
      gfx.moveTo(-28, -8);
      gfx.lineTo(-16, 0);
      gfx.lineTo(-28, 8);
      gfx.fill({ color: 0xFF6B81 });
      gfx.moveTo(28, -8);
      gfx.lineTo(16, 0);
      gfx.lineTo(28, 8);
      gfx.fill({ color: 0xFF6B81 });

      gfx.circle(0, 0, 18);
      gfx.fill({ color: 0xFFFFFF });
      gfx.stroke({ width: 2.5, color: 0xE15F41 });
      gfx.arc(0, 0, 10, 0, Math.PI);
      gfx.stroke({ width: 3, color: 0xFF4757 });
    } else if (this.candyTypeIndex === 1) {
      gfx.roundRect(-2, 10, 4, 18, 2);
      gfx.fill({ color: 0xF1F2F6 });
      gfx.circle(0, 0, 18);
      gfx.fill({ color: 0xFFA502 });
      gfx.stroke({ width: 2.5, color: 0xFF4757 });
      gfx.arc(0, 0, 10, 0, Math.PI * 1.5);
      gfx.stroke({ width: 2.5, color: 0x70A1FF });
    } else {
      const r = 18;
      for (let i = 0; i < 5; i++) {
        const a = (i * Math.PI * 2) / 5 - Math.PI / 2;
        const x1 = Math.cos(a) * r;
        const y1 = Math.sin(a) * r;
        const a2 = a + Math.PI / 5;
        const x2 = Math.cos(a2) * (r * 0.5);
        const y2 = Math.sin(a2) * (r * 0.5);
        if (i === 0) gfx.moveTo(x1, y1);
        else gfx.lineTo(x1, y1);
        gfx.lineTo(x2, y2);
      }
      gfx.fill({ color: 0xFFD32A });
      gfx.stroke({ width: 2.5, color: 0xF39C12 });
    }

    this.flyingCandyContainer.addChild(gfx);
  }

  private handleMonsterCollision(monster: TopMonster) {
    if (!this.currentQuestion) return;
    this.isCandyFlying = false;
    this.flyingCandyContainer.removeChildren();

    const isCorrect = String(monster.targetCategory) === String(this.currentQuestion.correctAnswer);

    if (isCorrect) {
      this.correctAnswers++;
      this.questionsAnswered++;
      this.score += 130;

      monster.state = 'gobbling';
      monster.animTimer = 0.9;

      GameState.getInstance().recordAnswer(this.currentQuestion, true);
      SoundSynth.playNom();
      SoundSynth.playCorrect();
      SoundSynth.triggerHaptic(35);

      this.particleSys.emitStarBurst(monster.x, monster.y, 30);
      this.pip.doHappyJump();

      setTimeout(() => {
        if (!this.destroyed) {
          monster.state = 'idle';
          this.nextQuestion();
        }
      }, 900);
    } else {
      this.questionsAnswered++;
      monster.state = 'grossed_out';
      monster.animTimer = 1.0;

      GameState.getInstance().recordAnswer(this.currentQuestion, false);
      SoundSynth.playWrong();
      SoundSynth.triggerHaptic(50);

      this.particleSys.emitSmokePuff(monster.x, monster.y + 20);
      this.pip.doErrorShake();

      setTimeout(() => {
        if (!this.destroyed) {
          monster.state = 'idle';
          this.showHintModal();
        }
      }, 1000);
    }
    this.renderUI();
  }

  private showHintModal() {
    if (!this.currentQuestion) return;
    const modal = new Container();
    const mw = Math.min(500, this.screenW - 40);
    const mh = 320;
    const mx = (this.screenW - mw) / 2;
    const my = (this.screenH - mh) / 2;

    const bg = new Graphics();
    bg.roundRect(mx, my, mw, mh, 18);
    bg.fill({ color: 0x1E272E, alpha: 0.98 });
    bg.stroke({ width: 3, color: 0x5F27CD });
    modal.addChild(bg);

    const title = new Text({
      text: '🍬 Monster Candy Slingshot Guide',
      style: new TextStyle({ fontSize: 18, fontWeight: 'bold', fill: '#FFD32A' })
    });
    title.x = mx + 20;
    title.y = my + 15;
    modal.addChild(title);

    if (this.currentQuestion.manipulative) {
      const manip = new VisualManipulative(this.currentQuestion.manipulative, mw - 40, 140);
      manip.x = mx + 20;
      manip.y = my + 45;
      modal.addChild(manip);
    }

    const hintText = new Text({
      text: this.currentQuestion.hint,
      style: new TextStyle({ fontSize: 13, fill: '#FFFFFF', wordWrap: true, wordWrapWidth: mw - 40 })
    });
    hintText.x = mx + 20;
    hintText.y = my + 195;
    modal.addChild(hintText);

    const gotItBtn = UIHelper.createButton('Aim & Shoot Candy! 🍬', 200, 40, 0x5F27CD, '#FFFFFF', 14, () => {
      this.uiLayer.removeChild(modal);
      modal.destroy();
      this.hintModal = null;
      this.nextQuestion();
    });
    gotItBtn.x = mx + mw / 2;
    gotItBtn.y = my + mh - 35;
    modal.addChild(gotItBtn);

    this.hintModal = modal;
    this.uiLayer.addChild(modal);
  }

  private triggerVictory() {
    this.isGameOver = true;
    this.monstersLayer.removeChildren();
    this.flyingCandyContainer.removeChildren();

    const state = GameState.getInstance();
    const result = state.completeStage(
      this.stageDef.id,
      this.correctAnswers,
      this.stageDef.targetCount,
      this.score
    );

    SoundSynth.playLevelClear();
    ParticleSystem.triggerConfetti();

    const modal = new Container();
    const mw = Math.min(460, this.screenW - 40);
    const mh = 360;
    const mx = (this.screenW - mw) / 2;
    const my = (this.screenH - mh) / 2;

    const bg = new Graphics();
    bg.roundRect(mx, my, mw, mh, 20);
    bg.fill({ color: 0x1E272E, alpha: 0.98 });
    bg.stroke({ width: 3, color: 0x5F27CD });
    modal.addChild(bg);

    const title = new Text({
      text: '🍬 ALL MONSTERS HAPPILY FED!',
      style: new TextStyle({ fontSize: 20, fontWeight: 'bold', fill: '#5F27CD', align: 'center' })
    });
    title.anchor.set(0.5);
    title.x = mx + mw / 2;
    title.y = my + 35;
    modal.addChild(title);

    const starsStr = '⭐'.repeat(result.starsEarned) + '☆'.repeat(3 - result.starsEarned);
    const starsText = new Text({
      text: starsStr,
      style: new TextStyle({ fontSize: 36, fill: '#FFD32A', align: 'center' })
    });
    starsText.anchor.set(0.5);
    starsText.x = mx + mw / 2;
    starsText.y = my + 85;
    modal.addChild(starsText);

    const scoreInfo = new Text({
      text: `Score: ${this.score}\nAccuracy: ${this.correctAnswers} / ${this.stageDef.targetCount} (${Math.round((this.correctAnswers / this.stageDef.targetCount) * 100)}%)\nStar Coins Earned: +${result.starsEarned * 3} 🪙`,
      style: new TextStyle({ fontSize: 15, fill: '#FFFFFF', align: 'center', lineHeight: 24 })
    });
    scoreInfo.anchor.set(0.5);
    scoreInfo.x = mx + mw / 2;
    scoreInfo.y = my + 175;
    modal.addChild(scoreInfo);

    const continueBtn = UIHelper.createButton('Back to Galaxy Map 🌌', 200, 44, 0x5F27CD, '#FFFFFF', 14, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    continueBtn.x = mx + mw / 2;
    continueBtn.y = my + mh - 45;
    modal.addChild(continueBtn);

    this.uiLayer.addChild(modal);
  }

  private renderUI() {
    this.uiLayer.removeChildren();
    if (this.hintModal) {
      this.uiLayer.addChild(this.hintModal);
      return;
    }

    const w = this.screenW;

    const headerBg = new Graphics();
    headerBg.roundRect(10, 8, w - 20, 44, 12);
    headerBg.fill({ color: 0x1E272E, alpha: 0.9 });
    headerBg.stroke({ width: 1.5, color: 0x576574 });
    this.uiLayer.addChild(headerBg);

    const backBtn = UIHelper.createButton('◀ Exit', 70, 30, 0xFF4757, '#FFFFFF', 12, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    backBtn.x = 55;
    backBtn.y = 30;
    this.uiLayer.addChild(backBtn);

    const progressText = new Text({
      text: `Candy Pop ${this.questionsAnswered + 1}/${this.stageDef.targetCount} | Pull back & aim to shoot!`,
      style: new TextStyle({ fontSize: 13, fontWeight: 'bold', fill: '#5F27CD' })
    });
    progressText.x = 105;
    progressText.y = 22;
    this.uiLayer.addChild(progressText);

    if (this.currentQuestion) {
      const qBg = new Graphics();
      qBg.roundRect(10, 56, w - 20, 44, 12);
      qBg.fill({ color: 0x2C3A47, alpha: 0.95 });
      qBg.stroke({ width: 2, color: 0x5F27CD });
      this.uiLayer.addChild(qBg);

      const qText = new Text({
        text: this.currentQuestion.prompt,
        style: new TextStyle({ fontSize: 15, fontWeight: 'bold', fill: '#FFFFFF' })
      });
      qText.x = 25;
      qText.y = 66;
      this.uiLayer.addChild(qText);

      const ttsBtn = UIHelper.createButton('🔊 Read', 64, 28, 0x5F27CD, '#FFFFFF', 11, () => {
        if (this.currentQuestion?.speechPrompt) {
          SpeechHelper.speak(this.currentQuestion.speechPrompt);
        }
      });
      ttsBtn.x = w - 50;
      ttsBtn.y = 78;
      this.uiLayer.addChild(ttsBtn);
    }
  }

  update(deltaSec: number) {
    this.pip.update(deltaSec);
    this.particleSys.update(deltaSec);

    for (const monster of this.monsters) {
      if (monster.state === 'gobbling') {
        monster.animTimer -= deltaSec;
        const chomp = Math.sin(monster.animTimer * 26);

        monster.mouthGfx.clear();
        monster.mouthGfx.roundRect(-monster.width / 4, -4, monster.width / 2, 22 + chomp * 8, 8);
        monster.mouthGfx.fill({ color: 0x1E272E });

        monster.faceGfx.clear();
        monster.faceGfx.arc(-monster.width / 4, -monster.height / 4, 10, Math.PI * 1.1, Math.PI * 1.9);
        monster.faceGfx.arc(monster.width / 4, -monster.height / 4, 10, Math.PI * 1.1, Math.PI * 1.9);
        monster.faceGfx.stroke({ width: 3, color: 0xFFFFFF });

        monster.container.scale.y = 1 + chomp * 0.12;
      } else if (monster.state === 'grossed_out') {
        monster.animTimer -= deltaSec;
        const shiver = Math.sin(monster.animTimer * 35) * 5;

        monster.bodyGfx.clear();
        monster.bodyGfx.roundRect(-monster.width / 2, -monster.height / 2, monster.width, monster.height, 24);
        monster.bodyGfx.fill({ color: 0x44BD32 });
        monster.bodyGfx.stroke({ width: 3.5, color: 0x8C7AE6 });

        monster.faceGfx.clear();
        monster.faceGfx.moveTo(-monster.width / 4 - 6, -monster.height / 4 - 6);
        monster.faceGfx.lineTo(-monster.width / 4 + 6, -monster.height / 4 + 6);
        monster.faceGfx.moveTo(-monster.width / 4 + 6, -monster.height / 4 - 6);
        monster.faceGfx.lineTo(-monster.width / 4 - 6, -monster.height / 4 + 6);

        monster.faceGfx.moveTo(monster.width / 4 - 6, -monster.height / 4 - 6);
        monster.faceGfx.lineTo(monster.width / 4 + 6, -monster.height / 4 + 6);
        monster.faceGfx.moveTo(monster.width / 4 + 6, -monster.height / 4 - 6);
        monster.faceGfx.lineTo(monster.width / 4 - 6, -monster.height / 4 + 6);
        monster.faceGfx.stroke({ width: 3, color: 0x2F3542 });

        monster.tongueGfx.clear();
        monster.tongueGfx.roundRect(-8, 6, 16, 20, 6);
        monster.tongueGfx.fill({ color: 0x9B59B6 });
        monster.tongueGfx.stroke({ width: 1.5, color: 0x8E44AD });

        monster.container.x = monster.x + shiver;
      } else {
        monster.container.scale.set(1.0);
        monster.tongueGfx.clear();
        monster.container.x = monster.x;
      }
    }

    if (this.isCandyFlying) {
      this.candyX += this.candyVx * deltaSec;
      this.candyY += this.candyVy * deltaSec;

      if (this.candyX < 30) {
        this.candyX = 30;
        this.candyVx = -this.candyVx;
        SoundSynth.playPlushSqueak();
      } else if (this.candyX > this.screenW - 30) {
        this.candyX = this.screenW - 30;
        this.candyVx = -this.candyVx;
        SoundSynth.playPlushSqueak();
      }

      this.flyingCandyContainer.x = this.candyX;
      this.flyingCandyContainer.y = this.candyY;
      this.flyingCandyContainer.rotation += 15 * deltaSec;

      for (const monster of this.monsters) {
        const dx = Math.abs(this.candyX - monster.x);
        const dy = Math.abs(this.candyY - monster.y);
        if (dx < monster.width / 2 + 15 && dy < monster.height / 2 + 15) {
          this.handleMonsterCollision(monster);
          return;
        }
      }

      if (this.candyY < 120) {
        let closest: TopMonster | null = null;
        let minDist = 9999;
        for (const m of this.monsters) {
          const d = Math.abs(this.candyX - m.x);
          if (d < minDist) {
            minDist = d;
            closest = m;
          }
        }
        if (closest) {
          this.handleMonsterCollision(closest);
        } else {
          this.isCandyFlying = false;
          this.renderSlingshot();
        }
      }
    }
  }
}
