import './styles/main.css';
import { GameApp } from './engine/App';
import { GameState } from './state/GameState';
import { SceneManager } from './scenes/SceneManager';

window.addEventListener('DOMContentLoaded', async () => {
  const container = document.getElementById('app');
  if (container) {
    const game = new GameApp();
    await game.start(container);

    // Expose for automated validation and debugging
    (window as any).__COSMOBOT__ = {
      app: game,
      gameState: GameState.getInstance(),
      sceneManager: SceneManager.getInstance()
    };
  }

  // Register PWA Service Worker for offline play
  if ('serviceWorker' in navigator) {
    try {
      await navigator.serviceWorker.register('./sw.js');
      console.log('CosmoBot PWA Service Worker registered successfully.');
    } catch (err) {
      console.warn('Service worker registration failed:', err);
    }
  }
});
