export type MusicTheme = 'adventure' | 'sanctuary' | 'arcade_rush' | 'off';

export class MusicPlayer {
  private static ctx: AudioContext | null = null;
  private static currentTheme: MusicTheme = 'off';
  private static isPlaying: boolean = false;
  private static loopTimer: number | null = null;
  private static volume: number = 0.35;
  private static isMuted: boolean = false;

  private static initContext() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  static setVolume(vol: number) {
    this.volume = Math.max(0, Math.min(1, vol));
  }

  static setMuted(muted: boolean) {
    this.isMuted = muted;
    if (muted) {
      this.stop();
    }
  }

  static playTheme(theme: MusicTheme) {
    if (this.currentTheme === theme && this.isPlaying) return;
    this.stop();
    this.currentTheme = theme;
    if (theme === 'off' || this.isMuted) return;

    this.isPlaying = true;
    this.scheduleLoop();
  }

  static stop() {
    this.isPlaying = false;
    if (this.loopTimer) {
      clearTimeout(this.loopTimer);
      this.loopTimer = null;
    }
  }

  private static scheduleLoop() {
    if (!this.isPlaying || this.isMuted) return;
    this.initContext();
    if (!this.ctx) return;

    const loopLengthMs = this.playPhrase(this.currentTheme);
    this.loopTimer = window.setTimeout(() => {
      this.scheduleLoop();
    }, loopLengthMs);
  }

  private static playPhrase(theme: MusicTheme): number {
    if (!this.ctx || this.isMuted) return 2000;

    let bpm = 120;
    let notes: { pitch: number; dur: number; offset: number }[] = [];

    if (theme === 'adventure') {
      bpm = 128;
      const beat = 60 / bpm;
      const melody = [
        { note: 523.25, d: 1 },  // C5
        { note: 587.33, d: 1 },  // D5
        { note: 659.25, d: 1 },  // E5
        { note: 783.99, d: 1 },  // G5
        { note: 880.00, d: 1 },  // A5
        { note: 783.99, d: 1 },  // G5
        { note: 659.25, d: 1 },  // E5
        { note: 523.25, d: 1 },  // C5
      ];
      let t = 0;
      melody.forEach(m => {
        notes.push({ pitch: m.note, dur: m.d * beat * 0.8, offset: t });
        notes.push({ pitch: m.note / 2, dur: m.d * beat * 0.5, offset: t });
        t += m.d * beat;
      });
      this.synthesizeNotes(notes);
      return t * 1000;
    } else if (theme === 'sanctuary') {
      bpm = 90;
      const beat = 60 / bpm;
      const chords = [
        [261.63, 329.63, 392.00],
        [220.00, 261.63, 329.63],
        [174.61, 220.00, 261.63],
        [196.00, 246.94, 293.66]
      ];
      let t = 0;
      chords.forEach(chord => {
        chord.forEach(p => {
          notes.push({ pitch: p, dur: beat * 1.8, offset: t });
        });
        t += beat * 2;
      });
      this.synthesizeNotes(notes, 'sine', 0.5);
      return t * 1000;
    } else {
      bpm = 140;
      const beat = 60 / bpm;
      const bass = [130.81, 146.83, 164.81, 196.00];
      let t = 0;
      for (let i = 0; i < 8; i++) {
        const p = bass[i % bass.length];
        notes.push({ pitch: p, dur: beat * 0.4, offset: t });
        notes.push({ pitch: p * 2, dur: beat * 0.2, offset: t + beat * 0.25 });
        t += beat * 0.5;
      }
      this.synthesizeNotes(notes, 'triangle', 0.6);
      return t * 1000;
    }
  }

  private static synthesizeNotes(
    notes: { pitch: number; dur: number; offset: number }[],
    type: OscillatorType = 'triangle',
    volFactor: number = 1
  ) {
    if (!this.ctx || this.isMuted) return;
    const now = this.ctx.currentTime;

    notes.forEach(n => {
      try {
        if (!this.ctx) return;
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = type;
        osc.frequency.setValueAtTime(n.pitch, now + n.offset);

        const targetVol = this.volume * volFactor * 0.2;
        gain.gain.setValueAtTime(targetVol, now + n.offset);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + n.offset + n.dur);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now + n.offset);
        osc.stop(now + n.offset + n.dur);
      } catch {
        // ignore
      }
    });
  }
}
