import { Container, Application } from 'pixi.js';

export interface GameScene extends Container {
  update?(deltaSec: number): void;
  resize?(width: number, height: number): void;
  onEnter?(): void;
  onExit?(): void;
}

export class SceneManager {
  private static instance: SceneManager;
  private currentScene: GameScene | null = null;
  private sceneContainer: Container;
  private width: number = 800;
  private height: number = 600;

  private constructor() {
    this.sceneContainer = new Container();
  }

  static getInstance(): SceneManager {
    if (!SceneManager.instance) {
      SceneManager.instance = new SceneManager();
    }
    return SceneManager.instance;
  }

  init(app: Application) {
    app.stage.addChild(this.sceneContainer);
  }

  changeScene(newScene: GameScene) {
    if (this.currentScene) {
      if (this.currentScene.onExit) {
        this.currentScene.onExit();
      }
      this.sceneContainer.removeChild(this.currentScene);
      this.currentScene.destroy({ children: true });
    }

    this.currentScene = newScene;
    this.sceneContainer.addChild(newScene);

    if (newScene.resize) {
      newScene.resize(this.width, this.height);
    }
    if (newScene.onEnter) {
      newScene.onEnter();
    }
  }

  update(deltaSec: number) {
    if (this.currentScene && this.currentScene.update) {
      this.currentScene.update(deltaSec);
    }
  }

  resize(width: number, height: number) {
    this.width = width;
    this.height = height;
    if (this.currentScene && this.currentScene.resize) {
      this.currentScene.resize(width, height);
    }
  }

  getWidth(): number {
    return this.width;
  }

  getHeight(): number {
    return this.height;
  }
}
