import { UserProgress, MathQuestion, StageDefinition, WorldId } from '../types/game';
import { Storage, DEFAULT_PROGRESS } from './Storage';
import { WORLDS, ACCESSORIES } from '../math/CurriculumData';
import { SoundSynth } from '../audio/SoundSynth';
import { MusicPlayer } from '../audio/MusicPlayer';
import { SpeechHelper } from '../math/SpeechHelper';

export class GameState {
  private static instance: GameState;
  public progress: UserProgress;

  private constructor() {
    this.progress = Storage.load();
    this.updateStreak();
    this.applySettings();
  }

  static getInstance(): GameState {
    if (!GameState.instance) {
      GameState.instance = new GameState();
    }
    return GameState.instance;
  }

  save() {
    Storage.save(this.progress);
  }

  private updateStreak() {
    const today = new Date().toISOString().split('T')[0];
    const last = this.progress.lastPlayedDate;
    if (last !== today) {
      const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
      if (last === yesterday) {
        this.progress.streakDays += 1;
      } else {
        this.progress.streakDays = 1;
      }
      this.progress.lastPlayedDate = today;
      this.progress.starCoins += 5;
      this.save();
    }
  }

  applySettings() {
    const isMuted = this.progress.settings.sfxVolume === 0 && this.progress.settings.musicVolume === 0;
    SoundSynth.setMuted(isMuted);
    MusicPlayer.setMuted(isMuted);
    if (!isMuted) {
      SoundSynth.setVolume(this.progress.settings.sfxVolume);
      MusicPlayer.setVolume(this.progress.settings.musicVolume);
    }
    SpeechHelper.setEnabled(this.progress.settings.voiceEnabled);
    SpeechHelper.setSpeed(this.progress.settings.voiceSpeed);
  }

  toggleSound(): boolean {
    const isCurrentlyMuted = SoundSynth.isMuted() || (this.progress.settings.sfxVolume === 0 && this.progress.settings.musicVolume === 0);
    const newMuted = !isCurrentlyMuted;

    SoundSynth.setMuted(newMuted);
    MusicPlayer.setMuted(newMuted);

    if (newMuted) {
      this.progress.settings.sfxVolume = 0;
      this.progress.settings.musicVolume = 0;
    } else {
      this.progress.settings.sfxVolume = 0.8;
      this.progress.settings.musicVolume = 0.4;
      SoundSynth.setVolume(0.8);
      MusicPlayer.setVolume(0.4);
    }
    this.save();
    return !newMuted;
  }

  isSoundEnabled(): boolean {
    return !SoundSynth.isMuted() && (this.progress.settings.sfxVolume > 0 || this.progress.settings.musicVolume > 0);
  }

  getTotalStars(): number {
    return Object.values(this.progress.stageStars).reduce((sum, stars) => sum + stars, 0);
  }

  /**
   * Check if an overworld/planet is unlocked according to linear progression.
   * World 1 is always unlocked.
   * World N (N > 1) is unlocked if all 12 nodes of all previous worlds (1 to N-1) have >= 1 star.
   */
  isWorldUnlocked(worldId: WorldId): boolean {
    if (worldId === 'world_1') return true;
    const worldOrder: WorldId[] = ['world_1', 'world_2', 'world_3', 'world_4', 'world_5'];
    const worldIdx = worldOrder.indexOf(worldId);
    if (worldIdx <= 0) return false;

    for (let w = 0; w < worldIdx; w++) {
      const prevWorldNum = w + 1;
      for (let n = 1; n <= 12; n++) {
        const nodeId = `w${prevWorldNum}_n${n}`;
        const stars = this.progress.stageStars[nodeId] || 0;
        if (stars < 1) {
          return false;
        }
      }
    }
    return true;
  }

  /**
   * Check if an overworld node is unlocked.
   * Supports both (nodeId: string) and (worldId: WorldId, nodeIndex: number).
   */
  isNodeUnlocked(arg1: string | WorldId, arg2?: number): boolean {
    let worldId: WorldId;
    let nodeIndex: number;

    if (typeof arg2 === 'number') {
      worldId = arg1 as WorldId;
      nodeIndex = arg2;
    } else {
      const match = (arg1 as string).match(/^w([1-5])_n([1-9]|1[0-2])$/);
      if (!match) return false;
      const worldNum = parseInt(match[1], 10);
      const nodeNum = parseInt(match[2], 10);
      worldId = `world_${worldNum}` as WorldId;
      nodeIndex = nodeNum - 1;
    }

    const worldOrder: WorldId[] = ['world_1', 'world_2', 'world_3', 'world_4', 'world_5'];
    const worldNum = worldOrder.indexOf(worldId) + 1;
    if (worldNum === 0) return false;

    if (!this.isWorldUnlocked(worldId)) {
      return false;
    }

    if (nodeIndex === 0) {
      return true;
    }

    if (nodeIndex < 0 || nodeIndex > 11) {
      return false;
    }

    const prevNodeId = `w${worldNum}_n${nodeIndex}`;
    const prevStars = this.progress.stageStars[prevNodeId] || 0;
    return prevStars >= 1;
  }

  /**
   * Get total stars earned on all 12 nodes of a world.
   */
  getWorldStars(worldId: WorldId): number {
    const worldOrder: WorldId[] = ['world_1', 'world_2', 'world_3', 'world_4', 'world_5'];
    const worldNum = worldOrder.indexOf(worldId) + 1;
    if (worldNum === 0) return 0;

    let total = 0;
    for (let n = 1; n <= 12; n++) {
      total += this.progress.stageStars[`w${worldNum}_n${n}`] || 0;
    }
    return total;
  }

  /**
   * Get number of completed nodes (stars >= 1) in a world.
   */
  getWorldCompletedNodeCount(worldId: WorldId): number {
    const worldOrder: WorldId[] = ['world_1', 'world_2', 'world_3', 'world_4', 'world_5'];
    const worldNum = worldOrder.indexOf(worldId) + 1;
    if (worldNum === 0) return 0;

    let count = 0;
    for (let n = 1; n <= 12; n++) {
      if ((this.progress.stageStars[`w${worldNum}_n${n}`] || 0) >= 1) {
        count++;
      }
    }
    return count;
  }

  /**
   * Helper to complete an overworld level node directly.
   */
  completeNode(nodeId: string, stars: number, score: number = 0): { starsEarned: number } {
    const prevStars = this.progress.stageStars[nodeId] || 0;
    if (stars > prevStars) {
      this.progress.stageStars[nodeId] = stars;
      this.progress.starCoins += (stars - prevStars) * 3;
    }

    const prevHigh = this.progress.stageHighScores[nodeId] || 0;
    if (score > prevHigh) {
      this.progress.stageHighScores[nodeId] = score;
    }

    this.save();
    return { starsEarned: stars };
  }

  isStageUnlocked(stage: StageDefinition): boolean {
    if (this.progress.unlockedStages[stage.id]) return true;
    const totalStars = this.getTotalStars();
    if (totalStars >= stage.starsRequiredToUnlock) {
      this.progress.unlockedStages[stage.id] = true;
      this.save();
      return true;
    }
    return false;
  }

  recordAnswer(q: MathQuestion, isCorrect: boolean) {
    const domain = q.domain;
    if (!this.progress.standardsMastery[domain]) {
      this.progress.standardsMastery[domain] = { correct: 0, total: 0 };
    }
    this.progress.standardsMastery[domain].total += 1;
    if (isCorrect) {
      this.progress.standardsMastery[domain].correct += 1;
      this.progress.levelXP += 10;
      this.progress.starCoins += 1;
      this.progress.totalScore += 100;
    }

    if (!this.progress.stageAttempts[q.stageId]) {
      this.progress.stageAttempts[q.stageId] = { correct: 0, total: 0 };
    }
    this.progress.stageAttempts[q.stageId].total += 1;
    if (isCorrect) {
      this.progress.stageAttempts[q.stageId].correct += 1;
    }

    this.save();
  }

  completeStage(stageId: string, correctCount: number, totalCount: number, score: number): { starsEarned: number; newBadges: string[] } {
    const accuracy = totalCount > 0 ? correctCount / totalCount : 0;
    let stars = 1;
    if (accuracy >= 0.9) stars = 3;
    else if (accuracy >= 0.75) stars = 2;

    const prevStars = this.progress.stageStars[stageId] || 0;
    if (stars > prevStars) {
      this.progress.stageStars[stageId] = stars;
      this.progress.starCoins += (stars - prevStars) * 3;
    }

    const prevHigh = this.progress.stageHighScores[stageId] || 0;
    if (score > prevHigh) {
      this.progress.stageHighScores[stageId] = score;
    }

    WORLDS.forEach(w => {
      w.stages.forEach(s => {
        if (this.getTotalStars() >= s.starsRequiredToUnlock) {
          this.progress.unlockedStages[s.id] = true;
        }
      });
    });

    const newBadges: string[] = [];
    const allStages = WORLDS.flatMap(w => w.stages);
    const stageDef = allStages.find(s => s.id === stageId);
    if (stageDef && stageDef.badgeRewardId && !this.progress.badges.includes(stageDef.badgeRewardId)) {
      this.progress.badges.push(stageDef.badgeRewardId);
      newBadges.push(stageDef.badgeRewardId);
    }

    const totalPossibleStars = allStages.length * 3;
    if (this.getTotalStars() >= totalPossibleStars * 0.8 && !this.progress.badges.includes('badge_grand_master')) {
      this.progress.badges.push('badge_grand_master');
      newBadges.push('badge_grand_master');
    }

    this.save();
    return { starsEarned: stars, newBadges };
  }

  buyAccessory(itemId: string): boolean {
    const item = ACCESSORIES.find(a => a.id === itemId);
    if (!item) return false;
    if (this.progress.inventory.includes(itemId)) return true;
    if (this.progress.starCoins >= item.cost) {
      this.progress.starCoins -= item.cost;
      this.progress.inventory.push(itemId);
      this.save();
      return true;
    }
    return false;
  }

  equipAccessory(itemId: string) {
    const item = ACCESSORIES.find(a => a.id === itemId);
    if (!item || !this.progress.inventory.includes(itemId)) return;
    this.progress.equippedAccessories[item.category] = itemId;
    this.save();
  }

  resetProgress() {
    this.progress = JSON.parse(JSON.stringify(DEFAULT_PROGRESS));
    this.save();
  }
}

