import { Container, Graphics } from 'pixi.js';
import confetti from 'canvas-confetti';

interface Particle {
  gfx: Graphics;
  x: number;
  y: number;
  vx: number;
  vy: number;
  alpha: number;
  decay: number;
  scale: number;
  scaleSpeed: number;
  rotation: number;
  rotSpeed: number;
}

export class ParticleSystem extends Container {
  private particles: Particle[] = [];

  constructor() {
    super();
  }

  emitStarBurst(x: number, y: number, count: number = 15, colors: number[] = [0xFFD32A, 0xFF6B81, 0x70A1FF, 0x2ED573]) {
    for (let i = 0; i < count; i++) {
      const gfx = new Graphics();
      const color = colors[Math.floor(Math.random() * colors.length)];
      const size = Math.random() * 6 + 4;

      // Draw star / diamond
      gfx.moveTo(0, -size);
      gfx.lineTo(size * 0.7, 0);
      gfx.lineTo(0, size);
      gfx.lineTo(-size * 0.7, 0);
      gfx.closePath();
      gfx.fill({ color });

      const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.5;
      const speed = Math.random() * 180 + 80;

      const p: Particle = {
        gfx,
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        alpha: 1,
        decay: Math.random() * 1.5 + 1.2,
        scale: 1,
        scaleSpeed: -0.5,
        rotation: Math.random() * Math.PI,
        rotSpeed: (Math.random() - 0.5) * 8
      };

      gfx.x = x;
      gfx.y = y;
      this.addChild(gfx);
      this.particles.push(p);
    }
  }

  emitSmokePuff(x: number, y: number) {
    const gfx = new Graphics();
    const radius = Math.random() * 8 + 6;
    gfx.circle(0, 0, radius);
    gfx.fill({ color: 0xCED6E0, alpha: 0.6 });

    const angle = Math.PI / 2 + (Math.random() - 0.5) * 0.8;
    const speed = Math.random() * 60 + 40;

    const p: Particle = {
      gfx,
      x,
      y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      alpha: 0.7,
      decay: 2.0,
      scale: 1,
      scaleSpeed: 0.8,
      rotation: 0,
      rotSpeed: 0
    };

    gfx.x = x;
    gfx.y = y;
    this.addChild(gfx);
    this.particles.push(p);
  }

  update(deltaSec: number) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx * deltaSec;
      p.y += p.vy * deltaSec;
      p.alpha -= p.decay * deltaSec;
      p.scale += p.scaleSpeed * deltaSec;
      p.rotation += p.rotSpeed * deltaSec;

      p.gfx.x = p.x;
      p.gfx.y = p.y;
      p.gfx.alpha = Math.max(0, p.alpha);
      p.gfx.scale.set(Math.max(0, p.scale));
      p.gfx.rotation = p.rotation;

      if (p.alpha <= 0 || p.scale <= 0) {
        this.removeChild(p.gfx);
        p.gfx.destroy();
        this.particles.splice(i, 1);
      }
    }
  }

  static triggerConfetti() {
    try {
      confetti({
        particleCount: 80,
        spread: 70,
        origin: { y: 0.6 },
        colors: ['#FF6B8B', '#FFD32A', '#2ED573', '#70A1FF', '#A55EEA']
      });
    } catch {
      // fallback
    }
  }
}
