export class SoundSynth {
  private static ctx: AudioContext | null = null;
  private static masterVolume: number = 0.8;
  private static muted: boolean = false;

  private static initContext() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  static setVolume(vol: number) {
    this.masterVolume = Math.max(0, Math.min(1, vol));
  }

  static setMuted(muted: boolean) {
    this.muted = muted;
  }

  static isMuted(): boolean {
    return this.muted;
  }

  static unlock() {
    this.initContext();
  }

  // Helper to play tone envelope
  private static playTone(
    freqStart: number,
    freqEnd: number,
    duration: number,
    type: OscillatorType = 'sine',
    volMult: number = 1
  ) {
    if (this.muted) return;
    this.initContext();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = type;
      osc.frequency.setValueAtTime(freqStart, now);
      osc.frequency.exponentialRampToValueAtTime(Math.max(10, freqEnd), now + duration);

      const targetVol = this.masterVolume * volMult;
      gain.gain.setValueAtTime(targetVol, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now);
      osc.stop(now + duration);
    } catch {
      // Audio context might be restricted
    }
  }

  // SFX 1: Laser Blast
  static playLaser() {
    this.playTone(880, 110, 0.15, 'sawtooth', 0.5);
  }

  // SFX 2: Correct Answer Chime (Sparkly Major Triad)
  static playCorrect() {
    if (this.muted) return;
    this.initContext();
    if (!this.ctx) return;

    const notes = [523.25, 659.25, 783.99, 1046.5]; // C5, E5, G5, C6
    notes.forEach((freq, idx) => {
      setTimeout(() => {
        this.playTone(freq, freq * 1.05, 0.25, 'triangle', 0.6);
      }, idx * 60);
    });
  }

  // SFX 3: Wrong Answer Gentle Boing
  static playWrong() {
    this.playTone(220, 110, 0.3, 'sine', 0.5);
  }

  // SFX 4: Star Pickup Ding
  static playStar() {
    this.playTone(1318.51, 1567.98, 0.2, 'sine', 0.6); // E6 -> G6
  }

  // SFX 5: Combo Fanfare
  static playCombo(comboLevel: number) {
    const base = 440 * Math.pow(1.12, Math.min(10, comboLevel));
    this.playTone(base, base * 1.5, 0.2, 'triangle', 0.7);
  }

  // SFX 6: Plush Robot Squeak (Cute high squeak)
  static playPlushSqueak() {
    this.playTone(1800, 2400, 0.12, 'sine', 0.4);
    setTimeout(() => {
      this.playTone(2400, 1600, 0.1, 'sine', 0.4);
    }, 100);
  }

  // SFX 7: Jetpack Thruster Puff
  static playThruster() {
    if (this.muted) return;
    this.initContext();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      // White noise buffer for thruster puff
      const bufferSize = this.ctx.sampleRate * 0.08;
      const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        data[i] = Math.random() * 2 - 1;
      }

      const noise = this.ctx.createBufferSource();
      noise.buffer = buffer;

      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(600, now);

      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(this.masterVolume * 0.25, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);

      noise.connect(filter);
      filter.connect(gain);
      gain.connect(this.ctx.destination);

      noise.start(now);
    } catch {
      // ignore
    }
  }

  // SFX 8: Alien Snack Gulp (Nom Nom)
  static playNom() {
    this.playTone(300, 600, 0.08, 'sine', 0.5);
    setTimeout(() => {
      this.playTone(600, 200, 0.12, 'triangle', 0.6);
    }, 80);
  }

  // SFX 9: Level Clear Fanfare
  static playLevelClear() {
    if (this.muted) return;
    this.initContext();
    if (!this.ctx) return;

    const melody = [
      { f: 523.25, d: 0.12 }, // C5
      { f: 659.25, d: 0.12 }, // E5
      { f: 783.99, d: 0.12 }, // G5
      { f: 1046.5, d: 0.2 },  // C6
      { f: 880.0, d: 0.15 },  // A5
      { f: 1046.5, d: 0.4 }   // C6 long
    ];

    let delay = 0;
    melody.forEach(n => {
      setTimeout(() => {
        this.playTone(n.f, n.f * 1.02, n.d, 'triangle', 0.7);
      }, delay);
      delay += n.d * 1000 + 40;
    });
  }

  // SFX 10: UI Button Click
  static playClick() {
    this.playTone(600, 900, 0.05, 'sine', 0.3);
  }

  // Mobile Haptic Feedback helper
  static triggerHaptic(duration: number = 30) {
    if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
      try {
        navigator.vibrate(duration);
      } catch {
        // ignore
      }
    }
  }
}
