import { Container, Graphics, Text, TextStyle } from 'pixi.js';
import { GameScene, SceneManager } from './SceneManager';
import { GameState } from '../state/GameState';
import { PlushRobot } from '../entities/PlushRobot';
import { ACCESSORIES, BADGES } from '../math/CurriculumData';
import { AccessoryItem, BadgeItem } from '../types/game';
import { WorldMapScene } from './WorldMapScene';
import { UIHelper } from '../engine/UIHelper';
import { SoundSynth } from '../audio/SoundSynth';
import { MusicPlayer } from '../audio/MusicPlayer';

export class DressUpScene extends Container implements GameScene {
  private screenW: number = 800;
  private screenH: number = 600;

  private bgGfx: Graphics;
  private portholeGfx: Graphics;
  private jukeboxGfx: Graphics;
  private rugGfx: Graphics;
  private itemsContainer: Container;
  private headerContainer: Container;

  private pip: PlushRobot;
  private selectedCategory: string = 'hat';

  constructor() {
    super();
    this.bgGfx = new Graphics();
    this.portholeGfx = new Graphics();
    this.rugGfx = new Graphics();
    this.jukeboxGfx = new Graphics();
    this.itemsContainer = new Container();
    this.headerContainer = new Container();

    this.addChild(this.bgGfx);
    this.addChild(this.portholeGfx);
    this.addChild(this.rugGfx);
    this.addChild(this.jukeboxGfx);
    this.addChild(this.itemsContainer);
    this.addChild(this.headerContainer);

    this.pip = new PlushRobot(1.0);
    this.addChild(this.pip);
  }

  onEnter() {
    MusicPlayer.playTheme('sanctuary');
    this.renderAll();
  }

  resize(w: number, h: number) {
    this.screenW = w;
    this.screenH = h;
    this.pip.x = w * 0.28;
    this.pip.y = h * 0.42;
    this.renderAll();
  }

  private renderAll() {
    this.renderBackground();
    this.renderHeader();
    this.renderCategoryTabs();
    this.renderItems();
  }

  private renderBackground() {
    const w = this.screenW;
    const h = this.screenH;

    this.bgGfx.clear();
    this.bgGfx.rect(0, 0, w, h);
    this.bgGfx.fill({ color: 0x181736 });

    this.rugGfx.clear();
    this.rugGfx.ellipse(w * 0.28, h * 0.48, 110, 45);
    this.rugGfx.fill({ color: 0x2A2756 });
    this.rugGfx.stroke({ width: 2.5, color: 0x6C5CE7 });

    this.portholeGfx.clear();
    const pwX = w * 0.14;
    const pwY = 110;
    this.portholeGfx.circle(pwX, pwY, 38);
    this.portholeGfx.fill({ color: 0x0A0D22 });
    this.portholeGfx.stroke({ width: 4, color: 0xF1C40F });

    this.portholeGfx.circle(pwX + 10, pwY + 12, 24);
    this.portholeGfx.fill({ color: 0x3498DB });
    this.portholeGfx.stroke({ width: 1.5, color: 0x2ECC71 });

    this.jukeboxGfx.clear();
    const jx = w * 0.45;
    const jy = h * 0.38;
    this.jukeboxGfx.roundRect(jx - 24, jy - 36, 48, 72, 16);
    this.jukeboxGfx.fill({ color: 0xE74C3C });
    this.jukeboxGfx.stroke({ width: 2.5, color: 0xF1C40F });

    this.jukeboxGfx.circle(jx, jy - 10, 14);
    this.jukeboxGfx.fill({ color: 0x2C3E50 });
    this.jukeboxGfx.stroke({ width: 1.5, color: 0xECF0F1 });
  }

  private renderHeader() {
    this.headerContainer.removeChildren();
    const w = this.screenW;
    const state = GameState.getInstance();

    const topBar = new Graphics();
    topBar.rect(0, 0, w, 56);
    topBar.fill({ color: 0x121028, alpha: 0.98 });
    topBar.stroke({ width: 1.5, color: 0x2E2958 });
    this.headerContainer.addChild(topBar);

    const backBtn = UIHelper.createButton('◀ Galaxy Map', 110, 32, 0x6C5CE7, '#FFFFFF', 12, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    backBtn.x = 70;
    backBtn.y = 28;
    this.headerContainer.addChild(backBtn);

    const title = new Text({
      text: "🧸 Pip's Cozy Orbit Habitat",
      style: new TextStyle({ fontSize: 16, fontWeight: 'bold', fill: '#FFD32A' })
    });
    title.anchor.set(0.5);
    title.x = w / 2;
    title.y = 28;
    this.headerContainer.addChild(title);

    const coinHud = new Text({
      text: `🪙 ${state.progress.starCoins} Coins`,
      style: new TextStyle({ fontSize: 13, fontWeight: 'bold', fill: '#FFD32A' })
    });
    coinHud.anchor.set(1, 0.5);
    coinHud.x = w - 20;
    coinHud.y = 28;
    this.headerContainer.addChild(coinHud);
  }

  private renderCategoryTabs() {
    const w = this.screenW;
    const categories = [
      { id: 'hat', label: '👑 Hats' },
      { id: 'scarf', label: '🧣 Scarves' },
      { id: 'back', label: '🎒 Back' },
      { id: 'companion', label: '🐾 Pets' },
      { id: 'skin', label: '🎨 Skins' },
      { id: 'badge', label: '🏆 Badges' }
    ];

    const tabCount = categories.length;
    const tabW = (w - 20) / tabCount;

    categories.forEach((cat, idx) => {
      const isSelected = cat.id === this.selectedCategory;
      const x = 10 + idx * tabW + tabW / 2;
      const y = 84;

      const tabContainer = new Container();
      tabContainer.eventMode = 'static';
      tabContainer.cursor = 'pointer';

      const tabGfx = new Graphics();
      tabGfx.roundRect(-tabW / 2 + 2, -15, tabW - 4, 30, 8);
      tabGfx.fill({ color: isSelected ? 0x6C5CE7 : 0x221E47 });
      tabGfx.stroke({ width: isSelected ? 2 : 1, color: isSelected ? 0xFFD32A : 0x3E3875 });

      const text = new Text({
        text: cat.label,
        style: new TextStyle({
          fontSize: Math.min(12, tabW * 0.18),
          fontWeight: 'bold',
          fill: isSelected ? '#FFFFFF' : '#A4B0BE'
        })
      });
      text.anchor.set(0.5);

      tabContainer.addChild(tabGfx);
      tabContainer.addChild(text);
      tabContainer.x = x;
      tabContainer.y = y;

      tabContainer.on('pointerdown', () => {
        this.selectedCategory = cat.id;
        this.renderAll();
      });

      this.headerContainer.addChild(tabContainer);
    });
  }

  private renderItems() {
    this.itemsContainer.removeChildren();
    const w = this.screenW;
    const h = this.screenH;

    const startY = h * 0.58;
    const items: (AccessoryItem | BadgeItem)[] =
      this.selectedCategory === 'badge'
        ? BADGES
        : ACCESSORIES.filter((a) => a.category === this.selectedCategory);

    const cols = Math.min(4, Math.floor((w - 20) / 100));
    const cardW = (w - 30) / cols - 8;
    const cardH = 88;

    items.forEach((item, idx: number) => {
      const col = idx % cols;
      const row = Math.floor(idx / cols);
      const x = 15 + col * (cardW + 8) + cardW / 2;
      const y = startY + row * (cardH + 10);

      const card = this.createItemCard(item, cardW, cardH);
      card.x = x;
      card.y = y;
      this.itemsContainer.addChild(card);
    });
  }

  private createItemCard(item: AccessoryItem | BadgeItem, width: number, height: number): Container {
    const container = new Container();
    container.eventMode = 'static';
    container.cursor = 'pointer';

    const state = GameState.getInstance();
    const isBadge = this.selectedCategory === 'badge';
    const isUnlocked = isBadge
      ? state.progress.badges.includes(item.id)
      : state.progress.inventory.includes(item.id) || (item as AccessoryItem).cost === 0;

    const equippedMap = state.progress.equippedAccessories as Record<string, string | undefined>;
    const isEquipped = !isBadge && equippedMap[this.selectedCategory] === item.id;

    const bg = new Graphics();
    bg.roundRect(-width / 2, -height / 2, width, height, 12);
    bg.fill({ color: isEquipped ? 0x6C5CE7 : isUnlocked ? 0x221E47 : 0x15122D });
    bg.stroke({ width: isEquipped ? 2.5 : 1.5, color: isEquipped ? 0xFFD32A : isUnlocked ? 0x00D2D3 : 0x3E3875 });

    const icon = new Text({
      text: item.icon,
      style: new TextStyle({ fontSize: 26 })
    });
    icon.anchor.set(0.5);
    icon.y = -14;

    const name = new Text({
      text: item.name,
      style: new TextStyle({ fontSize: 10, fontWeight: 'bold', fill: '#FFFFFF', align: 'center' })
    });
    name.anchor.set(0.5);
    name.y = 16;

    let statusStr = isEquipped ? '✓ EQUIPPED' : isUnlocked ? 'EQUIP' : `🪙 ${(item as AccessoryItem).cost || 0}`;
    let statusColor = isEquipped ? '#FFD32A' : isUnlocked ? '#00D2D3' : '#F1C40F';
    if (isBadge) {
      statusStr = isUnlocked ? '★ UNLOCKED' : 'LOCKED';
      statusColor = isUnlocked ? '#FFD32A' : '#747D8C';
    }

    const status = new Text({
      text: statusStr,
      style: new TextStyle({ fontSize: 9, fontWeight: 'bold', fill: statusColor })
    });
    status.anchor.set(0.5);
    status.y = 30;

    container.addChild(bg);
    container.addChild(icon);
    container.addChild(name);
    container.addChild(status);

    container.on('pointerdown', () => {
      if (isBadge) return;

      if (!isUnlocked) {
        if (state.buyAccessory(item.id)) {
          state.equipAccessory(item.id);
          SoundSynth.playLevelClear();
          this.pip.renderRobot();
          this.pip.doHappyJump();
          this.renderAll();
        } else {
          SoundSynth.playWrong();
        }
      } else {
        state.equipAccessory(item.id);
        SoundSynth.playClick();
        this.pip.renderRobot();
        this.renderAll();
      }
    });

    return container;
  }

  update(deltaSec: number) {
    this.pip.update(deltaSec);
  }
}
