import { Container, Graphics, Text, TextStyle, Rectangle } from 'pixi.js';
import { GameScene, SceneManager } from './SceneManager';
import { StageDefinition, MathQuestion } from '../types/game';
import { MathGenerator } from '../math/MathGenerator';
import { GameState } from '../state/GameState';
import { PlushRobot } from '../entities/PlushRobot';
import { ParticleSystem } from '../engine/ParticleSystem';
import { VisualManipulative } from '../entities/VisualManipulative';
import { UIHelper } from '../engine/UIHelper';
import { SoundSynth } from '../audio/SoundSynth';
import { MusicPlayer } from '../audio/MusicPlayer';
import { SpeechHelper } from '../math/SpeechHelper';
import { WorldMapScene } from './WorldMapScene';

interface FlightItem {
  container: Container;
  gfx: Graphics;
  text?: Text;
  answer?: string | number;
  isCorrect?: boolean;
  isAsteroid?: boolean;
  x: number;
  y: number;
  width: number;
  height: number;
}

export class JetpackScene extends Container implements GameScene {
  private stageDef: StageDefinition;
  private currentQuestion: MathQuestion | null = null;
  private questionsAnswered: number = 0;
  private correctAnswers: number = 0;
  private score: number = 0;

  private screenW: number = 800;
  private screenH: number = 600;

  private bgGfx: Graphics;
  private starsLayer: Graphics;
  private gameLayer: Container;
  private gatesLayer: Container;
  private rocketShipGfx: Graphics;
  private rocketExhaustGfx: Graphics;
  private rocketContainer: Container;
  private uiLayer: Container;
  private particleSys: ParticleSystem;

  private pip: PlushRobot;
  private pipX: number = 400;
  private pipY: number = 480;
  private targetPipX: number = 400;
  private pipLerpSpeed: number = 10;

  private activeItems: FlightItem[] = [];
  private speedY: number = 95;
  private starfieldOffset: number = 0;
  private spawnTimer: number = 0;
  private isWaitingForNext: boolean = false;
  private rocketExhaustTimer: number = 0;

  private hintModal: Container | null = null;
  private isGameOver: boolean = false;

  constructor(stageDef: StageDefinition) {
    super();
    this.stageDef = stageDef;

    this.bgGfx = new Graphics();
    this.starsLayer = new Graphics();
    this.gameLayer = new Container();
    this.gatesLayer = new Container();
    this.particleSys = new ParticleSystem();
    this.uiLayer = new Container();

    this.addChild(this.bgGfx);
    this.addChild(this.starsLayer);
    this.addChild(this.gameLayer);
    this.gameLayer.addChild(this.gatesLayer);

    // Cute Cartoon Rocket Vehicle
    this.rocketContainer = new Container();
    this.rocketExhaustGfx = new Graphics();
    this.rocketShipGfx = new Graphics();
    this.pip = new PlushRobot(0.52);

    this.rocketContainer.addChild(this.rocketExhaustGfx);
    this.rocketContainer.addChild(this.rocketShipGfx);
    this.rocketContainer.addChild(this.pip);
    this.gameLayer.addChild(this.rocketContainer);

    this.addChild(this.particleSys);
    this.addChild(this.uiLayer);

    this.renderRocketShip();
    this.setupTouchControls();
  }

  onEnter() {
    MusicPlayer.playTheme('adventure');
    this.prepareFirstQuestion();
    this.renderUI();
  }

  resize(w: number, h: number) {
    this.screenW = w;
    this.screenH = h;
    this.hitArea = new Rectangle(0, 0, w, h);
    this.pipX = w / 2;
    this.targetPipX = w / 2;
    this.pipY = h - 140;
    this.rocketContainer.x = this.pipX;
    this.rocketContainer.y = this.pipY;
    this.renderBackground();
    this.renderUI();
  }

  private renderRocketShip() {
    this.rocketShipGfx.clear();

    // 1. Stabilizer Fins
    this.rocketShipGfx.moveTo(-22, 10);
    this.rocketShipGfx.lineTo(-44, 38);
    this.rocketShipGfx.lineTo(-20, 36);
    this.rocketShipGfx.fill({ color: 0xFF4757 });
    this.rocketShipGfx.stroke({ width: 2.5, color: 0x2F3542 });

    this.rocketShipGfx.moveTo(22, 10);
    this.rocketShipGfx.lineTo(44, 38);
    this.rocketShipGfx.lineTo(20, 36);
    this.rocketShipGfx.fill({ color: 0xFF4757 });
    this.rocketShipGfx.stroke({ width: 2.5, color: 0x2F3542 });

    // 2. Rocket Fuselage
    this.rocketShipGfx.roundRect(-24, -28, 48, 68, 20);
    this.rocketShipGfx.fill({ color: 0xF1F2F6 });
    this.rocketShipGfx.stroke({ width: 3, color: 0x2F3542 });

    this.rocketShipGfx.roundRect(-24, 6, 48, 12, 4);
    this.rocketShipGfx.fill({ color: 0xFFA502 });

    // 3. Rocket Nose Cone
    this.rocketShipGfx.moveTo(-20, -26);
    this.rocketShipGfx.bezierCurveTo(-18, -52, 18, -52, 20, -26);
    this.rocketShipGfx.fill({ color: 0xFF4757 });
    this.rocketShipGfx.stroke({ width: 3, color: 0x2F3542 });

    // 4. Cockpit Porthole Bubble
    this.rocketShipGfx.circle(0, -10, 14);
    this.rocketShipGfx.fill({ color: 0x70A1FF });
    this.rocketShipGfx.stroke({ width: 2.5, color: 0x2F3542 });
    this.rocketShipGfx.ellipse(-4, -14, 5, 2.5);
    this.rocketShipGfx.fill({ color: 0xFFFFFF, alpha: 0.85 });

    // 5. Engine Nozzle
    this.rocketShipGfx.roundRect(-16, 38, 32, 10, 4);
    this.rocketShipGfx.fill({ color: 0x747D8C });
    this.rocketShipGfx.stroke({ width: 2, color: 0x2F3542 });

    this.pip.y = -18;
    this.pip.x = 0;
  }

  private setupTouchControls() {
    this.eventMode = 'static';
    this.hitArea = new Rectangle(0, 0, this.screenW, this.screenH);

    this.bgGfx.eventMode = 'static';

    const handlePointer = (e: any) => {
      if (this.isGameOver) return;
      this.targetPipX = Math.max(50, Math.min(this.screenW - 50, e.global.x));
    };

    this.on('pointerdown', (e) => {
      handlePointer(e);
      SoundSynth.triggerHaptic(15);
    });
    this.on('pointermove', handlePointer);

    this.bgGfx.on('pointerdown', (e) => {
      handlePointer(e);
      SoundSynth.triggerHaptic(15);
    });
    this.bgGfx.on('pointermove', handlePointer);
  }

  private renderBackground() {
    const w = this.screenW;
    const h = this.screenH;

    this.bgGfx.clear();
    this.bgGfx.rect(0, 0, w, h);
    this.bgGfx.fill({ color: 0x070B19 });

    this.bgGfx.rect(0, 0, 15, h);
    this.bgGfx.rect(w - 15, 0, 15, h);
    this.bgGfx.fill({ color: 0x1E272E, alpha: 0.8 });
    this.bgGfx.stroke({ width: 1.5, color: 0x6C5CE7 });
  }

  private prepareFirstQuestion() {
    this.isWaitingForNext = true;
    this.currentQuestion = MathGenerator.generateQuestion(this.stageDef.id);
    this.renderUI();

    if (this.currentQuestion.speechPrompt) {
      SpeechHelper.speak(this.currentQuestion.speechPrompt);
    }

    this.spawnTimer = 3.2;
  }

  private nextQuestion() {
    if (this.questionsAnswered >= this.stageDef.targetCount) {
      this.triggerVictory();
      return;
    }

    this.isWaitingForNext = true;
    this.currentQuestion = MathGenerator.generateQuestion(this.stageDef.id);
    this.renderUI();

    if (this.currentQuestion.speechPrompt) {
      SpeechHelper.speak(this.currentQuestion.speechPrompt);
    }

    this.spawnTimer = 1.8;
  }

  private spawnVerticalGates(q: MathQuestion) {
    this.gatesLayer.removeChildren();
    this.activeItems = [];

    const options = [...q.options];
    if (!options.map(String).includes(String(q.correctAnswer))) {
      options.unshift(q.correctAnswer);
    }
    const count = options.length;
    const padding = 35;
    const availableW = this.screenW - padding * 2;
    const stepX = availableW / count;
    const gateW = Math.min(95, stepX - 10);
    const gateH = 68;
    const startY = -90;

    options.forEach((opt, idx) => {
      const isCorrect = String(opt) === String(q.correctAnswer);
      const container = new Container();
      const targetX = padding + idx * stepX + stepX / 2;

      const gfx = new Graphics();
      // ALL GATES ARE 100% IDENTICAL IN STYLING, BORDER, CORE, AND COLORS
      gfx.roundRect(-gateW / 2, -gateH / 2, gateW, gateH, 18);
      gfx.fill({ color: 0x1E272E, alpha: 0.94 });
      gfx.stroke({ width: 3.5, color: 0x70A1FF });

      gfx.roundRect(-gateW / 2 + 5, -gateH / 2 + 5, gateW - 10, gateH - 10, 14);
      gfx.fill({ color: 0x2C3A47, alpha: 0.75 });

      const text = new Text({
        text: String(opt),
        style: new TextStyle({
          fontSize: 18,
          fontWeight: 'bold',
          fill: '#FFFFFF',
          align: 'center'
        })
      });
      text.anchor.set(0.5);

      container.addChild(gfx);
      container.addChild(text);

      container.x = targetX;
      container.y = startY;

      this.gatesLayer.addChild(container);
      this.activeItems.push({
        container,
        gfx,
        text,
        answer: opt,
        isCorrect,
        isAsteroid: false,
        x: targetX,
        y: startY,
        width: gateW,
        height: gateH
      });
    });

    // Stray independent drifting asteroid (15% chance, drifting separately from gates)
    if (Math.random() < 0.15) {
      const astContainer = new Container();
      const astX = Math.random() < 0.5 ? 45 : this.screenW - 45;
      const astY = startY - 70;

      const astGfx = new Graphics();
      astGfx.circle(0, 0, 22);
      astGfx.circle(-10, 6, 10);
      astGfx.circle(10, -8, 11);
      astGfx.fill({ color: 0x8395A7 });
      astGfx.stroke({ width: 2.5, color: 0x222F3E });

      astGfx.circle(-6, -6, 5);
      astGfx.circle(8, 6, 6);
      astGfx.fill({ color: 0x576574 });

      astContainer.addChild(astGfx);
      astContainer.x = astX;
      astContainer.y = astY;

      this.gatesLayer.addChild(astContainer);
      this.activeItems.push({
        container: astContainer,
        gfx: astGfx,
        isAsteroid: true,
        x: astX,
        y: astY,
        width: 44,
        height: 44
      });
    }
  }

  private handleItemCollision(item: FlightItem) {
    if (!this.currentQuestion) return;

    if (item.isAsteroid) {
      SoundSynth.playWrong();
      SoundSynth.triggerHaptic(40);
      this.particleSys.emitSmokePuff(item.x, item.y);
      this.pip.doErrorShake();
      this.gatesLayer.removeChild(item.container);
      this.activeItems = this.activeItems.filter(it => it !== item);
      return;
    }

    if (item.isCorrect) {
      this.correctAnswers++;
      this.questionsAnswered++;
      this.score += 150;

      GameState.getInstance().recordAnswer(this.currentQuestion, true);
      SoundSynth.playCorrect();
      SoundSynth.playStar();
      SoundSynth.triggerHaptic(40);

      this.particleSys.emitStarBurst(this.rocketContainer.x, this.rocketContainer.y, 30);
      this.pip.doHappyJump();

      this.gatesLayer.removeChildren();
      this.activeItems = [];
      this.nextQuestion();
    } else {
      this.questionsAnswered++;
      GameState.getInstance().recordAnswer(this.currentQuestion, false);
      SoundSynth.playWrong();
      SoundSynth.triggerHaptic(60);

      this.pip.doErrorShake();
      this.gatesLayer.removeChildren();
      this.activeItems = [];
      this.showHintModal();
    }
    this.renderUI();
  }

  private showHintModal() {
    if (!this.currentQuestion) return;
    const modal = new Container();
    const mw = Math.min(500, this.screenW - 40);
    const mh = 320;
    const mx = (this.screenW - mw) / 2;
    const my = (this.screenH - mh) / 2;

    const bg = new Graphics();
    bg.roundRect(mx, my, mw, mh, 18);
    bg.fill({ color: 0x1E272E, alpha: 0.98 });
    bg.stroke({ width: 3, color: 0x10AC84 });
    modal.addChild(bg);

    const title = new Text({
      text: '🚀 Rocket Flight Guide',
      style: new TextStyle({ fontSize: 18, fontWeight: 'bold', fill: '#FFD32A' })
    });
    title.x = mx + 20;
    title.y = my + 15;
    modal.addChild(title);

    if (this.currentQuestion.manipulative) {
      const manip = new VisualManipulative(this.currentQuestion.manipulative, mw - 40, 140);
      manip.x = mx + 20;
      manip.y = my + 45;
      modal.addChild(manip);
    }

    const hintText = new Text({
      text: this.currentQuestion.hint,
      style: new TextStyle({ fontSize: 13, fill: '#FFFFFF', wordWrap: true, wordWrapWidth: mw - 40 })
    });
    hintText.x = mx + 20;
    hintText.y = my + 195;
    modal.addChild(hintText);

    const gotItBtn = UIHelper.createButton('Fly Onward! 🚀', 180, 40, 0x10AC84, '#FFFFFF', 14, () => {
      this.uiLayer.removeChild(modal);
      modal.destroy();
      this.hintModal = null;
      this.nextQuestion();
    });
    gotItBtn.x = mx + mw / 2;
    gotItBtn.y = my + mh - 35;
    modal.addChild(gotItBtn);

    this.hintModal = modal;
    this.uiLayer.addChild(modal);
  }

  private triggerVictory() {
    this.isGameOver = true;
    this.gatesLayer.removeChildren();

    const state = GameState.getInstance();
    const result = state.completeStage(
      this.stageDef.id,
      this.correctAnswers,
      this.stageDef.targetCount,
      this.score
    );

    SoundSynth.playLevelClear();
    ParticleSystem.triggerConfetti();

    const modal = new Container();
    const mw = Math.min(460, this.screenW - 40);
    const mh = 360;
    const mx = (this.screenW - mw) / 2;
    const my = (this.screenH - mh) / 2;

    const bg = new Graphics();
    bg.roundRect(mx, my, mw, mh, 20);
    bg.fill({ color: 0x1E272E, alpha: 0.98 });
    bg.stroke({ width: 3, color: 0x10AC84 });
    modal.addChild(bg);

    const title = new Text({
      text: '🚀 ROCKET FLIGHT COMPLETE!',
      style: new TextStyle({ fontSize: 20, fontWeight: 'bold', fill: '#10AC84', align: 'center' })
    });
    title.anchor.set(0.5);
    title.x = mx + mw / 2;
    title.y = my + 35;
    modal.addChild(title);

    const starsStr = '⭐'.repeat(result.starsEarned) + '☆'.repeat(3 - result.starsEarned);
    const starsText = new Text({
      text: starsStr,
      style: new TextStyle({ fontSize: 36, fill: '#FFD32A', align: 'center' })
    });
    starsText.anchor.set(0.5);
    starsText.x = mx + mw / 2;
    starsText.y = my + 85;
    modal.addChild(starsText);

    const scoreInfo = new Text({
      text: `Score: ${this.score}\nAccuracy: ${this.correctAnswers} / ${this.stageDef.targetCount} (${Math.round((this.correctAnswers / this.stageDef.targetCount) * 100)}%)\nStar Coins Earned: +${result.starsEarned * 3} 🪙`,
      style: new TextStyle({ fontSize: 15, fill: '#FFFFFF', align: 'center', lineHeight: 24 })
    });
    scoreInfo.anchor.set(0.5);
    scoreInfo.x = mx + mw / 2;
    scoreInfo.y = my + 175;
    modal.addChild(scoreInfo);

    const continueBtn = UIHelper.createButton('Back to Galaxy Map 🌌', 200, 44, 0x10AC84, '#FFFFFF', 14, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    continueBtn.x = mx + mw / 2;
    continueBtn.y = my + mh - 45;
    modal.addChild(continueBtn);

    this.uiLayer.addChild(modal);
  }

  private renderUI() {
    this.uiLayer.removeChildren();
    if (this.hintModal) {
      this.uiLayer.addChild(this.hintModal);
      return;
    }

    const w = this.screenW;

    const headerBg = new Graphics();
    headerBg.roundRect(10, 8, w - 20, 44, 12);
    headerBg.fill({ color: 0x1E272E, alpha: 0.9 });
    headerBg.stroke({ width: 1.5, color: 0x576574 });
    this.uiLayer.addChild(headerBg);

    const backBtn = UIHelper.createButton('◀ Exit', 70, 30, 0xFF4757, '#FFFFFF', 12, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    backBtn.x = 55;
    backBtn.y = 30;
    this.uiLayer.addChild(backBtn);

    const progressText = new Text({
      text: `Rocket ${this.questionsAnswered + 1}/${this.stageDef.targetCount} | Steer rocket into portal!`,
      style: new TextStyle({ fontSize: 13, fontWeight: 'bold', fill: '#10AC84' })
    });
    progressText.x = 105;
    progressText.y = 22;
    this.uiLayer.addChild(progressText);

    if (this.currentQuestion) {
      const qBg = new Graphics();
      qBg.roundRect(10, 56, w - 20, 48, 12);
      qBg.fill({ color: 0x2C3A47, alpha: 0.95 });
      qBg.stroke({ width: 2, color: 0x10AC84 });
      this.uiLayer.addChild(qBg);

      const qText = new Text({
        text: this.currentQuestion.prompt,
        style: new TextStyle({ fontSize: 16, fontWeight: 'bold', fill: '#FFFFFF' })
      });
      qText.x = 25;
      qText.y = 66;
      this.uiLayer.addChild(qText);

      const ttsBtn = UIHelper.createButton('🔊 Read', 64, 30, 0x10AC84, '#FFFFFF', 11, () => {
        if (this.currentQuestion?.speechPrompt) {
          SpeechHelper.speak(this.currentQuestion.speechPrompt);
        }
      });
      ttsBtn.x = w - 50;
      ttsBtn.y = 80;
      this.uiLayer.addChild(ttsBtn);
    }
  }

  update(deltaSec: number) {
    this.pip.update(deltaSec);
    this.particleSys.update(deltaSec);

    // Vertical Starfield Scroll
    this.starfieldOffset = (this.starfieldOffset + 70 * deltaSec) % this.screenH;
    this.starsLayer.clear();
    for (let i = 0; i < 45; i++) {
      const sx = (i * 127) % (this.screenW - 30) + 15;
      const sy = (i * 191 + this.starfieldOffset) % this.screenH;
      this.starsLayer.circle(sx, sy, (i % 2) + 1);
      this.starsLayer.fill({ color: 0xFFFFFF, alpha: 0.3 + (i % 4) * 0.18 });
    }

    if (this.isGameOver) return;

    // Smooth horizontal steering
    this.pipX += (this.targetPipX - this.pipX) * this.pipLerpSpeed * deltaSec;
    this.rocketContainer.x = this.pipX;
    this.rocketContainer.y = this.pipY;

    // Bank tilt angle
    const deltaX = this.targetPipX - this.pipX;
    this.rocketContainer.rotation = Math.max(-0.22, Math.min(0.22, deltaX * 0.005));

    // Animated Rocket Jet Exhaust Plumes
    this.rocketExhaustTimer += deltaSec * 25;
    const flameH = 20 + Math.sin(this.rocketExhaustTimer) * 8;
    this.rocketExhaustGfx.clear();
    this.rocketExhaustGfx.moveTo(-10, 46);
    this.rocketExhaustGfx.lineTo(10, 46);
    this.rocketExhaustGfx.lineTo(0, 46 + flameH);
    this.rocketExhaustGfx.fill({ color: 0xFFA502 });
    this.rocketExhaustGfx.moveTo(-5, 46);
    this.rocketExhaustGfx.lineTo(5, 46);
    this.rocketExhaustGfx.lineTo(0, 46 + flameH * 0.6);
    this.rocketExhaustGfx.fill({ color: 0x70A1FF });

    if (Math.random() < 0.5) {
      this.particleSys.emitSmokePuff(this.pipX, this.pipY + 48);
    }

    if (this.isWaitingForNext) {
      this.spawnTimer -= deltaSec;
      if (this.spawnTimer <= 0 && this.currentQuestion) {
        this.isWaitingForNext = false;
        this.spawnVerticalGates(this.currentQuestion);
      }
    }

    // Move Gates & Asteroids
    for (let i = this.activeItems.length - 1; i >= 0; i--) {
      const item = this.activeItems[i];
      item.y += this.speedY * deltaSec;
      item.container.y = item.y;

      const dx = Math.abs(item.x - this.pipX);
      const dy = Math.abs(item.y - this.pipY);

      if (dx < item.width / 2 + 18 && dy < item.height / 2 + 25) {
        this.handleItemCollision(item);
        break;
      }
    }
  }
}
