import { Container, Graphics, Text, TextStyle } from 'pixi.js';
import { SoundSynth } from '../audio/SoundSynth';

export class UIHelper {
  /**
   * Creates a commercial-grade 3D pill button with drop-shadow, glossy highlight, and responsive tap bounce.
   */
  static createButton(
    label: string,
    width: number,
    height: number,
    primaryColor: number = 0x6C5CE7,
    textColor: string = '#FFFFFF',
    fontSize: number = 14,
    onClick?: () => void
  ): Container {
    const container = new Container();
    container.eventMode = 'static';
    container.cursor = 'pointer';

    const radius = Math.min(height / 2, 16);
    const shadowOffset = 4;

    const bgGfx = new Graphics();

    // 1. Bottom 3D Shadow Plate
    bgGfx.roundRect(-width / 2, -height / 2 + shadowOffset, width, height, radius);
    bgGfx.fill({ color: 0x000000, alpha: 0.35 });

    // 2. Button Bevel Base (Darker tone of primary color)
    bgGfx.roundRect(-width / 2, -height / 2 + 2, width, height, radius);
    bgGfx.fill({ color: UIHelper.adjustBrightness(primaryColor, -0.3) });

    // 3. Button Face
    bgGfx.roundRect(-width / 2, -height / 2, width, height - 2, radius);
    bgGfx.fill({ color: primaryColor });
    bgGfx.stroke({ width: 2, color: UIHelper.adjustBrightness(primaryColor, 0.25) });

    // 4. Glossy Top Highlight Arc
    bgGfx.roundRect(-width / 2 + 4, -height / 2 + 3, width - 8, height * 0.4, radius * 0.7);
    bgGfx.fill({ color: 0xFFFFFF, alpha: 0.22 });

    const text = new Text({
      text: label,
      style: new TextStyle({
        fontSize,
        fontWeight: 'bold',
        fill: textColor,
        align: 'center',
        dropShadow: {
          alpha: 0.4,
          angle: Math.PI / 2,
          blur: 2,
          color: 0x000000,
          distance: 1
        }
      })
    });
    text.anchor.set(0.5);
    text.y = -1;

    container.addChild(bgGfx);
    container.addChild(text);

    // Interactive button press animation & haptics
    container.on('pointerdown', () => {
      container.scale.set(0.94);
      container.y += 2;
      SoundSynth.triggerHaptic(15);
    });

    const resetBtn = () => {
      container.scale.set(1.0);
      container.y -= 2;
    };

    container.on('pointerup', () => {
      resetBtn();
      SoundSynth.playClick();
      if (onClick) onClick();
    });

    container.on('pointerupoutside', resetBtn);

    return container;
  }

  /**
   * Creates a commercial card panel with dark translucent glass, glowing border, and corner rivets.
   */
  static createCardPanel(
    width: number,
    height: number,
    borderColor: number = 0x6C5CE7,
    bgColor: number = 0x1A1E36,
    bgAlpha: number = 0.94,
    radius: number = 18
  ): Container {
    const container = new Container();
    const gfx = new Graphics();

    // Drop shadow
    gfx.roundRect(-width / 2 + 2, -height / 2 + 4, width, height, radius);
    gfx.fill({ color: 0x000000, alpha: 0.3 });

    // Card background
    gfx.roundRect(-width / 2, -height / 2, width, height, radius);
    gfx.fill({ color: bgColor, alpha: bgAlpha });
    gfx.stroke({ width: 2.5, color: borderColor });

    // Inner subtle glow border
    gfx.roundRect(-width / 2 + 4, -height / 2 + 4, width - 8, height - 8, radius - 4);
    gfx.stroke({ width: 1, color: 0xFFFFFF, alpha: 0.12 });

    // Corner decorative rivets
    const rx = width / 2 - 12;
    const ry = height / 2 - 12;
    const rivetColor = borderColor;
    gfx.circle(-rx, -ry, 3);
    gfx.circle(rx, -ry, 3);
    gfx.circle(-rx, ry, 3);
    gfx.circle(rx, ry, 3);
    gfx.fill({ color: rivetColor, alpha: 0.6 });

    container.addChild(gfx);
    return container;
  }

  /**
   * Helper to darken/lighten hex colors for 3D buttons & highlights.
   */
  static adjustBrightness(hex: number, percent: number): number {
    let r = (hex >> 16) & 0xFF;
    let g = (hex >> 8) & 0xFF;
    let b = hex & 0xFF;

    if (percent < 0) {
      r = Math.round(r * (1 + percent));
      g = Math.round(g * (1 + percent));
      b = Math.round(b * (1 + percent));
    } else {
      r = Math.round(r + (255 - r) * percent);
      g = Math.round(g + (255 - g) * percent);
      b = Math.round(b + (255 - b) * percent);
    }

    return (Math.max(0, Math.min(255, r)) << 16) |
           (Math.max(0, Math.min(255, g)) << 8) |
           Math.max(0, Math.min(255, b));
  }
}
