import { Container, Graphics, Text, TextStyle, Rectangle } from 'pixi.js';
import { GameScene, SceneManager } from './SceneManager';
import { StageDefinition, MathQuestion } from '../types/game';
import { MathGenerator } from '../math/MathGenerator';
import { GameState } from '../state/GameState';
import { PlushRobot } from '../entities/PlushRobot';
import { ParticleSystem } from '../engine/ParticleSystem';
import { VisualManipulative } from '../entities/VisualManipulative';
import { UIHelper } from '../engine/UIHelper';
import { SoundSynth } from '../audio/SoundSynth';
import { MusicPlayer } from '../audio/MusicPlayer';
import { SpeechHelper } from '../math/SpeechHelper';
import { WorldMapScene } from './WorldMapScene';

interface MeteorTarget {
  container: Container;
  gfx: Graphics;
  text: Text;
  answer: string | number;
  isCorrect: boolean;
  x: number;
  y: number;
  radius: number;
}

interface LaserProjectile {
  container: Container;
  gfx: Graphics;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  lifeTime: number;
}

export class BlasterScene extends Container implements GameScene {
  private stageDef: StageDefinition;
  private currentQuestion: MathQuestion | null = null;
  private questionsAnswered: number = 0;
  private correctAnswers: number = 0;
  private score: number = 0;
  private combo: number = 0;

  private screenW: number = 800;
  private screenH: number = 600;

  private bgGfx: Graphics;
  private starsGfx: Graphics;
  private gameLayer: Container;
  private meteorsLayer: Container;
  private laserBoltsLayer: Container;
  private cannonGfx: Graphics;
  private aimLineGfx: Graphics;
  private uiLayer: Container;
  private particleSys: ParticleSystem;

  private pip: PlushRobot;
  private activeMeteors: MeteorTarget[] = [];
  private activeLasers: LaserProjectile[] = [];

  private turretX: number = 400;
  private turretY: number = 540;
  private aimAngle: number = -Math.PI / 2;
  private isAiming: boolean = false;
  private starTimer: number = 0;

  private hintModal: Container | null = null;
  private isGameOver: boolean = false;

  constructor(stageDef: StageDefinition) {
    super();
    this.stageDef = stageDef;

    this.bgGfx = new Graphics();
    this.starsGfx = new Graphics();
    this.gameLayer = new Container();
    this.meteorsLayer = new Container();
    this.laserBoltsLayer = new Container();
    this.aimLineGfx = new Graphics();
    this.cannonGfx = new Graphics();
    this.particleSys = new ParticleSystem();
    this.uiLayer = new Container();

    this.addChild(this.bgGfx);
    this.addChild(this.starsGfx);
    this.addChild(this.gameLayer);
    this.gameLayer.addChild(this.meteorsLayer);
    this.gameLayer.addChild(this.laserBoltsLayer);
    this.gameLayer.addChild(this.aimLineGfx);
    this.gameLayer.addChild(this.cannonGfx);
    this.addChild(this.particleSys);
    this.addChild(this.uiLayer);

    this.pip = new PlushRobot(0.55);
    this.gameLayer.addChild(this.pip);

    this.setupTouchControls();
  }

  onEnter() {
    MusicPlayer.playTheme('arcade_rush');
    this.nextQuestion();
    this.renderUI();
  }

  resize(w: number, h: number) {
    this.screenW = w;
    this.screenH = h;
    this.hitArea = new Rectangle(0, 0, w, h);
    this.turretX = w / 2;
    this.turretY = h - 65;
    this.pip.x = this.turretX - 85;
    this.pip.y = this.turretY + 12;
    this.renderBackground();
    this.renderTurret();
    this.renderUI();
  }

  private setupTouchControls() {
    this.eventMode = 'static';
    this.hitArea = new Rectangle(0, 0, this.screenW, this.screenH);
    this.cursor = 'crosshair';

    this.bgGfx.eventMode = 'static';
    this.bgGfx.cursor = 'crosshair';

    const handlePointerDown = (e: any) => {
      if (this.isGameOver) return;
      this.isAiming = true;
      const tx = e.global.x;
      const ty = e.global.y;
      this.updateAim(tx, ty);
      // Fire flying laser projectile immediately!
      this.spawnFlyingLaser(tx, ty);
    };

    const handlePointerMove = (e: any) => {
      if (!this.isAiming || this.isGameOver) return;
      this.updateAim(e.global.x, e.global.y);
    };

    const handlePointerUp = (e: any) => {
      if (!this.isAiming || this.isGameOver) return;
      this.isAiming = false;
      this.aimLineGfx.clear();
      // Fire another laser bolt on release!
      this.spawnFlyingLaser(e.global.x, e.global.y);
    };

    this.on('pointerdown', handlePointerDown);
    this.on('pointermove', handlePointerMove);
    this.on('pointerup', handlePointerUp);
    this.on('pointerupoutside', handlePointerUp);

    this.bgGfx.on('pointerdown', handlePointerDown);
    this.bgGfx.on('pointermove', handlePointerMove);
    this.bgGfx.on('pointerup', handlePointerUp);
  }

  private updateAim(touchX: number, touchY: number) {
    const dx = touchX - this.turretX;
    const dy = touchY - this.turretY;
    this.aimAngle = Math.atan2(dy, dx);

    // Keep aim directed upward
    const minAngle = -Math.PI + 0.15;
    const maxAngle = -0.15;
    this.aimAngle = Math.max(minAngle, Math.min(maxAngle, this.aimAngle));

    this.renderAimLine(touchX, touchY);
    this.renderTurret();
  }

  private renderAimLine(targetX: number, targetY: number) {
    this.aimLineGfx.clear();
    // Glowing cyan plasma targeting beam
    this.aimLineGfx.moveTo(this.turretX, this.turretY - 20);
    this.aimLineGfx.lineTo(targetX, targetY);
    this.aimLineGfx.stroke({ width: 2, color: 0x00D2D3, alpha: 0.5 });

    // Target Crosshair at touch point
    this.aimLineGfx.circle(targetX, targetY, 16);
    this.aimLineGfx.stroke({ width: 2, color: 0x00D2D3 });
    this.aimLineGfx.circle(targetX, targetY, 3);
    this.aimLineGfx.fill({ color: 0xFFD32A });
  }

  private renderBackground() {
    const w = this.screenW;
    const h = this.screenH;

    this.bgGfx.clear();
    this.bgGfx.rect(0, 0, w, h);
    this.bgGfx.fill({ color: 0x080C21 });

    // Arcade Turret Platform Base
    this.bgGfx.roundRect(15, h - 85, w - 30, 80, 20);
    this.bgGfx.fill({ color: 0x161C3D, alpha: 0.95 });
    this.bgGfx.stroke({ width: 2, color: 0x00D2D3 });
  }

  private renderTurret() {
    this.cannonGfx.clear();
    const tx = this.turretX;
    const ty = this.turretY;

    // Glowing Power Generator Base
    this.cannonGfx.circle(tx, ty, 28);
    this.cannonGfx.fill({ color: 0x2A3464 });
    this.cannonGfx.stroke({ width: 3, color: 0x00D2D3 });

    // Plasma Cannon Barrel
    const barrelLength = 40;
    const barrelX = tx + Math.cos(this.aimAngle) * barrelLength;
    const barrelY = ty + Math.sin(this.aimAngle) * barrelLength;

    this.cannonGfx.moveTo(tx, ty);
    this.cannonGfx.lineTo(barrelX, barrelY);
    this.cannonGfx.stroke({ width: 8, color: 0x00D2D3, cap: 'round' });

    // Inner Glowing Core
    this.cannonGfx.circle(tx, ty, 12);
    this.cannonGfx.fill({ color: 0xFFD32A });
  }

  private spawnFlyingLaser(targetX: number, targetY: number) {
    const dx = targetX - this.turretX;
    const dy = targetY - this.turretY;
    let angle = Math.atan2(dy, dx);

    const minAngle = -Math.PI + 0.15;
    const maxAngle = -0.15;
    angle = Math.max(minAngle, Math.min(maxAngle, angle));
    this.aimAngle = angle;
    this.renderTurret();

    SoundSynth.playLaser();
    SoundSynth.triggerHaptic(30);
    this.pip.doHappyJump();

    const speed = 1050; // Fast, snappy, clearly visible flying laser projectile
    const vx = Math.cos(angle) * speed;
    const vy = Math.sin(angle) * speed;

    const startX = this.turretX + Math.cos(angle) * 35;
    const startY = this.turretY + Math.sin(angle) * 35;

    const container = new Container();
    const gfx = new Graphics();

    // 1. Outer Cyan Plasma Glow Capsule
    gfx.roundRect(-4, -14, 8, 28, 4);
    gfx.fill({ color: 0x00D2D3 });

    // 2. Inner Brilliant White Laser Core
    gfx.roundRect(-2, -10, 4, 20, 2);
    gfx.fill({ color: 0xFFFFFF });

    // 3. Trailing Star Sparkles
    gfx.circle(0, 16, 2.5);
    gfx.fill({ color: 0xFFD32A });

    container.addChild(gfx);
    container.x = startX;
    container.y = startY;
    container.rotation = angle + Math.PI / 2;

    this.laserBoltsLayer.addChild(container);

    this.activeLasers.push({
      container,
      gfx,
      x: startX,
      y: startY,
      vx,
      vy,
      radius: 14,
      lifeTime: 1.5
    });
  }

  private nextQuestion() {
    if (this.questionsAnswered >= this.stageDef.targetCount) {
      this.triggerVictory();
      return;
    }

    this.currentQuestion = MathGenerator.generateQuestion(this.stageDef.id);
    this.spawnMeteors(this.currentQuestion);
    this.renderUI();

    if (this.currentQuestion.speechPrompt) {
      SpeechHelper.speak(this.currentQuestion.speechPrompt);
    }
  }

  private spawnMeteors(q: MathQuestion) {
    this.meteorsLayer.removeChildren();
    this.activeMeteors = [];

    const options = [...q.options];
    if (!options.map(String).includes(String(q.correctAnswer))) {
      options.unshift(q.correctAnswer);
    }
    const count = options.length;
    const padding = 35;
    const availableW = this.screenW - padding * 2;
    const stepX = availableW / count;
    const radius = Math.min(36, stepX / 2 - 8);

    options.forEach((opt, idx) => {
      const isCorrect = String(opt) === String(q.correctAnswer);
      const container = new Container();
      container.eventMode = 'static';
      container.cursor = 'pointer';

      const targetX = padding + idx * stepX + stepX / 2;
      const targetY = 160 + (idx % 2 === 0 ? 0 : 35);

      const gfx = new Graphics();

      // 2.5D Crystalline Math Meteorite
      gfx.circle(0, 0, radius);
      gfx.fill({ color: 0x2C3A47 });
      gfx.stroke({ width: 3.5, color: 0x00D2D3 });

      // Facet shading
      gfx.circle(0, 0, radius - 6);
      gfx.fill({ color: 0x1E272E });

      const text = new Text({
        text: String(opt),
        style: new TextStyle({
          fontSize: 18,
          fontWeight: 'bold',
          fill: '#FFFFFF',
          align: 'center'
        })
      });
      text.anchor.set(0.5);

      container.addChild(gfx);
      container.addChild(text);
      container.x = targetX;
      container.y = targetY;

      // Direct tap support: aiming and firing flying laser projectile towards this meteor
      container.on('pointerdown', (e) => {
        e.stopPropagation();
        this.updateAim(targetX, targetY);
        this.spawnFlyingLaser(targetX, targetY);
      });

      this.meteorsLayer.addChild(container);
      this.activeMeteors.push({
        container,
        gfx,
        text,
        answer: opt,
        isCorrect,
        x: targetX,
        y: targetY,
        radius
      });
    });
  }

  private handleMeteorHit(meteor: MeteorTarget) {
    if (!this.currentQuestion) return;

    if (meteor.isCorrect) {
      this.correctAnswers++;
      this.questionsAnswered++;
      this.combo++;
      const comboBonus = this.combo > 1 ? this.combo * 25 : 0;
      this.score += 100 + comboBonus;

      GameState.getInstance().recordAnswer(this.currentQuestion, true);
      SoundSynth.playCorrect();
      SoundSynth.playStar();
      SoundSynth.triggerHaptic(40);

      this.particleSys.emitStarBurst(meteor.x, meteor.y, 35);
      this.pip.doHappyJump();

      this.meteorsLayer.removeChildren();
      this.activeMeteors = [];
      this.clearLasers();
      this.nextQuestion();
    } else {
      this.questionsAnswered++;
      this.combo = 0;
      GameState.getInstance().recordAnswer(this.currentQuestion, false);
      SoundSynth.playWrong();
      SoundSynth.triggerHaptic(60);

      this.pip.doErrorShake();
      this.meteorsLayer.removeChildren();
      this.activeMeteors = [];
      this.clearLasers();
      this.showHintModal();
    }
    this.renderUI();
  }

  private clearLasers() {
    for (const laser of this.activeLasers) {
      this.laserBoltsLayer.removeChild(laser.container);
      laser.container.destroy();
    }
    this.activeLasers = [];
  }

  private showHintModal() {
    if (!this.currentQuestion) return;
    const modal = new Container();
    const mw = Math.min(500, this.screenW - 40);
    const mh = 320;
    const mx = (this.screenW - mw) / 2;
    const my = (this.screenH - mh) / 2;

    const bg = new Graphics();
    bg.roundRect(mx, my, mw, mh, 18);
    bg.fill({ color: 0x1E272E, alpha: 0.98 });
    bg.stroke({ width: 3, color: 0x00D2D3 });
    modal.addChild(bg);

    const title = new Text({
      text: '💡 Starlight Math Helper',
      style: new TextStyle({ fontSize: 18, fontWeight: 'bold', fill: '#FFD32A' })
    });
    title.x = mx + 20;
    title.y = my + 15;
    modal.addChild(title);

    if (this.currentQuestion.manipulative) {
      const manip = new VisualManipulative(this.currentQuestion.manipulative, mw - 40, 140);
      manip.x = mx + 20;
      manip.y = my + 45;
      modal.addChild(manip);
    }

    const hintText = new Text({
      text: this.currentQuestion.hint,
      style: new TextStyle({ fontSize: 13, fill: '#FFFFFF', wordWrap: true, wordWrapWidth: mw - 40 })
    });
    hintText.x = mx + 20;
    hintText.y = my + 195;
    modal.addChild(hintText);

    const gotItBtn = UIHelper.createButton('Got it! 🚀', 160, 40, 0x00D2D3, '#0A0D22', 14, () => {
      this.uiLayer.removeChild(modal);
      modal.destroy();
      this.hintModal = null;
      this.nextQuestion();
    });
    gotItBtn.x = mx + mw / 2;
    gotItBtn.y = my + mh - 35;
    modal.addChild(gotItBtn);

    this.hintModal = modal;
    this.uiLayer.addChild(modal);
  }

  private triggerVictory() {
    this.isGameOver = true;
    this.meteorsLayer.removeChildren();
    this.clearLasers();

    const state = GameState.getInstance();
    const result = state.completeStage(
      this.stageDef.id,
      this.correctAnswers,
      this.stageDef.targetCount,
      this.score
    );

    SoundSynth.playLevelClear();
    ParticleSystem.triggerConfetti();

    const modal = new Container();
    const mw = Math.min(460, this.screenW - 40);
    const mh = 360;
    const mx = (this.screenW - mw) / 2;
    const my = (this.screenH - mh) / 2;

    const bg = new Graphics();
    bg.roundRect(mx, my, mw, mh, 20);
    bg.fill({ color: 0x1E272E, alpha: 0.98 });
    bg.stroke({ width: 3, color: 0x00D2D3 });
    modal.addChild(bg);

    const title = new Text({
      text: '🎉 MISSION ACCOMPLISHED!',
      style: new TextStyle({ fontSize: 20, fontWeight: 'bold', fill: '#00D2D3', align: 'center' })
    });
    title.anchor.set(0.5);
    title.x = mx + mw / 2;
    title.y = my + 35;
    modal.addChild(title);

    const starsStr = '⭐'.repeat(result.starsEarned) + '☆'.repeat(3 - result.starsEarned);
    const starsText = new Text({
      text: starsStr,
      style: new TextStyle({ fontSize: 36, fill: '#FFD32A', align: 'center' })
    });
    starsText.anchor.set(0.5);
    starsText.x = mx + mw / 2;
    starsText.y = my + 85;
    modal.addChild(starsText);

    const scoreInfo = new Text({
      text: `Score: ${this.score}\nAccuracy: ${this.correctAnswers} / ${this.stageDef.targetCount} (${Math.round((this.correctAnswers / this.stageDef.targetCount) * 100)}%)\nStar Coins Earned: +${result.starsEarned * 3} 🪙`,
      style: new TextStyle({ fontSize: 15, fill: '#FFFFFF', align: 'center', lineHeight: 24 })
    });
    scoreInfo.anchor.set(0.5);
    scoreInfo.x = mx + mw / 2;
    scoreInfo.y = my + 175;
    modal.addChild(scoreInfo);

    const continueBtn = UIHelper.createButton('Back to Galaxy Map 🌌', 200, 44, 0x00D2D3, '#0A0D22', 14, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    continueBtn.x = mx + mw / 2;
    continueBtn.y = my + mh - 45;
    modal.addChild(continueBtn);

    this.uiLayer.addChild(modal);
  }

  private renderUI() {
    this.uiLayer.removeChildren();
    if (this.hintModal) {
      this.uiLayer.addChild(this.hintModal);
      return;
    }

    const w = this.screenW;

    const headerBg = new Graphics();
    headerBg.roundRect(10, 8, w - 20, 44, 12);
    headerBg.fill({ color: 0x1E272E, alpha: 0.9 });
    headerBg.stroke({ width: 1.5, color: 0x576574 });
    this.uiLayer.addChild(headerBg);

    const backBtn = UIHelper.createButton('◀ Exit', 70, 30, 0xFF4757, '#FFFFFF', 12, () => {
      SceneManager.getInstance().changeScene(new WorldMapScene());
    });
    backBtn.x = 55;
    backBtn.y = 30;
    this.uiLayer.addChild(backBtn);

    const comboStr = this.combo > 1 ? ` 🔥 COMBO x${this.combo}!` : '';
    const progressText = new Text({
      text: `Question ${this.questionsAnswered + 1}/${this.stageDef.targetCount} | Tap anywhere to fire lasers!${comboStr}`,
      style: new TextStyle({ fontSize: 13, fontWeight: 'bold', fill: '#00D2D3' })
    });
    progressText.x = 105;
    progressText.y = 22;
    this.uiLayer.addChild(progressText);

    if (this.currentQuestion) {
      const qBg = new Graphics();
      qBg.roundRect(10, 56, w - 20, 48, 12);
      qBg.fill({ color: 0x2C3A47, alpha: 0.95 });
      qBg.stroke({ width: 2, color: 0x00D2D3 });
      this.uiLayer.addChild(qBg);

      const qText = new Text({
        text: this.currentQuestion.prompt,
        style: new TextStyle({ fontSize: 16, fontWeight: 'bold', fill: '#FFFFFF' })
      });
      qText.x = 25;
      qText.y = 66;
      this.uiLayer.addChild(qText);

      const ttsBtn = UIHelper.createButton('🔊 Read', 64, 30, 0x00D2D3, '#0A0D22', 11, () => {
        if (this.currentQuestion?.speechPrompt) {
          SpeechHelper.speak(this.currentQuestion.speechPrompt);
        }
      });
      ttsBtn.x = w - 50;
      ttsBtn.y = 80;
      this.uiLayer.addChild(ttsBtn);
    }
  }

  update(deltaSec: number) {
    this.pip.update(deltaSec);
    this.particleSys.update(deltaSec);

    this.starTimer += deltaSec;
    this.starsGfx.clear();
    for (let i = 0; i < 35; i++) {
      const sx = (i * 127) % this.screenW;
      const sy = (i * 211) % this.screenH;
      this.starsGfx.circle(sx, sy, 1.2);
      this.starsGfx.fill({ color: 0xFFFFFF, alpha: 0.25 + Math.sin(this.starTimer * 3 + i) * 0.2 });
    }

    if (this.isGameOver) return;

    for (const meteor of this.activeMeteors) {
      meteor.container.y = meteor.y + Math.sin(this.starTimer * 2 + meteor.x) * 0.4;
    }

    // Update Flying Laser Projectiles and Real-Time Collisions
    for (let i = this.activeLasers.length - 1; i >= 0; i--) {
      const laser = this.activeLasers[i];
      laser.x += laser.vx * deltaSec;
      laser.y += laser.vy * deltaSec;
      laser.lifeTime -= deltaSec;

      laser.container.x = laser.x;
      laser.container.y = laser.y;

      // Trailing spark particle
      if (Math.random() < 0.4) {
        this.particleSys.emitSmokePuff(laser.x, laser.y);
      }

      // Check collision with math meteors
      let hit = false;
      for (const meteor of this.activeMeteors) {
        const dist = Math.hypot(laser.x - meteor.x, laser.y - meteor.container.y);
        if (dist < meteor.radius + laser.radius) {
          // Collision confirmed!
          hit = true;
          this.laserBoltsLayer.removeChild(laser.container);
          laser.container.destroy();
          this.activeLasers.splice(i, 1);
          this.handleMeteorHit(meteor);
          break;
        }
      }

      if (!hit && (laser.lifeTime <= 0 || laser.y < -30 || laser.x < -30 || laser.x > this.screenW + 30)) {
        this.laserBoltsLayer.removeChild(laser.container);
        laser.container.destroy();
        this.activeLasers.splice(i, 1);
      }
    }
  }
}
