import { UserProgress } from '../types/game';

const STORAGE_KEY = 'cosmobot_math_blaster_v1';

// In-memory fallback for environments where localStorage is not available
const inMemoryStore: Record<string, string> = {};

function getItem(key: string): string | null {
  if (typeof localStorage !== 'undefined') {
    try {
      return localStorage.getItem(key);
    } catch {
      // fallback
    }
  }
  return inMemoryStore[key] || null;
}

function setItem(key: string, value: string) {
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(key, value);
      return;
    } catch {
      // fallback
    }
  }
  inMemoryStore[key] = value;
}

function clearStore() {
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.clear();
      return;
    } catch {
      // fallback
    }
  }
  for (const k in inMemoryStore) {
    delete inMemoryStore[k];
  }
}

export const DEFAULT_PROGRESS: UserProgress = {
  playerName: 'Cadet Explorer',
  starCoins: 10,
  totalScore: 0,
  levelXP: 0,
  unlockedStages: {
    w1_s1: true
  },
  stageHighScores: {},
  stageStars: {},
  stageAttempts: {},
  standardsMastery: {},
  streakDays: 1,
  lastPlayedDate: new Date().toISOString().split('T')[0],
  equippedAccessories: {
    hat: 'hat_none',
    scarf: 'scarf_none',
    back: 'back_none',
    companion: 'comp_none',
    skin: 'skin_mint_coral'
  },
  inventory: ['hat_none', 'scarf_none', 'back_none', 'comp_none', 'skin_mint_coral'],
  badges: [],
  settings: {
    sfxVolume: 0.8,
    musicVolume: 0.4,
    voiceEnabled: true,
    voiceSpeed: 0.9,
    hapticsEnabled: true,
    highContrast: false,
    dyslexicFont: false,
    reducedMotion: false
  }
};

export class Storage {
  static load(): UserProgress {
    try {
      const data = getItem(STORAGE_KEY);
      if (data) {
        const parsed = JSON.parse(data);
        return {
          ...DEFAULT_PROGRESS,
          ...parsed,
          settings: { ...DEFAULT_PROGRESS.settings, ...(parsed.settings || {}) },
          equippedAccessories: { ...DEFAULT_PROGRESS.equippedAccessories, ...(parsed.equippedAccessories || {}) },
          unlockedStages: { ...DEFAULT_PROGRESS.unlockedStages, ...(parsed.unlockedStages || {}) }
        };
      }
    } catch {
      // ignore
    }
    return JSON.parse(JSON.stringify(DEFAULT_PROGRESS));
  }

  static save(progress: UserProgress) {
    try {
      setItem(STORAGE_KEY, JSON.stringify(progress));
    } catch {
      // ignore
    }
  }

  static clear() {
    clearStore();
  }

  static exportSaveJson(): string {
    return getItem(STORAGE_KEY) || JSON.stringify(DEFAULT_PROGRESS);
  }

  static importSaveJson(jsonStr: string): boolean {
    try {
      const parsed = JSON.parse(jsonStr);
      if (parsed && typeof parsed.starCoins === 'number') {
        setItem(STORAGE_KEY, jsonStr);
        return true;
      }
    } catch {
      // invalid
    }
    return false;
  }
}
