import { Container, Graphics, Text, TextStyle, Rectangle } from 'pixi.js';
import { GameScene, SceneManager } from './SceneManager';
import { PlushRobot } from '../entities/PlushRobot';
import { WorldMapScene } from './WorldMapScene';
import { DressUpScene } from './DressUpScene';
import { ParentDashboardScene } from './ParentDashboardScene';
import { ParticleSystem } from '../engine/ParticleSystem';
import { UIHelper } from '../engine/UIHelper';
import { SoundSynth } from '../audio/SoundSynth';
import { MusicPlayer } from '../audio/MusicPlayer';
import { GameState } from '../state/GameState';
import { WORLDS } from '../math/CurriculumData';
import { WorldDefinition, WorldId } from '../types/game';

interface WorldCardDisplay {
  worldDef: WorldDefinition;
  worldIndex: number;
  container: Container;
  bgGfx: Graphics;
  planetContainer: Container;
  planetGfx: Graphics;
  planetSecondaryGfx: Graphics;
  planetGlowGfx: Graphics;
  actionBtn: Container;
  isUnlocked: boolean;
  worldStars: number;
  completedNodes: number;
}

export class BootScene extends Container implements GameScene {
  private screenW: number = 800;
  private screenH: number = 600;

  // Scene Graph Layers
  private bgLayer: Container;
  private bgGfx: Graphics;
  private nebulaGfx: Graphics;
  private starsGfx: Graphics;

  private headerContainer: Container;
  private heroContainer: Container;
  private pedestalGfx: Graphics;
  private pip: PlushRobot;

  private carouselContainer: Container;
  private cardsContainer: Container;
  private paginationContainer: Container;
  private leftArrowBtn: Container | null = null;
  private rightArrowBtn: Container | null = null;

  private bottomNavContainer: Container;
  private particleSys: ParticleSystem;

  // Carousel & Scrolling State
  private cardDisplays: WorldCardDisplay[] = [];
  private selectedWorldIndex: number = 0;
  private currentScrollX: number = 0;
  private targetScrollX: number = 0;
  private carouselCenterX: number = 400;
  private cardWidth: number = 280;
  private cardHeight: number = 340;
  private cardGap: number = 20;

  // Drag Interaction State
  private isDraggingCards: boolean = false;
  private dragStartX: number = 0;
  private scrollStartX: number = 0;
  private dragDistance: number = 0;

  // Animation Timers
  private animTimer: number = 0;
  private starTimer: number = 0;

  constructor() {
    super();

    // 1. Background Layers
    this.bgLayer = new Container();
    this.bgGfx = new Graphics();
    this.nebulaGfx = new Graphics();
    this.starsGfx = new Graphics();
    this.bgLayer.addChild(this.bgGfx);
    this.bgLayer.addChild(this.nebulaGfx);
    this.bgLayer.addChild(this.starsGfx);

    // 2. Character Hero Container
    this.heroContainer = new Container();
    this.pedestalGfx = new Graphics();
    this.pip = new PlushRobot(0.85);
    this.heroContainer.addChild(this.pedestalGfx);
    this.heroContainer.addChild(this.pip);

    // Pip interactive tap
    this.pip.eventMode = 'static';
    this.pip.cursor = 'pointer';
    this.pip.on('pointerup', () => {
      SoundSynth.playPlushSqueak();
      this.pip.doHappyJump();
      ParticleSystem.triggerConfetti();
    });

    // 3. World Cards Carousel
    this.carouselContainer = new Container();
    this.cardsContainer = new Container();
    this.paginationContainer = new Container();
    this.carouselContainer.addChild(this.cardsContainer);
    this.carouselContainer.addChild(this.paginationContainer);

    // 4. Header & Bottom Navigation
    this.headerContainer = new Container();
    this.bottomNavContainer = new Container();
    this.particleSys = new ParticleSystem();

    // Scene Graph assembly
    this.addChild(this.bgLayer);
    this.addChild(this.heroContainer);
    this.addChild(this.carouselContainer);
    this.addChild(this.headerContainer);
    this.addChild(this.bottomNavContainer);
    this.addChild(this.particleSys);

    this.setupCarouselDragging();
    this.initDefaultSelection();
  }

  onEnter(): void {
    MusicPlayer.playTheme('sanctuary');
    this.pip.updateAppearance();
    this.renderAll();
  }

  onExit(): void {
    // Teardown timers / listeners if necessary
  }

  resize(w: number, h: number): void {
    this.screenW = w;
    this.screenH = h;
    this.hitArea = new Rectangle(0, 0, w, h);
    this.renderAll();
  }

  /**
   * Determine initial world selection based on player progression.
   */
  private initDefaultSelection(): void {
    const state = GameState.getInstance();
    let candidateIdx = 0;
    for (let i = 0; i < WORLDS.length; i++) {
      const wid = WORLDS[i].id;
      if (state.isWorldUnlocked(wid)) {
        candidateIdx = i;
        if (state.getWorldCompletedNodeCount(wid) < 12) {
          break;
        }
      }
    }
    this.selectedWorldIndex = candidateIdx;
    this.targetScrollX = -this.selectedWorldIndex * (this.cardWidth + this.cardGap);
    this.currentScrollX = this.targetScrollX;
  }

  /**
   * Select and scroll to a specific world card.
   */
  public selectWorld(index: number): void {
    const clamped = Math.max(0, Math.min(WORLDS.length - 1, index));
    if (clamped !== this.selectedWorldIndex) {
      SoundSynth.playClick();
    }
    this.selectedWorldIndex = clamped;
    const cardStep = this.cardWidth + this.cardGap;
    this.targetScrollX = -this.selectedWorldIndex * cardStep;
    this.renderPaginationDots();
  }

  /**
   * Main rendering coordinator for all scene elements.
   */
  private renderAll(): void {
    this.renderBackground();
    this.renderHeader();
    this.renderWorldCards();
    this.renderHeroAndPedestal();
    this.renderBottomNavigation();
    this.renderPaginationDots();
  }

  /**
   * Deep space cosmic background with colorful nebulas.
   */
  private renderBackground(): void {
    const w = this.screenW;
    const h = this.screenH;

    this.bgGfx.clear();
    this.bgGfx.rect(0, 0, w, h);
    this.bgGfx.fill({ color: 0x0A0D22 });

    this.nebulaGfx.clear();
    // Top-left purple nebula
    this.nebulaGfx.circle(w * 0.2, h * 0.25, Math.min(w, h) * 0.35);
    this.nebulaGfx.fill({ color: 0x6C5CE7, alpha: 0.16 });

    // Center-right pink/magenta nebula
    this.nebulaGfx.circle(w * 0.8, h * 0.45, Math.min(w, h) * 0.4);
    this.nebulaGfx.fill({ color: 0xFF6B81, alpha: 0.14 });

    // Bottom cyan nebula
    this.nebulaGfx.circle(w * 0.5, h * 0.85, Math.min(w, h) * 0.38);
    this.nebulaGfx.fill({ color: 0x00D2D3, alpha: 0.12 });
  }

  /**
   * Header banner with Game Title, Subtitle, Sound Toggle, and Stats.
   */
  private renderHeader(): void {
    this.headerContainer.removeChildren();
    const w = this.screenW;
    const isNarrow = w < 600;
    const state = GameState.getInstance();
    const totalStars = state.getTotalStars();
    const starCoins = state.progress.starCoins;

    // Header Background Glass Bar
    const headerH = isNarrow ? 68 : 58;
    const headerBg = new Graphics();
    headerBg.rect(0, 0, w, headerH);
    headerBg.fill({ color: 0x0D122B, alpha: 0.94 });
    headerBg.stroke({ width: 1.5, color: 0x2A3562 });
    this.headerContainer.addChild(headerBg);

    // 1. Sound Toggle Button (Left)
    const isSoundOn = state.isSoundEnabled();
    const soundBtnW = isNarrow ? 40 : 100;
    const soundBtnText = isNarrow ? (isSoundOn ? '🔊' : '🔇') : (isSoundOn ? '🔊 Sound' : '🔇 Muted');
    const soundBtn = UIHelper.createButton(
      soundBtnText,
      soundBtnW,
      34,
      isSoundOn ? 0x2E386B : 0x3D3D5A,
      isSoundOn ? '#00D2D3' : '#A4B0BE',
      isNarrow ? 14 : 11,
      () => {
        state.toggleSound();
        this.renderHeader();
      }
    );
    soundBtn.x = 10 + soundBtnW / 2;
    soundBtn.y = headerH / 2;
    this.headerContainer.addChild(soundBtn);

    // 2. Stats Pill: Stars & Star Coins (Right)
    const statsPillW = isNarrow ? 120 : 160;
    const statsPill = new Container();
    const statsGfx = new Graphics();
    statsGfx.roundRect(-statsPillW / 2, -17, statsPillW, 34, 17);
    statsGfx.fill({ color: 0x1A2244, alpha: 0.9 });
    statsGfx.stroke({ width: 1.5, color: 0xFFD32A });

    const statsText = new Text({
      text: `⭐ ${totalStars}   🪙 ${starCoins}`,
      style: new TextStyle({
        fontSize: isNarrow ? 11 : 12,
        fontWeight: 'bold',
        fill: '#FFD32A',
        align: 'center'
      })
    });
    statsText.anchor.set(0.5);
    statsPill.addChild(statsGfx);
    statsPill.addChild(statsText);
    statsPill.x = w - 10 - statsPillW / 2;
    statsPill.y = headerH / 2;
    this.headerContainer.addChild(statsPill);

    // 3. Center Branding / Title Banner
    const maxTitleW = w - soundBtnW - statsPillW - 40;
    const titleContainer = new Container();

    const titleText = new Text({
      text: 'COSMOBOT',
      style: new TextStyle({
        fontFamily: 'system-ui, -apple-system, sans-serif',
        fontSize: Math.min(22, Math.max(14, maxTitleW * 0.12)),
        fontWeight: '900',
        fill: '#FFD32A',
        stroke: { color: '#1E272E', width: 3 },
        dropShadow: {
          alpha: 0.5,
          angle: Math.PI / 2,
          blur: 4,
          color: 0x6C5CE7,
          distance: 2
        },
        align: 'center'
      })
    });
    titleText.anchor.set(0.5);
    titleText.y = isNarrow ? -7 : -6;
    titleContainer.addChild(titleText);

    const subText = new Text({
      text: '★ PPS Math Blaster ★',
      style: new TextStyle({
        fontSize: Math.min(10, Math.max(8, maxTitleW * 0.055)),
        fontWeight: 'bold',
        fill: '#00D2D3',
        align: 'center'
      })
    });
    subText.anchor.set(0.5);
    subText.y = isNarrow ? 10 : 10;
    titleContainer.addChild(subText);

    titleContainer.x = w / 2;
    titleContainer.y = headerH / 2;
    this.headerContainer.addChild(titleContainer);
  }

  /**
   * Render Character Hero preview with pedestal.
   */
  private renderHeroAndPedestal(): void {
    const w = this.screenW;
    const h = this.screenH;
    const isDesktopLandscape = w >= 850 && w > h;

    this.pedestalGfx.clear();

    if (isDesktopLandscape) {
      // Desktop: Pip on the left side
      const heroX = w * 0.18;
      const heroY = h * 0.52;

      this.heroContainer.x = heroX;
      this.heroContainer.y = heroY;
      this.pip.scale.set(0.95);

      // Futuristic Glowing Energy Pedestal
      this.pedestalGfx.ellipse(0, 48, 70, 24);
      this.pedestalGfx.fill({ color: 0x000000, alpha: 0.4 });

      this.pedestalGfx.ellipse(0, 42, 60, 20);
      this.pedestalGfx.fill({ color: 0x1E2448, alpha: 0.9 });
      this.pedestalGfx.stroke({ width: 2.5, color: 0x6C5CE7 });

      this.pedestalGfx.ellipse(0, 42, 44, 14);
      this.pedestalGfx.fill({ color: 0x00D2D3, alpha: 0.35 });
      this.pedestalGfx.stroke({ width: 1.5, color: 0x00D2D3 });
    } else {
      // Mobile / Tablet Portrait: Compact Pip above carousel
      const heroX = w / 2;
      const heroY = Math.max(92, Math.min(140, h * 0.17));
      const heroScale = Math.min(0.75, Math.max(0.48, h * 0.00085));

      this.heroContainer.x = heroX;
      this.heroContainer.y = heroY;
      this.pip.scale.set(heroScale);

      // Mini Pedestal
      const pedW = 54 * (heroScale / 0.75);
      const pedH = 16 * (heroScale / 0.75);
      const pedY = 38 * (heroScale / 0.75);

      this.pedestalGfx.ellipse(0, pedY + 4, pedW + 6, pedH + 2);
      this.pedestalGfx.fill({ color: 0x000000, alpha: 0.35 });

      this.pedestalGfx.ellipse(0, pedY, pedW, pedH);
      this.pedestalGfx.fill({ color: 0x1E2448, alpha: 0.9 });
      this.pedestalGfx.stroke({ width: 2, color: 0x6C5CE7 });

      this.pedestalGfx.ellipse(0, pedY, pedW * 0.7, pedH * 0.7);
      this.pedestalGfx.fill({ color: 0x00D2D3, alpha: 0.3 });
    }
  }

  /**
   * Render the 5 World/Planet Selection Cards inside carousel.
   */
  private renderWorldCards(): void {
    this.cardsContainer.removeChildren();
    this.cardDisplays = [];

    const w = this.screenW;
    const h = this.screenH;
    const state = GameState.getInstance();
    const isDesktopLandscape = w >= 850 && w > h;

    // Card Dimensions Calculation
    if (isDesktopLandscape) {
      this.cardWidth = Math.min(300, w * 0.32);
      this.cardHeight = Math.min(420, h * 0.65);
      this.carouselCenterX = w * 0.62;
      this.carouselContainer.y = h * 0.52;
    } else {
      this.cardWidth = Math.min(310, w - 46);
      this.cardHeight = Math.min(370, Math.max(280, h * 0.5));
      this.carouselCenterX = w / 2;
      this.carouselContainer.y = Math.min(h * 0.57, h - this.cardHeight / 2 - 76);
    }
    this.cardGap = 20;

    // Build each world card
    for (let i = 0; i < WORLDS.length; i++) {
      const worldDef = WORLDS[i];
      const isUnlocked = state.isWorldUnlocked(worldDef.id);
      const worldStars = state.getWorldStars(worldDef.id);
      const completedNodes = state.getWorldCompletedNodeCount(worldDef.id);

      const cardItem = this.createWorldCard(worldDef, i, isUnlocked, worldStars, completedNodes);
      this.cardsContainer.addChild(cardItem.container);
      this.cardDisplays.push(cardItem);
    }

    // Left and Right Arrow Navigation Buttons
    this.renderCarouselArrows();

    // Position cards
    this.updateCardsPosition();
  }

  /**
   * Create a single rich World Card container.
   */
  private createWorldCard(
    worldDef: WorldDefinition,
    worldIndex: number,
    isUnlocked: boolean,
    worldStars: number,
    completedNodes: number
  ): WorldCardDisplay {
    const cardW = this.cardWidth;
    const cardH = this.cardHeight;
    const cardContainer = new Container();
    cardContainer.eventMode = 'static';
    cardContainer.cursor = 'pointer';

    // 1. Drop Shadow
    const shadowGfx = new Graphics();
    shadowGfx.roundRect(-cardW / 2 + 4, -cardH / 2 + 6, cardW, cardH, 20);
    shadowGfx.fill({ color: 0x000000, alpha: 0.4 });
    cardContainer.addChild(shadowGfx);

    // 2. Card Background & Border
    const bgGfx = new Graphics();
    bgGfx.roundRect(-cardW / 2, -cardH / 2, cardW, cardH, 20);

    const themeColor = parseInt(worldDef.accentColor.replace('#', '0x'), 16) || 0x6C5CE7;

    if (isUnlocked) {
      bgGfx.fill({ color: 0x141838, alpha: 0.95 });
      bgGfx.stroke({ width: 2.5, color: themeColor });
    } else {
      bgGfx.fill({ color: 0x121526, alpha: 0.88 });
      bgGfx.stroke({ width: 1.5, color: 0x384158 });
    }
    cardContainer.addChild(bgGfx);

    // 3. Planet / Celestial Sphere Graphic (Top)
    const planetContainer = new Container();
    const planetGlowGfx = new Graphics();
    const planetGfx = new Graphics();
    const planetSecondaryGfx = new Graphics();

    planetContainer.addChild(planetGlowGfx);
    planetContainer.addChild(planetGfx);
    planetContainer.addChild(planetSecondaryGfx);

    const planetCenterY = -cardH / 2 + (cardH > 340 ? 56 : 46);
    planetContainer.y = planetCenterY;

    this.drawThemePlanetGraphic(worldIndex, isUnlocked, themeColor, planetGlowGfx, planetGfx, planetSecondaryGfx);
    cardContainer.addChild(planetContainer);

    // 4. World Number & Name Title
    const titleY = planetCenterY + (cardH > 340 ? 46 : 38);
    const titleText = new Text({
      text: `${worldDef.icon} Planet ${worldIndex + 1}: ${worldDef.name}`,
      style: new TextStyle({
        fontSize: Math.min(14, Math.max(11, cardW * 0.048)),
        fontWeight: 'bold',
        fill: isUnlocked ? '#FFFFFF' : '#8395A7',
        align: 'center',
        wordWrap: true,
        wordWrapWidth: cardW - 24
      })
    });
    titleText.anchor.set(0.5);
    titleText.y = titleY;
    cardContainer.addChild(titleText);

    // 5. Math Curriculum Focus Badge
    const currY = titleY + 24;
    const currBadgeW = cardW - 32;
    const currBg = new Graphics();
    currBg.roundRect(-currBadgeW / 2, -11, currBadgeW, 22, 11);
    currBg.fill({ color: isUnlocked ? 0x0E142E : 0x1A1F30, alpha: 0.9 });
    currBg.stroke({ width: 1, color: isUnlocked ? themeColor : 0x3D465C, alpha: 0.7 });

    const curriculumSummary = this.getCurriculumSummary(worldIndex);
    const currText = new Text({
      text: curriculumSummary,
      style: new TextStyle({
        fontSize: 10,
        fontWeight: 'bold',
        fill: isUnlocked ? '#00D2D3' : '#636E72',
        align: 'center',
        wordWrap: true,
        wordWrapWidth: currBadgeW - 10
      })
    });
    currText.anchor.set(0.5);

    const currContainer = new Container();
    currContainer.addChild(currBg);
    currContainer.addChild(currText);
    currContainer.y = currY;
    cardContainer.addChild(currContainer);

    // 6. Progress & Stars Info
    const progY = currY + 28;
    const starsStr = isUnlocked ? `⭐ ${worldStars} / 36 Stars` : '🔒 0 / 36 Stars';
    const nodesStr = isUnlocked ? `🎯 ${completedNodes} / 12 Levels Complete` : '🔒 Levels Locked';

    const statsInfoText = new Text({
      text: `${starsStr}   •   ${nodesStr}`,
      style: new TextStyle({
        fontSize: 11,
        fontWeight: 'bold',
        fill: isUnlocked ? '#FFD32A' : '#636E72',
        align: 'center'
      })
    });
    statsInfoText.anchor.set(0.5);
    statsInfoText.y = progY;
    cardContainer.addChild(statsInfoText);

    // 7. Visual Progress Bar
    const barY = progY + 16;
    const barW = cardW - 44;
    const barH = 6;
    const barGfx = new Graphics();
    barGfx.roundRect(-barW / 2, -barH / 2, barW, barH, 3);
    barGfx.fill({ color: 0x0E1328 });
    barGfx.stroke({ width: 1, color: 0x2A355E });

    if (isUnlocked && completedNodes > 0) {
      const fillW = Math.max(6, (barW - 2) * (completedNodes / 12));
      barGfx.roundRect(-barW / 2 + 1, -barH / 2 + 1, fillW, barH - 2, 2);
      barGfx.fill({ color: themeColor });
    }
    barGfx.y = barY;
    cardContainer.addChild(barGfx);

    // 8. Action Button / Locked Banner
    const btnY = cardH / 2 - (cardH > 340 ? 36 : 28);
    const btnW = cardW - 36;
    const btnH = cardH > 340 ? 44 : 38;

    let actionBtn: Container;
    if (isUnlocked) {
      actionBtn = UIHelper.createButton(
        '🚀 ENTER WORLD',
        btnW,
        btnH,
        themeColor,
        '#FFFFFF',
        13,
        () => {
          this.handleEnterWorld(worldDef.id);
        }
      );
    } else {
      const prevWorldNum = worldIndex;
      actionBtn = UIHelper.createButton(
        `🔒 LOCKED (Complete World ${prevWorldNum})`,
        btnW,
        btnH,
        0x242B3E,
        '#8395A7',
        11,
        () => {
          this.handleLockedCardTap(cardContainer, worldIndex);
        }
      );
    }
    actionBtn.y = btnY;
    cardContainer.addChild(actionBtn);

    // Card Container Tap Handler (clicking anywhere on card selects or enters)
    cardContainer.on('pointerup', () => {
      if (this.dragDistance < 10) {
        if (this.selectedWorldIndex === worldIndex) {
          if (isUnlocked) {
            this.handleEnterWorld(worldDef.id);
          } else {
            this.handleLockedCardTap(cardContainer, worldIndex);
          }
        } else {
          this.selectWorld(worldIndex);
        }
      }
    });

    return {
      worldDef,
      worldIndex,
      container: cardContainer,
      bgGfx,
      planetContainer,
      planetGfx,
      planetSecondaryGfx,
      planetGlowGfx,
      actionBtn,
      isUnlocked,
      worldStars,
      completedNodes
    };
  }

  /**
   * Summary text describing the math curriculum of each world.
   */
  private getCurriculumSummary(worldIndex: number): string {
    switch (worldIndex) {
      case 0:
        return '➕ 2nd Grade: Addition & Subtraction Facts';
      case 1:
        return '🪙 Coins, Money & Clock Time (Nearest 5m)';
      case 2:
        return '🔷 2D/3D Geometry, Fractions & Arrays';
      case 3:
        return '⚡ 3rd Grade: Times Tables & Division';
      case 4:
      default:
        return '🌌 Advanced Pre-Algebra & Logic Puzzles';
    }
  }

  /**
   * Draw procedural vector planet graphics matching the curriculum world theme.
   */
  private drawThemePlanetGraphic(
    worldIndex: number,
    isUnlocked: boolean,
    themeColor: number,
    glowGfx: Graphics,
    planetGfx: Graphics,
    secondaryGfx: Graphics
  ): void {
    glowGfx.clear();
    planetGfx.clear();
    secondaryGfx.clear();

    const r = 30;

    if (!isUnlocked) {
      // Locked Planet (Dark Muted Slate with Padlock)
      glowGfx.circle(0, 0, r + 6);
      glowGfx.fill({ color: 0x1E2438, alpha: 0.3 });

      planetGfx.circle(0, 0, r);
      planetGfx.fill({ color: 0x1E2438 });
      planetGfx.stroke({ width: 2, color: 0x3D465C });

      // Padlock Body
      secondaryGfx.roundRect(-10, -3, 20, 16, 3);
      secondaryGfx.fill({ color: 0xD63031 });
      secondaryGfx.stroke({ width: 1.5, color: 0xFF7675 });

      // Padlock Shackle
      secondaryGfx.arc(0, -3, 6, Math.PI, 0);
      secondaryGfx.stroke({ width: 2.5, color: 0xDFE6E9 });

      // Keyhole
      secondaryGfx.circle(0, 4, 2.5);
      secondaryGfx.fill({ color: 0xFFFFFF });
      return;
    }

    switch (worldIndex) {
      case 0: {
        // World 1: Cosmic Nebula Ringed Violet Gas Giant
        glowGfx.circle(0, 0, r + 10);
        glowGfx.fill({ color: themeColor, alpha: 0.28 });

        planetGfx.circle(0, 0, r);
        planetGfx.fill({ color: 0x5F27CD });
        planetGfx.stroke({ width: 2, color: 0xA29BFE });

        // Surface bands
        planetGfx.ellipse(0, -7, r * 0.8, 5);
        planetGfx.fill({ color: 0xFF6B81, alpha: 0.7 });
        planetGfx.ellipse(0, 9, r * 0.75, 4);
        planetGfx.fill({ color: 0x6C5CE7, alpha: 0.6 });

        // Sparkling golden ring
        secondaryGfx.ellipse(0, 0, r * 1.55, 8);
        secondaryGfx.stroke({ width: 3, color: 0xFDCB6E, alpha: 0.9 });
        break;
      }
      case 1: {
        // World 2: Pittsburgh Astro-City (Gold & Steel Cityscape)
        glowGfx.circle(0, 0, r + 10);
        glowGfx.fill({ color: 0xF1C40F, alpha: 0.25 });

        planetGfx.circle(0, 0, r);
        planetGfx.fill({ color: 0x2C3E50 });
        planetGfx.stroke({ width: 2, color: 0xF1C40F });

        // Golden Bridge Cables Archway
        planetGfx.arc(0, 6, r * 0.7, Math.PI, 0);
        planetGfx.stroke({ width: 2.5, color: 0xF1C40F });
        planetGfx.moveTo(-r * 0.7, 6);
        planetGfx.lineTo(r * 0.7, 6);
        planetGfx.stroke({ width: 1.5, color: 0xF39C12 });

        // Orbiting shiny copper coin
        secondaryGfx.circle(r + 5, -8, 7);
        secondaryGfx.fill({ color: 0xE67E22 });
        secondaryGfx.stroke({ width: 1.5, color: 0xF1C40F });
        break;
      }
      case 2: {
        // World 3: Crystalline Asteroids (Cyan Geometric Crystal)
        glowGfx.circle(0, 0, r + 10);
        glowGfx.fill({ color: 0x00D2D3, alpha: 0.28 });

        // Faceted Hexagon Crystal Planet
        planetGfx.moveTo(0, -r);
        planetGfx.lineTo(r * 0.85, -r * 0.5);
        planetGfx.lineTo(r * 0.85, r * 0.5);
        planetGfx.lineTo(0, r);
        planetGfx.lineTo(-r * 0.85, r * 0.5);
        planetGfx.lineTo(-r * 0.85, -r * 0.5);
        planetGfx.closePath();
        planetGfx.fill({ color: 0x0984E3 });
        planetGfx.stroke({ width: 2, color: 0x74B9FF });

        // Inner Crystal Facets
        planetGfx.moveTo(0, -r);
        planetGfx.lineTo(0, r);
        planetGfx.moveTo(-r * 0.85, -r * 0.5);
        planetGfx.lineTo(r * 0.85, 0.5);
        planetGfx.stroke({ width: 1.5, color: 0x55EFC4, alpha: 0.7 });

        // Orbiting floating crystal prism
        secondaryGfx.moveTo(-r - 4, 10);
        secondaryGfx.lineTo(-r + 4, 4);
        secondaryGfx.lineTo(-r + 10, 12);
        secondaryGfx.lineTo(-r + 2, 18);
        secondaryGfx.closePath();
        secondaryGfx.fill({ color: 0x00CEC9 });
        secondaryGfx.stroke({ width: 1, color: 0xFFFFFF });
        break;
      }
      case 3: {
        // World 4: Starlight Solar Forge (Molten Radiant Sun)
        glowGfx.circle(0, 0, r + 12);
        glowGfx.fill({ color: 0xFF7675, alpha: 0.35 });

        planetGfx.circle(0, 0, r);
        planetGfx.fill({ color: 0xE17055 });
        planetGfx.stroke({ width: 2, color: 0xFFA502 });

        // Solar Flare Loops
        secondaryGfx.arc(-14, -14, 8, 0, Math.PI * 1.5);
        secondaryGfx.stroke({ width: 2.5, color: 0xFFD32A, alpha: 0.85 });

        secondaryGfx.arc(16, 12, 7, Math.PI * 0.5, Math.PI * 2);
        secondaryGfx.stroke({ width: 2.5, color: 0xFF7675, alpha: 0.85 });
        break;
      }
      case 4:
      default: {
        // World 5: Deep Space Mystery (Dark Vortex with Emerald Accretion Ring)
        glowGfx.circle(0, 0, r + 12);
        glowGfx.fill({ color: 0x0BE881, alpha: 0.35 });

        planetGfx.circle(0, 0, r);
        planetGfx.fill({ color: 0x050517 });
        planetGfx.stroke({ width: 2.5, color: 0x0BE881 });

        // Emerald Accretion Ring Swirl
        secondaryGfx.ellipse(0, 0, r * 1.5, 9);
        secondaryGfx.stroke({ width: 2.5, color: 0x00B894, alpha: 0.9 });

        // Quantum Logic Glyph Core
        secondaryGfx.circle(0, 0, 4);
        secondaryGfx.fill({ color: 0x0BE881 });
        break;
      }
    }
  }

  /**
   * Action handler when player taps to enter an unlocked world.
   */
  private handleEnterWorld(worldId: WorldId): void {
    SoundSynth.unlock();
    SoundSynth.playLevelClear();
    ParticleSystem.triggerConfetti();
    SceneManager.getInstance().changeScene(new WorldMapScene(worldId));
  }

  /**
   * Feedback when player taps a locked world card.
   */
  private handleLockedCardTap(cardContainer: Container, _worldIndex: number): void {
    SoundSynth.playWrong();
    SoundSynth.triggerHaptic(40);
    this.pip.doErrorShake();

    const origX = cardContainer.x;
    let shakeCount = 0;
    const interval = setInterval(() => {
      shakeCount++;
      cardContainer.x = origX + (shakeCount % 2 === 0 ? 6 : -6);
      if (shakeCount > 6) {
        clearInterval(interval);
        cardContainer.x = origX;
      }
    }, 30);
  }

  /**
   * Left and Right navigation arrows for carousel.
   */
  private renderCarouselArrows(): void {
    if (this.leftArrowBtn) this.carouselContainer.removeChild(this.leftArrowBtn);
    if (this.rightArrowBtn) this.carouselContainer.removeChild(this.rightArrowBtn);

    const w = this.screenW;
    const isDesktopLandscape = w >= 850 && w > this.screenH;
    const arrowOffsetX = isDesktopLandscape ? this.cardWidth / 2 + 36 : Math.min(this.cardWidth / 2 + 28, w / 2 - 18);

    this.leftArrowBtn = UIHelper.createButton('◀', 36, 36, 0x2A3562, '#FFFFFF', 14, () => {
      this.selectWorld(this.selectedWorldIndex - 1);
    });
    this.leftArrowBtn.x = this.carouselCenterX - arrowOffsetX;
    this.leftArrowBtn.y = 0;

    this.rightArrowBtn = UIHelper.createButton('▶', 36, 36, 0x2A3562, '#FFFFFF', 14, () => {
      this.selectWorld(this.selectedWorldIndex + 1);
    });
    this.rightArrowBtn.x = this.carouselCenterX + arrowOffsetX;
    this.rightArrowBtn.y = 0;

    this.carouselContainer.addChild(this.leftArrowBtn);
    this.carouselContainer.addChild(this.rightArrowBtn);
  }

  /**
   * 5 Pagination Dots Indicator below carousel.
   */
  private renderPaginationDots(): void {
    this.paginationContainer.removeChildren();
    const dotsCount = WORLDS.length;
    const dotSpacing = 16;
    const startX = this.carouselCenterX - ((dotsCount - 1) * dotSpacing) / 2;
    const dotY = this.cardHeight / 2 + 18;

    for (let i = 0; i < dotsCount; i++) {
      const dot = new Graphics();
      const isSelected = i === this.selectedWorldIndex;
      const r = isSelected ? 5.5 : 3.5;
      dot.circle(0, 0, r);
      dot.fill({ color: isSelected ? 0xFFD32A : 0x576574, alpha: isSelected ? 1 : 0.6 });
      if (isSelected) {
        dot.stroke({ width: 1.5, color: 0xFFFFFF });
      }
      dot.x = startX + i * dotSpacing;
      dot.y = dotY;
      dot.eventMode = 'static';
      dot.cursor = 'pointer';
      dot.on('pointerup', () => {
        this.selectWorld(i);
      });
      this.paginationContainer.addChild(dot);
    }
  }

  /**
   * Bottom bar with Quick Navigation buttons (Pip's Closet & Parent Dashboard).
   */
  private renderBottomNavigation(): void {
    this.bottomNavContainer.removeChildren();
    const w = this.screenW;
    const h = this.screenH;
    const isDesktopLandscape = w >= 850 && w > h;

    const navH = 50;
    const btnW = isDesktopLandscape ? 170 : Math.min(155, (w - 30) / 2);
    const btnH = 38;
    const navY = h - navH / 2 - 4;

    const closetBtn = UIHelper.createButton(
      "🧸 Pip's Closet",
      btnW,
      btnH,
      0x5F27CD,
      '#FFFFFF',
      12,
      () => {
        SceneManager.getInstance().changeScene(new DressUpScene());
      }
    );
    closetBtn.x = w / 2 - btnW / 2 - 8;
    closetBtn.y = navY;
    this.bottomNavContainer.addChild(closetBtn);

    const reportBtn = UIHelper.createButton(
      '📊 PPS Report',
      btnW,
      btnH,
      0x10AC84,
      '#FFFFFF',
      12,
      () => {
        SceneManager.getInstance().changeScene(new ParentDashboardScene());
      }
    );
    reportBtn.x = w / 2 + btnW / 2 + 8;
    reportBtn.y = navY;
    this.bottomNavContainer.addChild(reportBtn);
  }

  /**
   * Setup smooth pointer touch drag and swiping on cards carousel.
   */
  private setupCarouselDragging(): void {
    this.eventMode = 'static';

    this.on('pointerdown', (e) => {
      const cy = this.carouselContainer.y;
      if (e.global.y >= cy - this.cardHeight / 2 && e.global.y <= cy + this.cardHeight / 2) {
        this.isDraggingCards = true;
        this.dragStartX = e.global.x;
        this.scrollStartX = this.currentScrollX;
        this.dragDistance = 0;
      }
    });

    this.on('pointermove', (e) => {
      if (!this.isDraggingCards) return;
      const dx = e.global.x - this.dragStartX;
      this.dragDistance += Math.abs(dx);
      this.currentScrollX = this.scrollStartX + dx;
      this.updateCardsPosition();
    });

    const finishDrag = (_e: any) => {
      if (!this.isDraggingCards) return;
      this.isDraggingCards = false;

      const delta = this.currentScrollX - this.scrollStartX;
      const cardStep = this.cardWidth + this.cardGap;

      if (delta < -35 && this.selectedWorldIndex < WORLDS.length - 1) {
        this.selectWorld(this.selectedWorldIndex + 1);
      } else if (delta > 35 && this.selectedWorldIndex > 0) {
        this.selectWorld(this.selectedWorldIndex - 1);
      } else {
        const nearestIndex = Math.round(-this.currentScrollX / cardStep);
        this.selectWorld(nearestIndex);
      }
    };

    this.on('pointerup', finishDrag);
    this.on('pointerupoutside', finishDrag);
  }

  /**
   * Update visual positions, scaling, and alpha for all cards in the carousel.
   */
  private updateCardsPosition(): void {
    const cardStep = this.cardWidth + this.cardGap;

    for (let i = 0; i < this.cardDisplays.length; i++) {
      const card = this.cardDisplays[i];
      const baseCardX = i * cardStep;
      const renderedX = this.carouselCenterX + this.currentScrollX + baseCardX;
      card.container.x = renderedX;
      card.container.y = 0;

      // Distance from center determines scale and opacity
      const distFromCenter = Math.abs(renderedX - this.carouselCenterX);
      const normalizedDist = Math.min(1, distFromCenter / (cardStep * 1.2));
      const scale = 1.0 - normalizedDist * 0.08;
      const alpha = 1.0 - normalizedDist * 0.25;

      card.container.scale.set(scale);
      card.container.alpha = alpha;
    }
  }

  /**
   * Main Scene Ticker Update Loop.
   */
  public update(deltaSec: number): void {
    const dt = Math.max(0, deltaSec);
    this.animTimer += dt;
    this.starTimer += dt;

    // 1. Update Pip Plush Character
    this.pip.update(dt);
    this.particleSys.update(dt);

    // 2. Smooth Carousel Interpolation
    if (!this.isDraggingCards) {
      this.currentScrollX += (this.targetScrollX - this.currentScrollX) * Math.min(1, dt * 14);
      this.updateCardsPosition();
    }

    // 3. Planet Subtle Ambient Animations on Cards
    for (const card of this.cardDisplays) {
      if (card.planetSecondaryGfx && card.isUnlocked) {
        card.planetSecondaryGfx.rotation = Math.sin(this.animTimer * 1.2 + card.worldIndex) * 0.15;
      }
      if (card.planetGlowGfx && card.isUnlocked) {
        const pulse = 0.25 + 0.1 * Math.sin(this.animTimer * 2.5 + card.worldIndex);
        card.planetGlowGfx.alpha = pulse;
      }
    }

    // 4. Dynamic Twinkling Stars & Constellations
    this.starsGfx.clear();
    const w = this.screenW;
    const h = this.screenH;

    for (let i = 0; i < 35; i++) {
      const sx = (i * 137 + 19) % w;
      const sy = (i * 223 + 41) % h;
      const alpha = 0.25 + Math.sin(this.starTimer * 2.2 + i) * 0.25;

      if (i % 5 === 0) {
        // 4-Point Diamond Shimmer Star
        const r = 3.5;
        this.starsGfx.moveTo(sx, sy - r);
        this.starsGfx.lineTo(sx + r * 0.35, sy);
        this.starsGfx.lineTo(sx + r, sy);
        this.starsGfx.lineTo(sx + r * 0.35, sy);
        this.starsGfx.lineTo(sx, sy + r);
        this.starsGfx.lineTo(sx - r * 0.35, sy);
        this.starsGfx.lineTo(sx - r, sy);
        this.starsGfx.lineTo(sx - r * 0.35, sy);
        this.starsGfx.closePath();
        this.starsGfx.fill({ color: 0xFFD32A, alpha });
      } else {
        this.starsGfx.circle(sx, sy, (i % 2) + 1);
        this.starsGfx.fill({ color: 0xFFFFFF, alpha });
      }
    }
  }
}
