export class SpeechHelper {
  private static synth: SpeechSynthesis | null = typeof window !== 'undefined' && 'speechSynthesis' in window ? window.speechSynthesis : null;
  private static enabled: boolean = true;
  private static speed: number = 0.9; // Friendly, clear pace for 2nd graders

  static setEnabled(enabled: boolean) {
    this.enabled = enabled;
    if (!enabled && this.synth) {
      this.synth.cancel();
    }
  }

  static isEnabled(): boolean {
    return this.enabled;
  }

  static setSpeed(speed: number) {
    this.speed = Math.max(0.5, Math.min(1.5, speed));
  }

  static speak(text: string, onEnd?: () => void) {
    if (!this.enabled || !this.synth) {
      if (onEnd) onEnd();
      return;
    }

    try {
      this.synth.cancel(); // Stop any pending speech
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.rate = this.speed;
      utterance.pitch = 1.2; // Cheerful, friendly robot voice tone
      
      // Select best friendly English voice if available
      const voices = this.synth.getVoices();
      const preferredVoice = voices.find(v => (v.name.includes('Samantha') || v.name.includes('Google US English') || v.name.includes('Natural') || v.lang.startsWith('en')));
      if (preferredVoice) {
        utterance.voice = preferredVoice;
      }

      if (onEnd) {
        utterance.onend = () => onEnd();
        utterance.onerror = () => onEnd();
      }

      this.synth.speak(utterance);
    } catch {
      if (onEnd) onEnd();
    }
  }

  static stop() {
    if (this.synth) {
      this.synth.cancel();
    }
  }
}
