import { Container, Graphics, Text, TextStyle } from 'pixi.js';
import { VisualManipulativeData } from '../types/game';

export class VisualManipulative extends Container {
  private manipData: VisualManipulativeData;
  private maxW: number;
  private gfx: Graphics;

  constructor(data: VisualManipulativeData, maxWidth: number = 400, _maxHeight: number = 200) {
    super();
    this.manipData = data;
    this.maxW = maxWidth;
    this.gfx = new Graphics();
    this.addChild(this.gfx);
    this.renderManipulative();
  }

  renderManipulative() {
    this.gfx.clear();
    this.removeChildren();
    this.addChild(this.gfx);

    const d = this.manipData.data || {};
    switch (this.manipData.type) {
      case 'ten_frame':
        this.renderTenFrame(d.count || 0, d.secondaryCount || 0);
        break;
      case 'base_ten':
        this.renderBase10(d.value || 0);
        break;
      case 'coins':
        this.renderCoins(d.coins || []);
        break;
      case 'clock':
        this.renderClock(d.hours || 12, d.minutes || 0);
        break;
      case 'fractions':
        this.renderFractions(d.numerator || 1, d.denominator || 4);
        break;
      case 'array':
        this.renderArray(d.rows || 2, d.cols || 4);
        break;
      case 'shape':
        this.renderShapes(d.shapeName || 'triangle');
        break;
      case 'balance_scale':
        this.renderBalanceScale();
        break;
    }
  }

  private renderTenFrame(filled: number, added: number) {
    const cellW = 32;
    const cellH = 32;
    const cols = 5;
    const rows = 2;
    const totalW = cols * cellW;
    const totalH = rows * cellH;
    const startX = (this.maxW - totalW) / 2;
    const startY = 15;

    this.gfx.roundRect(startX - 8, startY - 8, totalW + 16, totalH + 16, 12);
    this.gfx.fill({ color: 0x2A2E45 });
    this.gfx.stroke({ width: 3, color: 0x6C5CE7 });

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const x = startX + c * cellW;
        const y = startY + r * cellH;
        const idx = r * cols + c;

        this.gfx.roundRect(x + 2, y + 2, cellW - 4, cellH - 4, 6);
        this.gfx.fill({ color: 0x1E2235 });
        this.gfx.stroke({ width: 1.5, color: 0x485460 });

        if (idx < filled) {
          this.gfx.circle(x + cellW / 2, y + cellH / 2, 11);
          this.gfx.fill({ color: 0xFF4757 });
          this.gfx.stroke({ width: 2, color: 0xD63031 });
          this.gfx.circle(x + cellW / 2 - 3, y + cellH / 2 - 3, 3);
          this.gfx.fill({ color: 0xFFFFFF, alpha: 0.85 });
        } else if (idx < filled + added) {
          this.gfx.circle(x + cellW / 2, y + cellH / 2, 11);
          this.gfx.fill({ color: 0x1E90FF });
          this.gfx.stroke({ width: 2, color: 0x0984E3 });
          this.gfx.circle(x + cellW / 2 - 3, y + cellH / 2 - 3, 3);
          this.gfx.fill({ color: 0xFFFFFF, alpha: 0.85 });
        }
      }
    }
  }

  private renderBase10(val: number) {
    const hundreds = Math.floor(val / 100);
    const tens = Math.floor((val % 100) / 10);
    const ones = val % 10;

    let currX = 25;
    const startY = 15;

    for (let h = 0; h < Math.min(3, hundreds); h++) {
      this.gfx.roundRect(currX, startY, 52, 52, 6);
      this.gfx.fill({ color: 0x2ED573 });
      this.gfx.stroke({ width: 2, color: 0x26AF5F });
      for (let g = 10; g < 50; g += 10) {
        this.gfx.moveTo(currX + g, startY);
        this.gfx.lineTo(currX + g, startY + 52);
        this.gfx.moveTo(currX, startY + g);
        this.gfx.lineTo(currX + 52, startY + g);
      }
      this.gfx.stroke({ width: 1, color: 0x1E824C, alpha: 0.6 });
      currX += 60;
    }

    for (let t = 0; t < Math.min(8, tens); t++) {
      this.gfx.roundRect(currX, startY, 14, 52, 4);
      this.gfx.fill({ color: 0xFFA502 });
      this.gfx.stroke({ width: 1.5, color: 0xE67E22 });
      for (let g = 5; g < 50; g += 5.2) {
        this.gfx.moveTo(currX, startY + g);
        this.gfx.lineTo(currX + 14, startY + g);
      }
      this.gfx.stroke({ width: 1, color: 0xD35400, alpha: 0.6 });
      currX += 20;
    }

    let unitX = currX + 5;
    let unitY = startY;
    for (let o = 0; o < Math.min(10, ones); o++) {
      this.gfx.roundRect(unitX, unitY, 12, 12, 3);
      this.gfx.fill({ color: 0xFF4757 });
      this.gfx.stroke({ width: 1.5, color: 0xC0392B });
      unitY += 15;
      if (unitY > startY + 45) {
        unitY = startY;
        unitX += 16;
      }
    }
  }

  private renderCoins(coins: number[]) {
    let currX = 25;
    const startY = 35;

    coins.forEach((c) => {
      let r = 16;
      let col = 0xD4AF37;
      let label = `${c}¢`;

      if (c === 1) {
        r = 13;
        col = 0xCD7F32;
      } else if (c === 5) {
        r = 16;
        col = 0xB0BEC5;
      } else if (c === 10) {
        r = 11;
        col = 0xCFD8DC;
      } else if (c === 25) {
        r = 18;
        col = 0x90A4AE;
      } else if (c === 100) {
        this.gfx.roundRect(currX, startY - 14, 46, 28, 4);
        this.gfx.fill({ color: 0x85BB65 });
        this.gfx.stroke({ width: 2, color: 0x2E7D32 });

        const t = new Text({
          text: '$1',
          style: new TextStyle({ fontSize: 13, fontWeight: 'bold', fill: '#1B5E20' })
        });
        t.anchor.set(0.5);
        t.x = currX + 23;
        t.y = startY;
        this.addChild(t);

        currX += 54;
        return;
      }

      this.gfx.circle(currX + r, startY, r);
      this.gfx.fill({ color: col });
      this.gfx.stroke({ width: 2, color: 0x37474F });

      this.gfx.circle(currX + r, startY, r - 3);
      this.gfx.stroke({ width: 1, color: 0xFFFFFF, alpha: 0.5 });

      const t = new Text({
        text: label,
        style: new TextStyle({ fontSize: 11, fontWeight: 'bold', fill: '#263238' })
      });
      t.anchor.set(0.5);
      t.x = currX + r;
      t.y = startY;
      this.addChild(t);

      currX += r * 2 + 10;
    });
  }

  private renderClock(hrs: number, mins: number) {
    const cx = this.maxW / 2;
    const cy = 60;
    const r = 45;

    this.gfx.circle(cx, cy, r + 6);
    this.gfx.fill({ color: 0xF5CD79 });
    this.gfx.stroke({ width: 2.5, color: 0xE15F41 });

    this.gfx.circle(cx, cy, r);
    this.gfx.fill({ color: 0xFDFBF7 });
    this.gfx.stroke({ width: 2, color: 0x2F3542 });

    for (let i = 0; i < 12; i++) {
      const angle = (i * Math.PI) / 6;
      const x1 = cx + Math.sin(angle) * (r - 4);
      const y1 = cy - Math.cos(angle) * (r - 4);
      const x2 = cx + Math.sin(angle) * (r - 8);
      const y2 = cy - Math.cos(angle) * (r - 8);
      this.gfx.moveTo(x1, y1);
      this.gfx.lineTo(x2, y2);
      this.gfx.stroke({ width: i % 3 === 0 ? 2.5 : 1.5, color: 0x2F3542 });
    }

    const hrAngle = ((hrs % 12) + mins / 60) * (Math.PI / 6);
    const hrX = cx + Math.sin(hrAngle) * 24;
    const hrY = cy - Math.cos(hrAngle) * 24;
    this.gfx.moveTo(cx, cy);
    this.gfx.lineTo(hrX, hrY);
    this.gfx.stroke({ width: 4, color: 0xFF4757, cap: 'round' });

    const minAngle = (mins / 60) * (Math.PI * 2);
    const minX = cx + Math.sin(minAngle) * 35;
    const minY = cy - Math.cos(minAngle) * 35;
    this.gfx.moveTo(cx, cy);
    this.gfx.lineTo(minX, minY);
    this.gfx.stroke({ width: 2.5, color: 0x1E90FF, cap: 'round' });

    this.gfx.circle(cx, cy, 3.5);
    this.gfx.fill({ color: 0xF1C40F });
    this.gfx.stroke({ width: 1.5, color: 0x2F3542 });
  }

  private renderFractions(num: number, den: number) {
    const cx = this.maxW / 2;
    const cy = 60;
    const r = 45;

    this.gfx.circle(cx, cy, r);
    this.gfx.fill({ color: 0xF5CD79 });
    this.gfx.stroke({ width: 3, color: 0xE67E22 });

    this.gfx.circle(cx, cy, r - 5);
    this.gfx.fill({ color: 0xF8C291 });

    const step = (Math.PI * 2) / den;
    for (let i = 0; i < den; i++) {
      const a1 = i * step - Math.PI / 2;
      const a2 = (i + 1) * step - Math.PI / 2;

      if (i < num) {
        this.gfx.moveTo(cx, cy);
        this.gfx.arc(cx, cy, r - 5, a1, a2);
        this.gfx.lineTo(cx, cy);
        this.gfx.fill({ color: 0xFF6B6B });

        const midA = a1 + step / 2;
        const px = cx + Math.cos(midA) * 22;
        const py = cy + Math.sin(midA) * 22;
        this.gfx.circle(px, py, 4);
        this.gfx.fill({ color: 0x962D3E });
      }

      this.gfx.moveTo(cx, cy);
      this.gfx.lineTo(cx + Math.cos(a1) * r, cy + Math.sin(a1) * r);
      this.gfx.stroke({ width: 2, color: 0x2C3A47 });
    }
  }

  private renderArray(rows: number, cols: number) {
    const dotR = 8;
    const spacingX = 26;
    const spacingY = 24;
    const startX = (this.maxW - cols * spacingX) / 2 + dotR;
    const startY = 20;

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const x = startX + c * spacingX;
        const y = startY + r * spacingY;
        this.gfx.circle(x, y, dotR);
        this.gfx.fill({ color: 0xFFD32A });
        this.gfx.stroke({ width: 1.8, color: 0xF39C12 });
        this.gfx.circle(x - 2, y - 2, 2.5);
        this.gfx.fill({ color: 0xFFFFFF, alpha: 0.8 });
      }
    }
  }

  private renderShapes(name: string) {
    const cx = this.maxW / 2;
    const cy = 60;

    this.gfx.circle(cx, cy, 46);
    this.gfx.fill({ color: 0x1E272E });
    this.gfx.stroke({ width: 2, color: 0x6C5CE7 });

    if (name === 'triangle') {
      this.gfx.moveTo(cx, cy - 30);
      this.gfx.lineTo(cx - 30, cy + 24);
      this.gfx.lineTo(cx + 30, cy + 24);
      this.gfx.fill({ color: 0x2ED573 });
      this.gfx.stroke({ width: 3, color: 0x26AF5F });
    } else if (name === 'pentagon') {
      const r = 28;
      for (let i = 0; i < 5; i++) {
        const a = (i * Math.PI * 2) / 5 - Math.PI / 2;
        const x = cx + Math.cos(a) * r;
        const y = cy + Math.sin(a) * r;
        if (i === 0) this.gfx.moveTo(x, y);
        else this.gfx.lineTo(x, y);
      }
      this.gfx.fill({ color: 0x70A1FF });
      this.gfx.stroke({ width: 3, color: 0x1E90FF });
    } else if (name === 'hexagon') {
      const r = 30;
      for (let i = 0; i < 6; i++) {
        const a = (i * Math.PI * 2) / 6;
        const x = cx + Math.cos(a) * r;
        const y = cy + Math.sin(a) * r;
        if (i === 0) this.gfx.moveTo(x, y);
        else this.gfx.lineTo(x, y);
      }
      this.gfx.fill({ color: 0xFFA502 });
      this.gfx.stroke({ width: 3, color: 0xE67E22 });
    } else {
      this.gfx.roundRect(cx - 24, cy - 24, 48, 48, 6);
      this.gfx.fill({ color: 0xFF6B81 });
      this.gfx.stroke({ width: 3, color: 0xEE5253 });
    }
  }

  private renderBalanceScale() {
    const cx = this.maxW / 2;
    const cy = 65;

    this.gfx.moveTo(cx, cy);
    this.gfx.lineTo(cx - 18, cy + 32);
    this.gfx.lineTo(cx + 18, cy + 32);
    this.gfx.fill({ color: 0x747D8C });
    this.gfx.stroke({ width: 2, color: 0x2F3542 });

    this.gfx.roundRect(cx - 75, cy - 4, 150, 8, 3);
    this.gfx.fill({ color: 0xF1C40F });
    this.gfx.stroke({ width: 2, color: 0xD68910 });

    this.gfx.roundRect(cx - 75, cy + 12, 38, 10, 4);
    this.gfx.roundRect(cx + 37, cy + 12, 38, 10, 4);
    this.gfx.fill({ color: 0x70A1FF });
    this.gfx.stroke({ width: 1.5, color: 0x1E90FF });

    this.gfx.moveTo(cx - 56, cy);
    this.gfx.lineTo(cx - 56, cy + 12);
    this.gfx.moveTo(cx + 56, cy);
    this.gfx.lineTo(cx + 56, cy + 12);
    this.gfx.stroke({ width: 1.5, color: 0x2F3542 });
  }
}
