import { Container, Graphics } from 'pixi.js';
import { GameState } from '../state/GameState';
import { SoundSynth } from '../audio/SoundSynth';

export interface PlushRobotConfig {
  scale?: number;
  interactive?: boolean;
  showShadow?: boolean;
  animateIdle?: boolean;
}

export interface SkinPalette {
  mainPlush: number;
  bellyCorduroy: number;
  earAccent: number;
  armRibbon: number;
  stitchColor: number;
  antennaBall: number;
  heartLed: number;
}

export class PlushRobot extends Container {
  // Container & Graphics hierarchy
  private shadowGfx: Graphics;
  private characterContainer: Container;
  private backLayerGfx: Graphics;
  private leftLegGfx: Graphics;
  private rightLegGfx: Graphics;
  private leftArmGfx: Graphics;
  private rightArmGfx: Graphics;
  private bodyGfx: Graphics;
  private chestGfx: Graphics;
  private headGfx: Graphics;
  private earsGfx: Graphics;
  private antennaGfx: Graphics;
  private eyesGfx: Graphics;
  private mouthGfx: Graphics;
  private accessoriesContainer: Container;
  private frontAccGfx: Graphics;
  private companionGfx: Graphics;

  // Animation & state flags
  private eyeState: 'normal' | 'happy' | 'blink' | 'surprised' = 'normal';
  private blinkTimer: number = 0;
  private animTimer: number = 0;
  private isBouncing: boolean = true;
  private bounceSpeed: number = 3.2;
  private scaleFactor: number = 1;
  private squashFactor: number = 1;
  private facing: 'left' | 'right' | 'front' = 'front';
  private interactiveMode: boolean = true;
  private showShadow: boolean = true;
  private animateIdle: boolean = true;

  // Path movement animation state
  private isWalking: boolean = false;
  private isHopping: boolean = false;
  private startX: number = 0;
  private startY: number = 0;
  private targetX: number = 0;
  private targetY: number = 0;
  private moveDuration: number = 0.6;
  private moveElapsed: number = 0;
  private onMoveComplete?: () => void;

  constructor(arg1?: GameState | number | PlushRobotConfig, arg2?: PlushRobotConfig) {
    super();

    let scale = 1;
    let interactive = true;
    let showShadow = true;
    let animateIdle = true;

    if (typeof arg1 === 'number') {
      scale = arg1;
      if (arg2) {
        if (arg2.scale !== undefined) scale = arg2.scale;
        if (arg2.interactive !== undefined) interactive = arg2.interactive;
        if (arg2.showShadow !== undefined) showShadow = arg2.showShadow;
        if (arg2.animateIdle !== undefined) animateIdle = arg2.animateIdle;
      }
    } else if (arg1 instanceof GameState) {
      if (arg2) {
        if (arg2.scale !== undefined) scale = arg2.scale;
        if (arg2.interactive !== undefined) interactive = arg2.interactive;
        if (arg2.showShadow !== undefined) showShadow = arg2.showShadow;
        if (arg2.animateIdle !== undefined) animateIdle = arg2.animateIdle;
      }
    } else if (arg1 && typeof arg1 === 'object') {
      if (arg1.scale !== undefined) scale = arg1.scale;
      if (arg1.interactive !== undefined) interactive = arg1.interactive;
      if (arg1.showShadow !== undefined) showShadow = arg1.showShadow;
      if (arg1.animateIdle !== undefined) animateIdle = arg1.animateIdle;
    }

    this.scaleFactor = scale;
    this.interactiveMode = interactive;
    this.showShadow = showShadow;
    this.animateIdle = animateIdle;

    // Build scene graph hierarchy
    this.shadowGfx = new Graphics();
    this.characterContainer = new Container();

    this.backLayerGfx = new Graphics();
    this.leftLegGfx = new Graphics();
    this.rightLegGfx = new Graphics();
    this.leftArmGfx = new Graphics();
    this.rightArmGfx = new Graphics();
    this.bodyGfx = new Graphics();
    this.chestGfx = new Graphics();
    this.headGfx = new Graphics();
    this.earsGfx = new Graphics();
    this.antennaGfx = new Graphics();
    this.eyesGfx = new Graphics();
    this.mouthGfx = new Graphics();
    this.accessoriesContainer = new Container();
    this.frontAccGfx = new Graphics();
    this.companionGfx = new Graphics();

    this.addChild(this.shadowGfx);
    this.addChild(this.characterContainer);

    this.characterContainer.addChild(this.backLayerGfx);
    this.characterContainer.addChild(this.leftLegGfx);
    this.characterContainer.addChild(this.rightLegGfx);
    this.characterContainer.addChild(this.leftArmGfx);
    this.characterContainer.addChild(this.rightArmGfx);
    this.characterContainer.addChild(this.bodyGfx);
    this.characterContainer.addChild(this.chestGfx);
    this.characterContainer.addChild(this.headGfx);
    this.characterContainer.addChild(this.earsGfx);
    this.characterContainer.addChild(this.antennaGfx);
    this.characterContainer.addChild(this.eyesGfx);
    this.characterContainer.addChild(this.mouthGfx);
    this.characterContainer.addChild(this.accessoriesContainer);
    this.accessoriesContainer.addChild(this.frontAccGfx);
    this.characterContainer.addChild(this.companionGfx);

    if (this.interactiveMode) {
      this.eventMode = 'static';
      this.cursor = 'pointer';
      this.on('pointertap', () => {
        this.doHappyJump();
        SoundSynth.playPlushSqueak();
        SoundSynth.triggerHaptic(25);
      });
    } else {
      this.eventMode = 'none';
    }

    this.renderRobot();
  }

  public getSkinColor(): SkinPalette {
    const state = GameState.getInstance();
    const skinId = state?.progress?.equippedAccessories?.skin || 'skin_mint_coral';

    switch (skinId) {
      case 'skin_lavender_pink':
        return {
          mainPlush: 0x9B89B3,
          bellyCorduroy: 0xFDE2E4,
          earAccent: 0xFFB5A7,
          armRibbon: 0x8675A9,
          stitchColor: 0x5C4D7D,
          antennaBall: 0xFFCAD4,
          heartLed: 0xFF4757
        };
      case 'skin_pgh_gold':
        return {
          mainPlush: 0x4B535E,
          bellyCorduroy: 0xF5DEB3,
          earAccent: 0xF1C40F,
          armRibbon: 0x333B42,
          stitchColor: 0x1E272E,
          antennaBall: 0xF39C12,
          heartLed: 0xFFD32A
        };
      case 'skin_cyber_neon':
        return {
          mainPlush: 0x00A8A8,
          bellyCorduroy: 0xE0FFFF,
          earAccent: 0xFF3838,
          armRibbon: 0x008080,
          stitchColor: 0x004D4D,
          antennaBall: 0xFF5E57,
          heartLed: 0x0BE881
        };
      case 'skin_mint_coral':
      default:
        // Authentic Jellycat Robot Stuffie colorway:
        // Soft vintage slate/sage teal plush, cream linen corduroy tummy, mustard ear dials, yellow pom-pom
        return {
          mainPlush: 0x6C9A8B,
          bellyCorduroy: 0xF7F4EA,
          earAccent: 0xE59866,
          armRibbon: 0x52796F,
          stitchColor: 0x2F4F4F,
          antennaBall: 0xF9CA24,
          heartLed: 0xEB4D4B
        };
    }
  }

  public setFacing(dir: 'left' | 'right' | 'front'): void {
    this.facing = dir;
    if (this.destroyed || !this.characterContainer) return;
    if (dir === 'left') {
      this.characterContainer.scale.x = -1;
    } else {
      this.characterContainer.scale.x = 1;
    }
  }

  public getFacing(): 'left' | 'right' | 'front' {
    return this.facing;
  }

  public updateAppearance(): void {
    this.renderRobot();
  }

  public renderRobot(): void {
    if (this.destroyed || !this.bodyGfx) return;
    this.renderShadow();
    this.renderLimbsAndBody();
    this.renderFace();
    this.renderAccessories();
  }

  private renderShadow(): void {
    if (this.destroyed || !this.shadowGfx) return;
    this.shadowGfx.clear();
    if (!this.showShadow) return;
    const s = this.scaleFactor;
    this.shadowGfx.ellipse(0, 62 * s, 34 * s, 11 * s);
    this.shadowGfx.fill({ color: 0x000000, alpha: 0.28 });
  }

  private renderLimbsAndBody(): void {
    if (this.destroyed || !this.bodyGfx) return;
    const c = this.getSkinColor();
    const s = this.scaleFactor;

    // 1. Stubby Plush Legs & Rounded Suedette Feet
    this.leftLegGfx.clear();
    this.leftLegGfx.roundRect(-24 * s, 36 * s, 16 * s, 24 * s, 7 * s);
    this.leftLegGfx.fill({ color: c.mainPlush });
    this.leftLegGfx.stroke({ width: 2.5 * s, color: c.stitchColor });
    this.leftLegGfx.roundRect(-27 * s, 52 * s, 22 * s, 12 * s, 6 * s);
    this.leftLegGfx.fill({ color: c.earAccent });
    this.leftLegGfx.stroke({ width: 2 * s, color: c.stitchColor });

    this.rightLegGfx.clear();
    this.rightLegGfx.roundRect(8 * s, 36 * s, 16 * s, 24 * s, 7 * s);
    this.rightLegGfx.fill({ color: c.mainPlush });
    this.rightLegGfx.stroke({ width: 2.5 * s, color: c.stitchColor });
    this.rightLegGfx.roundRect(5 * s, 52 * s, 22 * s, 12 * s, 6 * s);
    this.rightLegGfx.fill({ color: c.earAccent });
    this.rightLegGfx.stroke({ width: 2 * s, color: c.stitchColor });

    // 2. Accordion Ribbed Plush Arms & Padded Paws
    this.leftArmGfx.clear();
    const lax = -42 * s;
    const lay = -2 * s;
    for (let i = 0; i < 4; i++) {
      this.leftArmGfx.roundRect(lax - i * 3 * s, lay + i * 8 * s, 14 * s, 7 * s, 3 * s);
      this.leftArmGfx.fill({ color: i % 2 === 0 ? c.mainPlush : c.armRibbon });
      this.leftArmGfx.stroke({ width: 1.5 * s, color: c.stitchColor });
    }
    this.leftArmGfx.circle(lax - 10 * s, lay + 34 * s, 7 * s);
    this.leftArmGfx.fill({ color: c.earAccent });
    this.leftArmGfx.stroke({ width: 2 * s, color: c.stitchColor });

    this.rightArmGfx.clear();
    const rax = 30 * s;
    const ray = -2 * s;
    for (let i = 0; i < 4; i++) {
      this.rightArmGfx.roundRect(rax + i * 3 * s, ray + i * 8 * s, 14 * s, 7 * s, 3 * s);
      this.rightArmGfx.fill({ color: i % 2 === 0 ? c.mainPlush : c.armRibbon });
      this.rightArmGfx.stroke({ width: 1.5 * s, color: c.stitchColor });
    }
    this.rightArmGfx.circle(rax + 22 * s, ray + 34 * s, 7 * s);
    this.rightArmGfx.fill({ color: c.earAccent });
    this.rightArmGfx.stroke({ width: 2 * s, color: c.stitchColor });

    // 3. Plush Torso & Stitch Seams
    this.bodyGfx.clear();
    this.bodyGfx.roundRect(-36 * s, -16 * s, 72 * s, 64 * s, 18 * s);
    this.bodyGfx.fill({ color: 0x000000, alpha: 0.16 });
    this.bodyGfx.roundRect(-34 * s, -18 * s, 68 * s, 62 * s, 16 * s);
    this.bodyGfx.fill({ color: c.mainPlush });
    this.bodyGfx.stroke({ width: 3 * s, color: c.stitchColor });

    for (let y = -8 * s; y <= 32 * s; y += 8 * s) {
      this.bodyGfx.moveTo(-32 * s, y);
      this.bodyGfx.lineTo(-27 * s, y);
      this.bodyGfx.moveTo(32 * s, y);
      this.bodyGfx.lineTo(27 * s, y);
    }
    this.bodyGfx.stroke({ width: 1.5 * s, color: c.stitchColor, alpha: 0.45 });

    // 4. Cream Corduroy Tummy Panel & LED Heart
    this.chestGfx.clear();
    this.chestGfx.roundRect(-22 * s, -6 * s, 44 * s, 42 * s, 10 * s);
    this.chestGfx.fill({ color: c.bellyCorduroy });
    this.chestGfx.stroke({ width: 2 * s, color: c.stitchColor });

    for (let x = -16 * s; x <= 16 * s; x += 5 * s) {
      this.chestGfx.moveTo(x, -4 * s);
      this.chestGfx.lineTo(x, 34 * s);
    }
    this.chestGfx.stroke({ width: 1 * s, color: 0xE0D8C3, alpha: 0.8 });

    const hx = 0;
    const hy = 8 * s;
    const hs = 6 * s;
    this.chestGfx.moveTo(hx, hy + hs);
    this.chestGfx.bezierCurveTo(hx - hs * 1.5, hy - hs * 0.5, hx - hs * 1.5, hy - hs * 1.8, hx, hy - hs * 0.8);
    this.chestGfx.bezierCurveTo(hx + hs * 1.5, hy - hs * 1.8, hx + hs * 1.5, hy - hs * 0.5, hx, hy + hs);
    this.chestGfx.fill({ color: c.heartLed });

    this.chestGfx.circle(-12 * s, 24 * s, 4 * s);
    this.chestGfx.circle(12 * s, 24 * s, 4 * s);
    this.chestGfx.fill({ color: c.earAccent });
    this.chestGfx.stroke({ width: 1.5 * s, color: c.stitchColor });

    this.chestGfx.arc(0, 24 * s, 6 * s, Math.PI, 0);
    this.chestGfx.stroke({ width: 2 * s, color: c.stitchColor });

    // 5. Plush Robot Head & Seams
    this.headGfx.clear();
    this.headGfx.roundRect(-36 * s, -70 * s, 72 * s, 50 * s, 15 * s);
    this.headGfx.fill({ color: c.mainPlush });
    this.headGfx.stroke({ width: 3 * s, color: c.stitchColor });

    this.headGfx.moveTo(-22 * s, -68 * s);
    this.headGfx.lineTo(22 * s, -68 * s);
    this.headGfx.stroke({ width: 1.8 * s, color: c.stitchColor, alpha: 0.6 });

    // 6. Cylindrical Spool Ear Dials
    this.earsGfx.clear();
    this.earsGfx.roundRect(-46 * s, -52 * s, 12 * s, 16 * s, 4 * s);
    this.earsGfx.fill({ color: c.earAccent });
    this.earsGfx.stroke({ width: 2 * s, color: c.stitchColor });
    this.earsGfx.circle(-40 * s, -44 * s, 3 * s);
    this.earsGfx.fill({ color: c.bellyCorduroy });

    this.earsGfx.roundRect(34 * s, -52 * s, 12 * s, 16 * s, 4 * s);
    this.earsGfx.fill({ color: c.earAccent });
    this.earsGfx.stroke({ width: 2 * s, color: c.stitchColor });
    this.earsGfx.circle(40 * s, -44 * s, 3 * s);
    this.earsGfx.fill({ color: c.bellyCorduroy });

    // 7. Jellycat Plush Antenna
    this.antennaGfx.clear();
    const acc = GameState.getInstance()?.progress?.equippedAccessories;
    const isHatNone = !acc?.hat || acc.hat === 'hat_none';

    if (isHatNone) {
      this.antennaGfx.roundRect(-4 * s, -86 * s, 8 * s, 18 * s, 3 * s);
      this.antennaGfx.fill({ color: c.armRibbon });
      this.antennaGfx.stroke({ width: 2 * s, color: c.stitchColor });

      this.antennaGfx.moveTo(-4 * s, -76 * s);
      this.antennaGfx.lineTo(4 * s, -76 * s);
      this.antennaGfx.moveTo(-4 * s, -81 * s);
      this.antennaGfx.lineTo(4 * s, -81 * s);
      this.antennaGfx.stroke({ width: 1.5 * s, color: c.earAccent });

      this.antennaGfx.circle(0, -92 * s, 9.5 * s);
      this.antennaGfx.fill({ color: c.antennaBall });
      this.antennaGfx.stroke({ width: 2.5 * s, color: 0xD68910 });
      this.antennaGfx.circle(-3 * s, -95 * s, 2.5 * s);
      this.antennaGfx.fill({ color: 0xFFFFFF, alpha: 0.8 });
    }
  }

  public renderFace(): void {
    if (this.destroyed || !this.eyesGfx || !this.mouthGfx) return;
    const s = this.scaleFactor;
    this.eyesGfx.clear();
    this.mouthGfx.clear();

    const eyeLeftX = -15 * s;
    const eyeRightX = 15 * s;
    const eyeY = -46 * s;

    if (this.eyeState === 'normal') {
      this.eyesGfx.circle(eyeLeftX, eyeY, 7.5 * s);
      this.eyesGfx.circle(eyeRightX, eyeY, 7.5 * s);
      this.eyesGfx.fill({ color: 0x1E272E });

      this.eyesGfx.circle(eyeLeftX - 2.5 * s, eyeY - 2.5 * s, 2.8 * s);
      this.eyesGfx.circle(eyeRightX - 2.5 * s, eyeY - 2.5 * s, 2.8 * s);
      this.eyesGfx.circle(eyeLeftX + 2.5 * s, eyeY + 2.5 * s, 1.2 * s);
      this.eyesGfx.circle(eyeRightX + 2.5 * s, eyeY + 2.5 * s, 1.2 * s);
      this.eyesGfx.fill({ color: 0xFFFFFF });

      this.eyesGfx.ellipse(eyeLeftX - 6 * s, eyeY + 9 * s, 5.5 * s, 3 * s);
      this.eyesGfx.ellipse(eyeRightX + 6 * s, eyeY + 9 * s, 5.5 * s, 3 * s);
      this.eyesGfx.fill({ color: 0xFF8A80, alpha: 0.65 });

      this.mouthGfx.arc(0, -36 * s, 6.5 * s, 0.2, Math.PI - 0.2);
      this.mouthGfx.stroke({ width: 2.5 * s, color: 0x1E272E, cap: 'round' });
    } else if (this.eyeState === 'happy') {
      this.eyesGfx.arc(eyeLeftX, eyeY, 7 * s, Math.PI * 1.15, Math.PI * 1.85);
      this.eyesGfx.arc(eyeRightX, eyeY, 7 * s, Math.PI * 1.15, Math.PI * 1.85);
      this.eyesGfx.stroke({ width: 3.5 * s, color: 0x1E272E, cap: 'round' });

      this.eyesGfx.ellipse(eyeLeftX - 6 * s, eyeY + 6 * s, 6 * s, 3.5 * s);
      this.eyesGfx.ellipse(eyeRightX + 6 * s, eyeY + 6 * s, 6 * s, 3.5 * s);
      this.eyesGfx.fill({ color: 0xFF5252, alpha: 0.8 });

      this.mouthGfx.arc(0, -35 * s, 8 * s, 0, Math.PI);
      this.mouthGfx.fill({ color: 0xFF5252 });
      this.mouthGfx.stroke({ width: 2 * s, color: 0x1E272E });
    } else if (this.eyeState === 'blink') {
      this.eyesGfx.moveTo(eyeLeftX - 6 * s, eyeY);
      this.eyesGfx.lineTo(eyeLeftX + 6 * s, eyeY);
      this.eyesGfx.moveTo(eyeRightX - 6 * s, eyeY);
      this.eyesGfx.lineTo(eyeRightX + 6 * s, eyeY);
      this.eyesGfx.stroke({ width: 3 * s, color: 0x1E272E, cap: 'round' });

      this.mouthGfx.arc(0, -36 * s, 5 * s, 0.2, Math.PI - 0.2);
      this.mouthGfx.stroke({ width: 2 * s, color: 0x1E272E, cap: 'round' });
    } else if (this.eyeState === 'surprised') {
      this.eyesGfx.circle(eyeLeftX, eyeY, 8.5 * s);
      this.eyesGfx.circle(eyeRightX, eyeY, 8.5 * s);
      this.eyesGfx.fill({ color: 0xFFFFFF });
      this.eyesGfx.stroke({ width: 2.5 * s, color: 0x1E272E });

      this.eyesGfx.circle(eyeLeftX, eyeY, 4 * s);
      this.eyesGfx.circle(eyeRightX, eyeY, 4 * s);
      this.eyesGfx.fill({ color: 0x1E272E });

      this.mouthGfx.circle(0, -34 * s, 3.5 * s);
      this.mouthGfx.fill({ color: 0x1E272E });
    }
  }

  public renderAccessories(): void {
    if (this.destroyed || !this.accessoriesContainer) return;
    this.renderBackAccessories();
    this.renderFrontAccessories();
    this.renderCompanion();
  }

  private renderBackAccessories(): void {
    if (this.destroyed || !this.backLayerGfx) return;
    this.backLayerGfx.clear();
    const s = this.scaleFactor;
    const state = GameState.getInstance();
    const acc = state?.progress?.equippedAccessories || {};

    // 1. Cape Back Layer (scarf_cape)
    if (acc.scarf === 'scarf_cape') {
      this.backLayerGfx.moveTo(-28 * s, -16 * s);
      this.backLayerGfx.lineTo(28 * s, -16 * s);
      this.backLayerGfx.lineTo(38 * s, 46 * s);
      this.backLayerGfx.bezierCurveTo(20 * s, 40 * s, -20 * s, 40 * s, -38 * s, 46 * s);
      this.backLayerGfx.lineTo(-28 * s, -16 * s);
      this.backLayerGfx.fill({ color: 0x3867D6 });
      this.backLayerGfx.stroke({ width: 2.5 * s, color: 0xF1C40F });

      // Starlight emblems on cape
      this.backLayerGfx.circle(-18 * s, 18 * s, 2.5 * s);
      this.backLayerGfx.circle(18 * s, 22 * s, 2.5 * s);
      this.backLayerGfx.circle(0, 30 * s, 3 * s);
      this.backLayerGfx.fill({ color: 0xFFD32A });
    }

    // 2. Back Items
    if (acc.back === 'back_none') {
      // Retro brass wind-up key
      this.backLayerGfx.roundRect(-42 * s, 2 * s, 14 * s, 6 * s, 2 * s);
      this.backLayerGfx.fill({ color: 0xF39C12 });
      this.backLayerGfx.stroke({ width: 1.5 * s, color: 0xD68910 });
      this.backLayerGfx.circle(-46 * s, 0 * s, 6.5 * s);
      this.backLayerGfx.circle(-46 * s, 10 * s, 6.5 * s);
      this.backLayerGfx.fill({ color: 0xF1C40F });
      this.backLayerGfx.stroke({ width: 1.5 * s, color: 0xD68910 });
      this.backLayerGfx.circle(-46 * s, 0 * s, 2.5 * s);
      this.backLayerGfx.circle(-46 * s, 10 * s, 2.5 * s);
      this.backLayerGfx.fill({ color: 0x1E272E, alpha: 0.6 });
    } else if (acc.back === 'back_jetpack') {
      // Dual Neon Blue Rocket Thrusters with exhaust flames
      this.backLayerGfx.roundRect(-36 * s, 4 * s, 72 * s, 8 * s, 3 * s);
      this.backLayerGfx.fill({ color: 0x2F3542 });
      this.backLayerGfx.stroke({ width: 1.5 * s, color: 0x57606F });

      // Left canister
      this.backLayerGfx.roundRect(-46 * s, -8 * s, 12 * s, 38 * s, 5 * s);
      this.backLayerGfx.fill({ color: 0x70A1FF });
      this.backLayerGfx.stroke({ width: 2 * s, color: 0x1E90FF });
      this.backLayerGfx.circle(-40 * s, 4 * s, 3 * s);
      this.backLayerGfx.fill({ color: 0xE0FFFF });

      // Right canister
      this.backLayerGfx.roundRect(34 * s, -8 * s, 12 * s, 38 * s, 5 * s);
      this.backLayerGfx.fill({ color: 0x70A1FF });
      this.backLayerGfx.stroke({ width: 2 * s, color: 0x1E90FF });
      this.backLayerGfx.circle(40 * s, 4 * s, 3 * s);
      this.backLayerGfx.fill({ color: 0xE0FFFF });

      // Left flame plume
      this.backLayerGfx.moveTo(-45 * s, 30 * s);
      this.backLayerGfx.lineTo(-35 * s, 30 * s);
      this.backLayerGfx.lineTo(-40 * s, 48 * s);
      this.backLayerGfx.fill({ color: 0xFF6348 });
      this.backLayerGfx.moveTo(-43 * s, 30 * s);
      this.backLayerGfx.lineTo(-37 * s, 30 * s);
      this.backLayerGfx.lineTo(-40 * s, 42 * s);
      this.backLayerGfx.fill({ color: 0xFFA502 });

      // Right flame plume
      this.backLayerGfx.moveTo(35 * s, 30 * s);
      this.backLayerGfx.lineTo(45 * s, 30 * s);
      this.backLayerGfx.lineTo(40 * s, 48 * s);
      this.backLayerGfx.fill({ color: 0xFF6348 });
      this.backLayerGfx.moveTo(37 * s, 30 * s);
      this.backLayerGfx.lineTo(43 * s, 30 * s);
      this.backLayerGfx.lineTo(40 * s, 42 * s);
      this.backLayerGfx.fill({ color: 0xFFA502 });
    } else if (acc.back === 'back_angel_wings') {
      // Left plush feather wing
      this.backLayerGfx.moveTo(-20 * s, 0);
      this.backLayerGfx.bezierCurveTo(-45 * s, -38 * s, -65 * s, -22 * s, -60 * s, 8 * s);
      this.backLayerGfx.bezierCurveTo(-55 * s, 24 * s, -35 * s, 28 * s, -20 * s, 18 * s);
      this.backLayerGfx.fill({ color: 0xFFFFFF });
      this.backLayerGfx.stroke({ width: 2.5 * s, color: 0xFFD32A });

      // Left inner feather
      this.backLayerGfx.moveTo(-35 * s, -12 * s);
      this.backLayerGfx.bezierCurveTo(-50 * s, -6 * s, -52 * s, 10 * s, -30 * s, 14 * s);
      this.backLayerGfx.fill({ color: 0xF1F2F6 });

      // Right plush feather wing
      this.backLayerGfx.moveTo(20 * s, 0);
      this.backLayerGfx.bezierCurveTo(45 * s, -38 * s, 65 * s, -22 * s, 60 * s, 8 * s);
      this.backLayerGfx.bezierCurveTo(55 * s, 24 * s, 35 * s, 28 * s, 20 * s, 18 * s);
      this.backLayerGfx.fill({ color: 0xFFFFFF });
      this.backLayerGfx.stroke({ width: 2.5 * s, color: 0xFFD32A });

      // Right inner feather
      this.backLayerGfx.moveTo(35 * s, -12 * s);
      this.backLayerGfx.bezierCurveTo(50 * s, -6 * s, 52 * s, 10 * s, 30 * s, 14 * s);
      this.backLayerGfx.fill({ color: 0xF1F2F6 });

      // Golden sparkle stars
      this.backLayerGfx.circle(-56 * s, -6 * s, 2 * s);
      this.backLayerGfx.circle(56 * s, -6 * s, 2 * s);
      this.backLayerGfx.fill({ color: 0xFFD32A });
    } else if (acc.back === 'back_backpack') {
      // Leatherette explorer knapsack body
      this.backLayerGfx.roundRect(-30 * s, -10 * s, 60 * s, 42 * s, 10 * s);
      this.backLayerGfx.fill({ color: 0x8C5024 });
      this.backLayerGfx.stroke({ width: 2.5 * s, color: 0x543011 });

      // Flap
      this.backLayerGfx.roundRect(-26 * s, -12 * s, 52 * s, 20 * s, 6 * s);
      this.backLayerGfx.fill({ color: 0xA0522D });
      this.backLayerGfx.stroke({ width: 2 * s, color: 0x543011 });

      // Buckle
      this.backLayerGfx.roundRect(-6 * s, 4 * s, 12 * s, 10 * s, 2 * s);
      this.backLayerGfx.fill({ color: 0xF1C40F });
      this.backLayerGfx.rect(-3 * s, 6 * s, 6 * s, 6 * s);
      this.backLayerGfx.fill({ color: 0x543011 });

      // Rolled-up map
      this.backLayerGfx.roundRect(-22 * s, -22 * s, 12 * s, 16 * s, 3 * s);
      this.backLayerGfx.fill({ color: 0xF5CD79 });
      this.backLayerGfx.stroke({ width: 1.5 * s, color: 0xD35400 });

      // Ruler / Pencil
      this.backLayerGfx.roundRect(12 * s, -24 * s, 6 * s, 20 * s, 2 * s);
      this.backLayerGfx.fill({ color: 0xFF4757 });
    }
  }

  private renderFrontAccessories(): void {
    if (this.destroyed || !this.frontAccGfx) return;
    this.frontAccGfx.clear();
    const s = this.scaleFactor;
    const state = GameState.getInstance();
    const acc = state?.progress?.equippedAccessories || {};

    // 1. Backpack Front Straps
    if (acc.back === 'back_backpack') {
      this.frontAccGfx.roundRect(-22 * s, -14 * s, 7 * s, 44 * s, 3 * s);
      this.frontAccGfx.fill({ color: 0x8C5024 });
      this.frontAccGfx.stroke({ width: 1.5 * s, color: 0x543011 });

      this.frontAccGfx.roundRect(15 * s, -14 * s, 7 * s, 44 * s, 3 * s);
      this.frontAccGfx.fill({ color: 0x8C5024 });
      this.frontAccGfx.stroke({ width: 1.5 * s, color: 0x543011 });
    }

    // 2. Hats
    if (acc.hat === 'hat_star_tiara') {
      // 3-pointed sparkling gold tiara with ruby heart center
      this.frontAccGfx.roundRect(-24 * s, -73 * s, 48 * s, 8 * s, 3 * s);
      this.frontAccGfx.fill({ color: 0xF1C40F });
      this.frontAccGfx.stroke({ width: 2 * s, color: 0xD68910 });

      this.frontAccGfx.moveTo(-24 * s, -73 * s);
      this.frontAccGfx.lineTo(-16 * s, -88 * s);
      this.frontAccGfx.lineTo(-6 * s, -75 * s);
      this.frontAccGfx.lineTo(0, -94 * s);
      this.frontAccGfx.lineTo(6 * s, -75 * s);
      this.frontAccGfx.lineTo(16 * s, -88 * s);
      this.frontAccGfx.lineTo(24 * s, -73 * s);
      this.frontAccGfx.fill({ color: 0xFFD32A });
      this.frontAccGfx.stroke({ width: 2 * s, color: 0xF39C12 });

      // Ruby heart center
      const rx = 0;
      const ry = -82 * s;
      const rs = 4 * s;
      this.frontAccGfx.moveTo(rx, ry + rs);
      this.frontAccGfx.bezierCurveTo(rx - rs * 1.5, ry - rs * 0.5, rx - rs * 1.5, ry - rs * 1.8, rx, ry - rs * 0.8);
      this.frontAccGfx.bezierCurveTo(rx + rs * 1.5, ry - rs * 1.8, rx + rs * 1.5, ry - rs * 0.5, rx, ry + rs);
      this.frontAccGfx.fill({ color: 0xFF4757 });

      // Side Jewels
      this.frontAccGfx.circle(-16 * s, -83 * s, 2.5 * s);
      this.frontAccGfx.circle(16 * s, -83 * s, 2.5 * s);
      this.frontAccGfx.fill({ color: 0x70A1FF });

      // Sparkle shine dots
      this.frontAccGfx.circle(0, -96 * s, 2 * s);
      this.frontAccGfx.fill({ color: 0xFFFFFF });
    } else if (acc.hat === 'hat_pierogi') {
      // Golden plush crescent pierogi perched on head
      this.frontAccGfx.moveTo(-28 * s, -70 * s);
      this.frontAccGfx.bezierCurveTo(-30 * s, -88 * s, -15 * s, -96 * s, 0, -96 * s);
      this.frontAccGfx.bezierCurveTo(15 * s, -96 * s, 30 * s, -88 * s, 28 * s, -70 * s);
      this.frontAccGfx.bezierCurveTo(15 * s, -73 * s, -15 * s, -73 * s, -28 * s, -70 * s);
      this.frontAccGfx.fill({ color: 0xF5CD79 });
      this.frontAccGfx.stroke({ width: 2.5 * s, color: 0xD35400 });

      // Crimped edge dough ruffles
      const crimps = [-24, -16, -6, 6, 16, 24];
      const crimpYs = [-78, -86, -92, -92, -86, -78];
      for (let i = 0; i < crimps.length; i++) {
        this.frontAccGfx.circle(crimps[i] * s, crimpYs[i] * s, 3.5 * s);
        this.frontAccGfx.fill({ color: 0xF5CD79 });
        this.frontAccGfx.stroke({ width: 1.5 * s, color: 0xD35400 });
      }

      // Melting butter pat
      this.frontAccGfx.roundRect(-7 * s, -92 * s, 14 * s, 7 * s, 2.5 * s);
      this.frontAccGfx.fill({ color: 0xFFEAA7 });
      this.frontAccGfx.stroke({ width: 1.2 * s, color: 0xF39C12 });
      this.frontAccGfx.circle(4 * s, -88 * s, 1.5 * s);
      this.frontAccGfx.fill({ color: 0x2ECC71 });
    } else if (acc.hat === 'hat_kitty_ears') {
      // Fuzzy pink plush cat ears
      this.frontAccGfx.moveTo(-32 * s, -68 * s);
      this.frontAccGfx.lineTo(-26 * s, -94 * s);
      this.frontAccGfx.lineTo(-12 * s, -70 * s);
      this.frontAccGfx.fill({ color: 0xFFA8B6 });
      this.frontAccGfx.stroke({ width: 2.5 * s, color: 0xFF6B81 });

      this.frontAccGfx.moveTo(-28 * s, -70 * s);
      this.frontAccGfx.lineTo(-24 * s, -88 * s);
      this.frontAccGfx.lineTo(-15 * s, -71 * s);
      this.frontAccGfx.fill({ color: 0xFF4757 });

      this.frontAccGfx.moveTo(12 * s, -70 * s);
      this.frontAccGfx.lineTo(26 * s, -94 * s);
      this.frontAccGfx.lineTo(32 * s, -68 * s);
      this.frontAccGfx.fill({ color: 0xFFA8B6 });
      this.frontAccGfx.stroke({ width: 2.5 * s, color: 0xFF6B81 });

      this.frontAccGfx.moveTo(15 * s, -71 * s);
      this.frontAccGfx.lineTo(24 * s, -88 * s);
      this.frontAccGfx.lineTo(28 * s, -70 * s);
      this.frontAccGfx.fill({ color: 0xFF4757 });

      this.frontAccGfx.circle(-26 * s, -72 * s, 3 * s);
      this.frontAccGfx.circle(26 * s, -72 * s, 3 * s);
      this.frontAccGfx.fill({ color: 0xFFFFFF });
    } else if (acc.hat === 'hat_steeler') {
      // Black & Gold Football Helmet
      this.frontAccGfx.arc(0, -48 * s, 42 * s, Math.PI * 0.95, Math.PI * 0.05);
      this.frontAccGfx.fill({ color: 0x1E272E });
      this.frontAccGfx.stroke({ width: 3 * s, color: 0x000000 });

      // Gold racing center stripe
      this.frontAccGfx.rect(-6 * s, -90 * s, 12 * s, 28 * s);
      this.frontAccGfx.fill({ color: 0xF1C40F });

      // Visor / brow rim
      this.frontAccGfx.roundRect(-36 * s, -68 * s, 72 * s, 10 * s, 4 * s);
      this.frontAccGfx.fill({ color: 0x2C3A47 });
      this.frontAccGfx.stroke({ width: 2 * s, color: 0xF1C40F });

      // Face cage grill
      this.frontAccGfx.moveTo(-20 * s, -45 * s);
      this.frontAccGfx.lineTo(20 * s, -45 * s);
      this.frontAccGfx.moveTo(-16 * s, -40 * s);
      this.frontAccGfx.lineTo(16 * s, -40 * s);
      this.frontAccGfx.moveTo(-10 * s, -48 * s);
      this.frontAccGfx.lineTo(-10 * s, -38 * s);
      this.frontAccGfx.moveTo(10 * s, -48 * s);
      this.frontAccGfx.lineTo(10 * s, -38 * s);
      this.frontAccGfx.stroke({ width: 2.5 * s, color: 0xBDC3C7 });

      // Hypocycloid colored dots on side
      this.frontAccGfx.circle(24 * s, -62 * s, 2.5 * s);
      this.frontAccGfx.fill({ color: 0xF1C40F });
      this.frontAccGfx.circle(30 * s, -56 * s, 2.5 * s);
      this.frontAccGfx.fill({ color: 0xE74C3C });
      this.frontAccGfx.circle(24 * s, -50 * s, 2.5 * s);
      this.frontAccGfx.fill({ color: 0x3498DB });
    } else if (acc.hat === 'hat_wizard') {
      // Cosmic Wizard Hat with brim and yellow stars
      this.frontAccGfx.ellipse(0, -70 * s, 38 * s, 9 * s);
      this.frontAccGfx.fill({ color: 0x5758BB });
      this.frontAccGfx.stroke({ width: 2.5 * s, color: 0x341F97 });

      this.frontAccGfx.moveTo(-28 * s, -70 * s);
      this.frontAccGfx.bezierCurveTo(-15 * s, -95 * s, -8 * s, -108 * s, -2 * s, -118 * s);
      this.frontAccGfx.bezierCurveTo(12 * s, -112 * s, 20 * s, -90 * s, 28 * s, -70 * s);
      this.frontAccGfx.fill({ color: 0x8854D0 });
      this.frontAccGfx.stroke({ width: 2.5 * s, color: 0x341F97 });

      // Glowing tip star
      this.frontAccGfx.circle(-2 * s, -118 * s, 5 * s);
      this.frontAccGfx.fill({ color: 0xFFD32A });
      this.frontAccGfx.stroke({ width: 1.5 * s, color: 0xF39C12 });

      // Crescent moon on hat
      this.frontAccGfx.circle(-6 * s, -88 * s, 6 * s);
      this.frontAccGfx.fill({ color: 0xFFD32A });
      this.frontAccGfx.circle(-3 * s, -88 * s, 4.5 * s);
      this.frontAccGfx.fill({ color: 0x8854D0 });

      // Golden math plus rune
      this.frontAccGfx.moveTo(10 * s, -85 * s);
      this.frontAccGfx.lineTo(16 * s, -85 * s);
      this.frontAccGfx.moveTo(13 * s, -88 * s);
      this.frontAccGfx.lineTo(13 * s, -82 * s);
      this.frontAccGfx.stroke({ width: 2 * s, color: 0xFFD32A });
      this.frontAccGfx.circle(8 * s, -98 * s, 2 * s);
      this.frontAccGfx.fill({ color: 0xFFD32A });
    }

    // 3. Scarves & Neckwear
    if (acc.scarf === 'scarf_pgh_gold') {
      // Knitted black & gold striped winter scarf
      this.frontAccGfx.roundRect(-32 * s, -22 * s, 64 * s, 16 * s, 6 * s);
      this.frontAccGfx.fill({ color: 0xF1C40F });
      this.frontAccGfx.stroke({ width: 2.5 * s, color: 0x1E272E });

      // Black stripes
      this.frontAccGfx.rect(-20 * s, -22 * s, 8 * s, 16 * s);
      this.frontAccGfx.rect(0, -22 * s, 8 * s, 16 * s);
      this.frontAccGfx.rect(20 * s, -22 * s, 8 * s, 16 * s);
      this.frontAccGfx.fill({ color: 0x1E272E });

      // Scarf tail dangling
      this.frontAccGfx.roundRect(14 * s, -10 * s, 14 * s, 36 * s, 5 * s);
      this.frontAccGfx.fill({ color: 0xF1C40F });
      this.frontAccGfx.stroke({ width: 2 * s, color: 0x1E272E });
      this.frontAccGfx.rect(14 * s, 2 * s, 14 * s, 8 * s);
      this.frontAccGfx.rect(14 * s, 18 * s, 14 * s, 8 * s);
      this.frontAccGfx.fill({ color: 0x1E272E });

      // Fringe tassels
      for (let fx = 15; fx <= 27; fx += 3) {
        this.frontAccGfx.moveTo(fx * s, 26 * s);
        this.frontAccGfx.lineTo(fx * s, 33 * s);
      }
      this.frontAccGfx.stroke({ width: 1.5 * s, color: 0xF1C40F });
    } else if (acc.scarf === 'scarf_pink_bow') {
      // Bubblegum satin bow tie with glowing ruby heart jewel
      this.frontAccGfx.moveTo(0, -14 * s);
      this.frontAccGfx.lineTo(-22 * s, -24 * s);
      this.frontAccGfx.lineTo(-22 * s, -4 * s);
      this.frontAccGfx.lineTo(0, -14 * s);
      this.frontAccGfx.lineTo(22 * s, -24 * s);
      this.frontAccGfx.lineTo(22 * s, -4 * s);
      this.frontAccGfx.lineTo(0, -14 * s);
      this.frontAccGfx.fill({ color: 0xFF6B81 });
      this.frontAccGfx.stroke({ width: 2 * s, color: 0xFF4757 });

      this.frontAccGfx.circle(0, -14 * s, 6.5 * s);
      this.frontAccGfx.fill({ color: 0xFF4757 });

      // Ruby heart center
      const bx = 0;
      const by = -14 * s;
      const bs = 3.5 * s;
      this.frontAccGfx.moveTo(bx, by + bs);
      this.frontAccGfx.bezierCurveTo(bx - bs * 1.5, by - bs * 0.5, bx - bs * 1.5, by - bs * 1.8, bx, by - bs * 0.8);
      this.frontAccGfx.bezierCurveTo(bx + bs * 1.5, by - bs * 1.8, bx + bs * 1.5, by - bs * 0.5, bx, by + bs);
      this.frontAccGfx.fill({ color: 0xFFFFFF });

      this.frontAccGfx.roundRect(-8 * s, -8 * s, 6 * s, 16 * s, 2 * s);
      this.frontAccGfx.roundRect(2 * s, -8 * s, 6 * s, 16 * s, 2 * s);
      this.frontAccGfx.fill({ color: 0xFF6B81 });
    } else if (acc.scarf === 'scarf_cape') {
      // Golden neck collar & starlight hero brooch clasp
      this.frontAccGfx.roundRect(-26 * s, -20 * s, 52 * s, 10 * s, 4 * s);
      this.frontAccGfx.fill({ color: 0xF1C40F });
      this.frontAccGfx.stroke({ width: 2 * s, color: 0xD35400 });

      this.frontAccGfx.circle(0, -15 * s, 6 * s);
      this.frontAccGfx.fill({ color: 0xFFD32A });
      this.frontAccGfx.stroke({ width: 1.5 * s, color: 0xD35400 });
      this.frontAccGfx.circle(0, -15 * s, 2.5 * s);
      this.frontAccGfx.fill({ color: 0xFF4757 });
    }
  }

  private renderCompanion(): void {
    if (this.destroyed || !this.companionGfx) return;
    this.companionGfx.clear();
    const s = this.scaleFactor;
    const state = GameState.getInstance();
    const acc = state?.progress?.equippedAccessories || {};

    if (acc.companion === 'comp_alien_blob') {
      // Bubbles the Star Alien
      const cx = 50 * s;
      const cy = -22 * s;

      // Slime blob body
      this.companionGfx.circle(cx, cy, 15 * s);
      this.companionGfx.fill({ color: 0x2ED573 });
      this.companionGfx.stroke({ width: 2.5 * s, color: 0x26AF5F });

      // Bottom slime droplets
      this.companionGfx.circle(cx - 8 * s, cy + 10 * s, 4 * s);
      this.companionGfx.circle(cx, cy + 12 * s, 4.5 * s);
      this.companionGfx.circle(cx + 8 * s, cy + 10 * s, 4 * s);
      this.companionGfx.fill({ color: 0x2ED573 });

      // Glossy eye
      this.companionGfx.circle(cx, cy - 2 * s, 6.5 * s);
      this.companionGfx.fill({ color: 0xFFFFFF });
      this.companionGfx.circle(cx + 1 * s, cy - 2 * s, 3.5 * s);
      this.companionGfx.fill({ color: 0x1E272E });
      this.companionGfx.circle(cx - 1 * s, cy - 4 * s, 1.5 * s);
      this.companionGfx.fill({ color: 0xFFFFFF });

      // Blush cheeks & smile
      this.companionGfx.ellipse(cx - 8 * s, cy + 4 * s, 3 * s, 1.5 * s);
      this.companionGfx.ellipse(cx + 8 * s, cy + 4 * s, 3 * s, 1.5 * s);
      this.companionGfx.fill({ color: 0xFF6B81, alpha: 0.6 });

      this.companionGfx.arc(cx, cy + 3 * s, 3.5 * s, 0.2, Math.PI - 0.2);
      this.companionGfx.stroke({ width: 1.8 * s, color: 0x1E272E });

      // Top antenna with glowing star
      this.companionGfx.moveTo(cx, cy - 15 * s);
      this.companionGfx.lineTo(cx, cy - 22 * s);
      this.companionGfx.stroke({ width: 2 * s, color: 0x26AF5F });
      this.companionGfx.circle(cx, cy - 24 * s, 3.5 * s);
      this.companionGfx.fill({ color: 0xFFD32A });
    } else if (acc.companion === 'comp_robo_puppy') {
      // Bark-E the Robo-Puppy
      const px = -54 * s;
      const py = 16 * s;

      // Puppy body
      this.companionGfx.roundRect(px - 14 * s, py - 10 * s, 28 * s, 22 * s, 7 * s);
      this.companionGfx.fill({ color: 0xF1C40F });
      this.companionGfx.stroke({ width: 2.5 * s, color: 0xD68910 });

      // Floppy ears
      this.companionGfx.roundRect(px - 18 * s, py - 14 * s, 7 * s, 16 * s, 3 * s);
      this.companionGfx.fill({ color: 0x57606F });
      this.companionGfx.roundRect(px + 10 * s, py - 14 * s, 7 * s, 16 * s, 3 * s);
      this.companionGfx.fill({ color: 0x57606F });

      // Snout & Button nose
      this.companionGfx.roundRect(px - 7 * s, py, 14 * s, 10 * s, 4 * s);
      this.companionGfx.fill({ color: 0xF5DEB3 });
      this.companionGfx.circle(px, py + 2 * s, 2.5 * s);
      this.companionGfx.fill({ color: 0x1E272E });

      // Puppy eyes
      this.companionGfx.circle(px - 5 * s, py - 4 * s, 3 * s);
      this.companionGfx.fill({ color: 0x1E272E });
      this.companionGfx.circle(px - 6 * s, py - 5 * s, 1 * s);
      this.companionGfx.fill({ color: 0xFFFFFF });

      // Stubby legs
      this.companionGfx.roundRect(px - 10 * s, py + 12 * s, 6 * s, 8 * s, 2.5 * s);
      this.companionGfx.roundRect(px + 4 * s, py + 12 * s, 6 * s, 8 * s, 2.5 * s);
      this.companionGfx.fill({ color: 0x57606F });

      // Wagging tail antenna
      this.companionGfx.moveTo(px + 12 * s, py - 2 * s);
      this.companionGfx.lineTo(px + 18 * s, py - 8 * s);
      this.companionGfx.stroke({ width: 2 * s, color: 0xD68910 });
      this.companionGfx.circle(px + 19 * s, py - 9 * s, 2.5 * s);
      this.companionGfx.fill({ color: 0xFF4757 });
    } else if (acc.companion === 'comp_kitty_bot') {
      // Meow-Bit the Space Cat
      const kx = 50 * s;
      const ky = 16 * s;

      // Body
      this.companionGfx.roundRect(kx - 12 * s, ky - 10 * s, 24 * s, 20 * s, 8 * s);
      this.companionGfx.fill({ color: 0x81ECEC });
      this.companionGfx.stroke({ width: 2.5 * s, color: 0x00CEC9 });

      // Cat ears
      this.companionGfx.moveTo(kx - 10 * s, ky - 10 * s);
      this.companionGfx.lineTo(kx - 6 * s, ky - 20 * s);
      this.companionGfx.lineTo(kx - 2 * s, ky - 10 * s);
      this.companionGfx.fill({ color: 0x81ECEC });
      this.companionGfx.stroke({ width: 1.5 * s, color: 0x00CEC9 });

      this.companionGfx.moveTo(kx + 2 * s, ky - 10 * s);
      this.companionGfx.lineTo(kx + 6 * s, ky - 20 * s);
      this.companionGfx.lineTo(kx + 10 * s, ky - 10 * s);
      this.companionGfx.fill({ color: 0x81ECEC });
      this.companionGfx.stroke({ width: 1.5 * s, color: 0x00CEC9 });

      // LED Visor & glowing cyan eyes
      this.companionGfx.roundRect(kx - 8 * s, ky - 6 * s, 16 * s, 8 * s, 3 * s);
      this.companionGfx.fill({ color: 0x2D3436 });
      this.companionGfx.circle(kx - 4 * s, ky - 2 * s, 1.8 * s);
      this.companionGfx.circle(kx + 4 * s, ky - 2 * s, 1.8 * s);
      this.companionGfx.fill({ color: 0x00CEC9 });

      // Whiskers
      this.companionGfx.moveTo(kx - 14 * s, ky);
      this.companionGfx.lineTo(kx - 9 * s, ky);
      this.companionGfx.moveTo(kx - 14 * s, ky + 3 * s);
      this.companionGfx.lineTo(kx - 9 * s, ky + 4 * s);
      this.companionGfx.moveTo(kx + 9 * s, ky);
      this.companionGfx.lineTo(kx + 14 * s, ky);
      this.companionGfx.moveTo(kx + 9 * s, ky + 4 * s);
      this.companionGfx.lineTo(kx + 14 * s, ky + 3 * s);
      this.companionGfx.stroke({ width: 1.2 * s, color: 0x00CEC9 });

      // Bell collar
      this.companionGfx.roundRect(kx - 10 * s, ky + 6 * s, 20 * s, 4 * s, 2 * s);
      this.companionGfx.fill({ color: 0xFF7675 });
      this.companionGfx.circle(kx, ky + 9 * s, 2.5 * s);
      this.companionGfx.fill({ color: 0xFFD32A });

      // Robotic tail
      this.companionGfx.moveTo(kx + 12 * s, ky + 4 * s);
      this.companionGfx.bezierCurveTo(kx + 20 * s, ky + 2 * s, kx + 22 * s, ky - 10 * s, kx + 16 * s, ky - 14 * s);
      this.companionGfx.stroke({ width: 2.5 * s, color: 0x00CEC9 });
      this.companionGfx.circle(kx + 16 * s, ky - 14 * s, 2.5 * s);
      this.companionGfx.fill({ color: 0xFF7675 });

      // Hover thruster pad
      this.companionGfx.ellipse(kx, ky + 14 * s, 8 * s, 2.5 * s);
      this.companionGfx.fill({ color: 0x74B9FF, alpha: 0.8 });
    }
  }

  public walkTo(targetX: number, targetY: number, durationSec?: number, onComplete?: () => void): void {
    if (this.destroyed) {
      if (onComplete) onComplete();
      return;
    }
    this.startX = this.x;
    this.startY = this.y;
    this.targetX = targetX;
    this.targetY = targetY;

    const dx = targetX - this.startX;
    const dy = targetY - this.startY;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (Math.abs(dx) > 1) {
      this.setFacing(dx < 0 ? 'left' : 'right');
    }

    this.moveDuration = durationSec !== undefined && durationSec > 0 ? durationSec : Math.max(0.3, dist / 200);
    this.moveElapsed = 0;
    this.isWalking = true;
    this.isHopping = false;
    this.isBouncing = false;
    this.onMoveComplete = onComplete;
  }

  public hopTo(targetX: number, targetY: number, durationSec?: number, onComplete?: () => void): void {
    if (this.destroyed) {
      if (onComplete) onComplete();
      return;
    }
    this.startX = this.x;
    this.startY = this.y;
    this.targetX = targetX;
    this.targetY = targetY;

    const dx = targetX - this.startX;
    const dy = targetY - this.startY;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (Math.abs(dx) > 1) {
      this.setFacing(dx < 0 ? 'left' : 'right');
    }

    this.moveDuration = durationSec !== undefined && durationSec > 0 ? durationSec : Math.max(0.35, dist / 180);
    this.moveElapsed = 0;
    this.isHopping = true;
    this.isWalking = false;
    this.isBouncing = false;
    this.onMoveComplete = onComplete;
    this.setEyeState('happy');
  }

  private resetLimbTransforms(): void {
    if (this.destroyed) return;
    this.leftLegGfx.rotation = 0;
    this.leftLegGfx.y = 0;
    this.rightLegGfx.rotation = 0;
    this.rightLegGfx.y = 0;
    this.leftArmGfx.rotation = 0;
    this.rightArmGfx.rotation = 0;
    this.bodyGfx.y = 0;
    this.chestGfx.y = 0;
    this.headGfx.y = 0;
    this.earsGfx.y = 0;
    this.eyesGfx.y = 0;
    this.mouthGfx.y = 0;
    this.antennaGfx.rotation = 0;
    this.accessoriesContainer.y = 0;
    this.characterContainer.scale.y = 1;
    this.isBouncing = true;
    this.setEyeState('normal');

    if (this.showShadow && this.shadowGfx) {
      this.shadowGfx.y = 0;
      this.shadowGfx.scale.set(1);
      this.shadowGfx.alpha = 1;
    }
  }

  public update(deltaSeconds: number): void {
    if (this.destroyed || !this.headGfx) return;
    const s = this.scaleFactor;
    const dt = Math.max(0, deltaSeconds);

    this.animTimer += dt;
    this.blinkTimer += dt;

    // 1. Natural eye blinking
    if (this.blinkTimer > 3.4 && !this.isHopping && this.eyeState === 'normal') {
      this.setEyeState('blink');
      setTimeout(() => {
        if (!this.destroyed && this.eyeState === 'blink') {
          this.setEyeState('normal');
        }
      }, 130);
      this.blinkTimer = 0;
    }

    // 2. Active walk interpolation
    if (this.isWalking) {
      this.moveElapsed += dt;
      const t = Math.min(1, this.moveElapsed / this.moveDuration);

      this.x = this.startX + (this.targetX - this.startX) * t;
      this.y = this.startY + (this.targetY - this.startY) * t;

      const stepCycle = Math.sin(t * Math.PI * 6);
      this.leftLegGfx.rotation = stepCycle * 0.32;
      this.rightLegGfx.rotation = -stepCycle * 0.32;
      this.leftArmGfx.rotation = -stepCycle * 0.24;
      this.rightArmGfx.rotation = stepCycle * 0.24;

      const stepBob = Math.abs(Math.sin(t * Math.PI * 6)) * 4 * s;
      this.headGfx.y = -stepBob * 0.5;
      this.earsGfx.y = -stepBob * 0.5;
      this.eyesGfx.y = -stepBob * 0.5;
      this.mouthGfx.y = -stepBob * 0.5;
      this.accessoriesContainer.y = -stepBob * 0.5;
      this.bodyGfx.y = -stepBob * 0.3;
      this.chestGfx.y = -stepBob * 0.3;

      if (t >= 1) {
        this.isWalking = false;
        this.x = this.targetX;
        this.y = this.targetY;
        this.resetLimbTransforms();
        if (this.onMoveComplete) {
          const cb = this.onMoveComplete;
          this.onMoveComplete = undefined;
          cb();
        }
      }
      return;
    }

    // 3. Active hop interpolation (parabolic vertical bounce arc + squash/stretch)
    if (this.isHopping) {
      this.moveElapsed += dt;
      const t = Math.min(1, this.moveElapsed / this.moveDuration);

      const curX = this.startX + (this.targetX - this.startX) * t;
      const curY = this.startY + (this.targetY - this.startY) * t;
      const hopHeight = 44 * s;
      const parabolicArc = -4 * hopHeight * t * (1 - t);

      this.x = curX;
      this.y = curY + parabolicArc;

      // Squash and stretch transitions
      if (t < 0.15) {
        const st = t / 0.15;
        this.characterContainer.scale.y = 1 - Math.sin(st * Math.PI) * 0.16;
      } else if (t < 0.85) {
        const st = (t - 0.15) / 0.7;
        this.characterContainer.scale.y = 1 + Math.sin(st * Math.PI) * 0.14;
        this.leftLegGfx.y = -4 * s * Math.sin(st * Math.PI);
        this.rightLegGfx.y = -4 * s * Math.sin(st * Math.PI);
        this.leftArmGfx.rotation = -0.3;
        this.rightArmGfx.rotation = 0.3;
      } else {
        const st = (t - 0.85) / 0.15;
        this.characterContainer.scale.y = 1 - Math.sin(st * Math.PI) * 0.18;
        this.leftLegGfx.y = 0;
        this.rightLegGfx.y = 0;
        this.leftArmGfx.rotation = 0;
        this.rightArmGfx.rotation = 0;
      }

      // Ground shadow tracking
      if (this.showShadow && this.shadowGfx) {
        this.shadowGfx.y = -parabolicArc;
        const shadowFactor = 1 - 0.45 * (4 * t * (1 - t));
        this.shadowGfx.scale.set(shadowFactor);
        this.shadowGfx.alpha = Math.max(0.1, 1 - 0.5 * (4 * t * (1 - t)));
      }

      if (t >= 1) {
        this.isHopping = false;
        this.x = this.targetX;
        this.y = this.targetY;
        this.resetLimbTransforms();
        if (this.onMoveComplete) {
          const cb = this.onMoveComplete;
          this.onMoveComplete = undefined;
          cb();
        }
      }
      return;
    }

    // 4. Idle breathing & continuous bobbing
    if (this.animateIdle && this.isBouncing) {
      const bob = Math.sin(this.animTimer * this.bounceSpeed) * 3.2 * s;
      this.headGfx.y = bob * 0.5;
      this.earsGfx.y = bob * 0.5;
      this.eyesGfx.y = bob * 0.5;
      this.mouthGfx.y = bob * 0.5;
      this.accessoriesContainer.y = bob * 0.5;

      this.antennaGfx.rotation = Math.sin(this.animTimer * 2.6) * 0.08;
      this.leftArmGfx.rotation = Math.sin(this.animTimer * 2.2) * 0.08;
      this.rightArmGfx.rotation = -Math.sin(this.animTimer * 2.2) * 0.08;

      this.squashFactor = 1 + Math.sin(this.animTimer * this.bounceSpeed) * 0.025;
      this.characterContainer.scale.y = this.squashFactor;

      // Companion gentle idle floating
      if (this.companionGfx) {
        this.companionGfx.y = Math.sin(this.animTimer * 3.0 + 1.2) * 3.5 * s;
        this.companionGfx.rotation = Math.sin(this.animTimer * 2.0) * 0.04;
      }

      // Back layer gentle motion
      if (this.backLayerGfx) {
        this.backLayerGfx.rotation = Math.sin(this.animTimer * 3.2) * 0.03;
      }
    }
  }

  public setEyeState(state: 'normal' | 'happy' | 'blink' | 'surprised'): void {
    if (this.destroyed) return;
    this.eyeState = state;
    this.renderFace();
  }

  public doHappyJump(): void {
    if (this.destroyed) return;
    this.setEyeState('happy');
    const startY = this.y;
    let elapsed = 0;
    const duration = 0.48;
    this.isBouncing = false;

    const scheduleFrame = (cb: () => void) => {
      if (typeof requestAnimationFrame !== 'undefined') {
        requestAnimationFrame(cb);
      } else if (typeof window !== 'undefined' && (window as any).requestAnimationFrame) {
        (window as any).requestAnimationFrame(cb);
      } else {
        setTimeout(cb, 16);
      }
    };

    const anim = () => {
      if (this.destroyed || !this.leftArmGfx) return;
      elapsed += 0.03;
      const progress = elapsed / duration;
      if (progress < 1) {
        const arc = -Math.sin(progress * Math.PI) * 42 * this.scaleFactor;
        this.y = startY + arc;
        this.characterContainer.rotation = Math.sin(progress * Math.PI * 2) * 0.15;
        this.leftArmGfx.rotation = -0.45;
        this.rightArmGfx.rotation = 0.45;
        if (this.showShadow && this.shadowGfx) {
          this.shadowGfx.y = -arc;
          this.shadowGfx.scale.set(1 - 0.4 * Math.sin(progress * Math.PI));
        }
        scheduleFrame(anim);
      } else {
        this.y = startY;
        this.characterContainer.rotation = 0;
        this.resetLimbTransforms();
      }
    };
    anim();
  }

  public doErrorShake(): void {
    if (this.destroyed) return;
    this.setEyeState('surprised');
    const startX = this.x;
    let count = 0;
    const interval = setInterval(() => {
      if (this.destroyed) {
        clearInterval(interval);
        return;
      }
      count++;
      this.x = startX + (count % 2 === 0 ? 8 : -8) * this.scaleFactor;
      if (count > 6) {
        clearInterval(interval);
        if (!this.destroyed) {
          this.x = startX;
          this.setEyeState('normal');
        }
      }
    }, 40);
  }
}
